function circuitById(id) {
  return CIRCUITS.find((c) => c.id === id);
}

function circuitProfileLabel(circuit) {
  if (circuit.downforce >= 0.68) return "High downforce";
  if (circuit.downforce <= 0.42) return "Low downforce";
  return "Balanced";
}

const SETUP_LABELS = { speed: "Speed", neutral: "Neutral", aero: "Aero" };
const SETUP_MATCH = { speed: "Low downforce", neutral: "Balanced", aero: "High downforce" };

// The setup that actually suits this circuit — our engineer's recommendation.
function recommendedSetup(circuit) {
  const profile = circuitProfileLabel(circuit);
  return Object.keys(SETUP_MATCH).find((k) => SETUP_MATCH[k] === profile) || "neutral";
}

// Net pace effect of a setup choice: a good match is a real bonus, picking
// the exact opposite extreme (Speed at a high-downforce track, or vice
// versa) is a heavy malus, and a middling mismatch (Neutral at an extreme
// track, or an extreme setup at a Balanced track) costs a bit less.
function setupBonus(setup, circuit) {
  if (!setup) return 0;
  const profile = circuitProfileLabel(circuit);
  if (SETUP_MATCH[setup] === profile) return 0.9;
  const isOpposite = (setup === "speed" && profile === "High downforce") || (setup === "aero" && profile === "Low downforce");
  return isOpposite ? -1.4 : -0.5;
}

// AI teams don't always get the setup call right — most of the time they
// follow the obvious read for the circuit, but a wrong guess happens often
// enough to matter, which is exactly what makes nailing your own call worth
// something.
function chooseAiSetup(circuit) {
  const correct = recommendedSetup(circuit);
  if (Math.random() < 0.72) return correct;
  const options = Object.keys(SETUP_MATCH).filter((s) => s !== correct);
  return options[Math.floor(Math.random() * options.length)];
}

// Our strategist's starting-tyre recommendation, based on what we know about
// the circuit before a wheel has turned: rain risk, incident risk, and how
// tyre-friendly the layout tends to be. If a practice session ran, its
// degradation reading (which may be wrong — see runPracticeSession) gets
// folded into the note as supporting context.
function strategistTireAdvice(circuit, practiceReport) {
  let result;
  if (circuit.rainRisk >= 1.2) {
    result = { compound: "MEDIUM", note: `Rain risk is elevated at ${circuit.name} — we'd start on Mediums to keep our options open if the weather turns.` };
  } else if (circuit.incidentRisk >= 1.3) {
    result = { compound: "MEDIUM", note: `This circuit sees a lot of incidents — Mediums give us the flexibility to react to a Safety Car without needing an early stop.` };
  } else if (circuit.downforce >= 0.7) {
    result = { compound: "SOFT", note: `High-downforce, technical layout — Softs should survive the opening stint and we can use the extra grip to build track position.` };
  } else if (circuit.downforce <= 0.35) {
    result = { compound: "HARD", note: `Long straights put a lot of energy through the tyres under braking — we'd rather start on Hards and keep our stops to a minimum.` };
  } else {
    result = { compound: "MEDIUM", note: `A balanced circuit with nothing extreme to plan around — Mediums are the safe, flexible opener.` };
  }

  if (practiceReport) {
    const reading = practiceReport.readings.find((r) => r.compound === result.compound);
    if (reading) {
      result = { ...result, note: `${result.note} Practice suggests the ${COMPOUNDS[result.compound].label} should be good for around ${reading.predictedCliff} laps before it falls off a cliff.` };
    }
  }
  return result;
}

// Free Practice: a short representative run to gauge tyre degradation before
// qualifying. Most of the time this is solid data — but traffic, a red flag,
// or an unrepresentative track state can leave the team with a confidently
// wrong read, and there's no in-game flag telling the player which one they
// got. That's the point: practice data is a strong hint, not a guarantee.
function runPracticeSession() {
  const roll = Math.random();
  let quality, flavor;
  if (roll < 0.6) {
    quality = "clean";
    flavor = "A clean, representative session — good long-run data on every compound.";
  } else if (roll < 0.85) {
    quality = "limited";
    flavor = "Traffic and a red flag cut our long-run data short — treat these numbers as a rough guide.";
  } else {
    quality = "compromised";
    flavor = "Consistent long runs all session, no issues to report.";
  }

  const compounds = ["SOFT", "MEDIUM", "HARD"];
  const readings = compounds.map((key) => {
    const trueCliff = COMPOUNDS[key].cliffAge;
    let noise = 0;
    if (quality === "limited") noise = (Math.random() - 0.5) * 7;
    // A compromised session reads confidently OPTIMISTIC — tyres look like
    // they'll go longer than they really will, which is exactly the trap
    // that leads to overstaying a stint into a nasty cliff in the race.
    if (quality === "compromised") noise = 3 + Math.random() * 9;
    return { compound: key, predictedCliff: Math.max(4, Math.round(trueCliff + noise)) };
  });

  return { quality, flavor, readings };
}

/* ============================== HELPERS ============================== */

function fmtLap(sec) {
  if (sec == null || !isFinite(sec)) return "--:--.---";
  const m = Math.floor(sec / 60);
  const s = sec - m * 60;
  return `${m}:${s.toFixed(3).padStart(6, "0")}`;
}

function fmtGap(deltaLaps, deltaSeconds) {
  if (deltaLaps <= 0.0005) return "Leader";
  if (deltaLaps >= 1) {
    const laps = Math.floor(deltaLaps);
    return `+${laps} LAP${laps > 1 ? "S" : ""}`;
  }
  return `+${deltaSeconds.toFixed(1)}s`;
}

function seeded(id, salt) {
  const x = Math.sin(id * 999 + salt * 137.7) * 10000;
  return x - Math.floor(x);
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function easeInOutQuad(t) {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}

function quadBezier(p0, p1, p2, t) {
  const u = 1 - t;
  return { x: u * u * p0.x + 2 * u * t * p1.x + t * t * p2.x, y: u * u * p0.y + 2 * u * t * p1.y + t * t * p2.y };
}

function curvedWaypoint(p0, p2) {
  const dx = p2.x - p0.x;
  const dy = p2.y - p0.y;
  return { x: (p0.x + p2.x) / 2 - dy * 0.28, y: (p0.y + p2.y) / 2 + dx * 0.28 };
}

// Pit crew skill shifts the odds toward clean stops and shaves a little off
// the baseline time — level 0.5 matches the old fixed tuning (used for every
// AI team, since only the player invests in staff).
function rollPitLoss(carId, pitCount, crewLevel = 0.5) {
  const roll = seeded(carId, pitCount * 7 + 3);
  const span = seeded(carId, pitCount * 7 + 9);
  const cleanCut = 0.55 + crewLevel * 0.35;
  const slowCut = 0.85 + crewLevel * 0.12;
  const timeOff = crewLevel * 2;
  if (roll < cleanCut) return { loss: 18 - timeOff + span * 2, tier: "clean" };
  if (roll < slowCut) return { loss: 20 - timeOff + span * 2.5, tier: "slow" };
  return { loss: 23 - timeOff + span * 5, tier: "botched" };
}

// Generates one driver candidate with two stats — Pace (skill) and
// Consistency — and a price derived from both, so a fast-but-erratic
// rookie can be cheaper than a slower, ultra-reliable veteran.
function generateDriverCandidate(usedNames, skillRange) {
  const available = DRIVER_NAME_POOL.filter((n) => !usedNames.includes(n));
  const name = available.length
    ? available[Math.floor(Math.random() * available.length)]
    : `Driver ${Math.floor(100 + Math.random() * 900)}`;
  const [minSkill, maxSkill] = skillRange || [0.32, 0.92];
  const skill = minSkill + Math.random() * (maxSkill - minSkill);
  const consistency = 0.30 + Math.random() * 0.65;
  const age = 19 + Math.floor(Math.random() * 20);
  const price = Math.round(30 + skill * 180 + consistency * 55);
  return { id: `drv_${Math.random().toString(36).slice(2, 9)}`, name, skill, consistency, age, price };
}

// A team's tier caps who it can realistically sign — a shoestring New Team
// simply doesn't have the budget or reputation to attract proven talent, so
// its market pool is drawn from a visibly lower skill band than a Top Team's.
function generateMarketPool(count, usedNames, skillRange) {
  const pool = [];
  const taken = [...usedNames];
  for (let i = 0; i < count; i++) {
    const d = generateDriverCandidate(taken, skillRange);
    taken.push(d.name);
    pool.push(d);
  }
  return pool.sort((a, b) => b.skill - a.skill);
}

function getTierSkillRange(tierId) {
  const tier = TEAM_TIERS.find((t) => t.id === tierId);
  return tier ? tier.driverSkillRange : [0.32, 0.92];
}

// AI teams field a fixed pair of drivers for the whole game — their skill
// loosely tracks the team's own competitiveness, so front-running teams
// tend to have stronger line-ups (with some variance).
function generateAiRosters() {
  const rosters = {};
  const usedNames = [];
  TEAMS.forEach((team) => {
    if (team.isPlayer) return;
    const drivers = [];
    for (let i = 0; i < 2; i++) {
      const skill = Math.min(0.95, Math.max(0.32, team.perf * 0.55 + 0.22 + (Math.random() - 0.5) * 0.3));
      const consistency = 0.30 + Math.random() * 0.6;
      const age = 19 + Math.floor(Math.random() * 20);
      const available = DRIVER_NAME_POOL.filter((n) => !usedNames.includes(n));
      const name = available[Math.floor(Math.random() * available.length)] || `Driver ${team.id}-${i}`;
      usedNames.push(name);
      drivers.push({ id: `ai_${team.id}_${i}`, name, skill, consistency, age, price: 0 });
    }
    rosters[team.id] = drivers;
  });
  return rosters;
}

// One season of career progression for a single driver: young drivers
// improve as they gain experience, drivers in their prime hold steady with
// small consistency gains, and veterans past their mid-30s start to fade.
function ageDriver(driver) {
  const age = (driver.age ?? 24) + 1;
  let skill = driver.skill;
  let consistency = driver.consistency;
  if (age < 25) {
    skill = Math.min(0.97, skill + 0.02 + Math.random() * 0.02);
    consistency = Math.min(0.95, consistency + 0.015 + Math.random() * 0.015);
  } else if (age <= 32) {
    skill = Math.min(0.97, Math.max(0.2, skill + (Math.random() - 0.4) * 0.01));
    consistency = Math.min(0.95, consistency + 0.005 + Math.random() * 0.01);
  } else {
    const decline = (age - 32) * 0.006;
    skill = Math.max(0.2, skill - decline - Math.random() * 0.01);
    consistency = Math.max(0.2, consistency - decline * 0.6);
  }
  return { ...driver, age, skill, consistency };
}

// End-of-season driver market movement for AI teams: most drivers stay and
// age normally, but there's a rising chance of a seat changing hands as a
// driver gets older — simulating retirements and teams chasing younger
// talent, the same pressure the player feels with their own contracts.
function evolveAiRosters(aiRosters, teamPerf) {
  const next = {};
  const usedNames = Object.values(aiRosters).flat().map((d) => d.name);
  const news = [];
  TEAMS.forEach((team) => {
    if (team.isPlayer) return;
    next[team.id] = aiRosters[team.id].map((d) => {
      const changeChance = 0.16 + Math.max(0, (d.age ?? 24) - 33) * 0.025;
      if (Math.random() < changeChance) {
        const perf = teamPerf[team.id] ?? team.perf;
        const skill = Math.min(0.95, Math.max(0.3, perf * 0.55 + 0.22 + (Math.random() - 0.5) * 0.3));
        const consistency = 0.3 + Math.random() * 0.6;
        const age = 19 + Math.floor(Math.random() * 8);
        const available = DRIVER_NAME_POOL.filter((n) => !usedNames.includes(n));
        const name = available[Math.floor(Math.random() * available.length)] || `Driver ${team.id}`;
        usedNames.push(name);
        news.push(`${team.name} signs ${name} (age ${age}) as ${d.name} departs.`);
        return { id: `ai_${team.id}_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`, name, skill, consistency, age, price: 0 };
      }
      return ageDriver(d);
    });
  });
  return { rosters: next, news };
}

// Day-form: rolled once per driver every race weekend. Positive form makes the
// car quicker, negative slows it, neutral changes nothing. Value is in
// [-1, 1]; FORM_PACE_SEC is the lap-time swing at the extremes.
const FORM_PACE_SEC = 0.4;
function rollDriverForm() {
  const r = Math.random();
  const mag = 0.35 + Math.random() * 0.65;
  if (r < 0.3) return mag;
  if (r < 0.7) return 0;
  return -mag;
}
function rollWeekendForm(count) {
  const map = {};
  for (let i = 0; i < count; i++) map[i] = rollDriverForm();
  return map;
}
function formInfo(v = 0) {
  if (v >= 0.7) return { label: "On fire", tone: "up", icon: "▲▲" };
  if (v > 0) return { label: "Good form", tone: "up", icon: "▲" };
  if (v === 0) return { label: "Neutral", tone: "flat", icon: "●" };
  if (v > -0.7) return { label: "Off form", tone: "down", icon: "▼" };
  return { label: "Struggling", tone: "down", icon: "▼▼" };
}
function FormBadge({ value, showEffect }) {
  const info = formInfo(value);
  const sec = Math.abs(value * FORM_PACE_SEC);
  return (
    <span className={`pw-form pw-form-${info.tone}`} title={value === 0 ? "No effect on pace" : `${value > 0 ? "-" : "+"}${sec.toFixed(2)}s per lap`}>
      {info.icon} {info.label}
      {showEffect && value !== 0 && <span className="pw-form-fx"> {value > 0 ? "-" : "+"}{sec.toFixed(2)}s/lap</span>}
    </span>
  );
}

// Builds the 12-car qualifying/race roster from the currently-signed
// drivers — the player's two contracted seats plus every AI team's fixed
// pair — instead of rerolling random names every race.
function buildRosterFromSeason(season, formMap = {}) {
  const roster = [];
  let idx = 0;
  TEAMS.forEach((team) => {
    const drivers = team.isPlayer ? season.playerDrivers : season.aiRosters[team.id];
    drivers.forEach((d) => {
      roster.push({ id: idx, number: idx + 1, name: d.name, teamId: team.id, team, skill: d.skill, consistency: d.consistency, form: formMap[idx] ?? 0 });
      idx++;
    });
  });
  return roster;
}

// Each AI car gets a fresh strategic personality for the weekend, so the
// field spreads its stops out over different windows instead of everyone
// following the same schedule.
function pickStrategyStyle() {
  const r = Math.random();
  if (r < 0.35) return "aggressive";
  if (r < 0.8) return "balanced";
  return "conservative";
}

function stintTargetForStyle(style) {
  if (style === "aggressive") return 13 + Math.round(Math.random() * 8); // short, sharp stints
  if (style === "conservative") return 25 + Math.round(Math.random() * 13); // stretch it, fewer stops
  return 17 + Math.round(Math.random() * 12); // balanced middle ground
}

function compoundPoolForStyle(style, lapsRemaining, pitCount) {
  if (style === "aggressive") return lapsRemaining < 16 ? ["SOFT"] : ["SOFT", "MEDIUM"];
  if (style === "conservative") return ["MEDIUM", "HARD"];
  return lapsRemaining < 14 && pitCount >= 1 ? ["SOFT", "MEDIUM"] : ["MEDIUM", "HARD"];
}

// Each team picks its own starting compound for the grid — weather and
// incident risk override everything (nobody gambles on a dry-only tyre if
// rain is likely), but otherwise an aggressive team gambles on Softs for
// track position, a conservative one protects itself on Hards, and a
// balanced team just follows the sensible circuit-based read.
function chooseAiStartCompound(style, circuit, advice) {
  if (circuit.rainRisk >= 1.2 || circuit.incidentRisk >= 1.3) return advice.compound;
  if (style === "aggressive") return "SOFT";
  if (style === "conservative") return "HARD";
  return advice.compound;
}

// The actual launch off the line — separate from the small track-position
// penalty of starting further back. A skilled, consistent driver reacts
// close to the lights reliably; a shakier one can nail a great start just as
// easily as fluffing it, and there's always a small chance of a real stall.
function computeStartDelta(entry) {
  const consistency = entry.consistency ?? 0.55;
  const skill = entry.skill ?? 0.55;
  const form = entry.form ?? 0;
  const stallChance = Math.max(0.005, (0.045 - consistency * 0.03) * (1 - form * 0.5));
  if (Math.random() < stallChance) {
    return 2.4 + Math.random() * 2.6; // bogs down / nearly stalls
  }
  const base = (1 - skill) * 0.6 - 0.15 - form * 0.3;
  const variance = (1.2 - consistency * 0.8) * (Math.random() - 0.5) * 1.4;
  return base + variance;
}

function carFromRoster(entry, baseLap, gridPosition, startCompound = "MEDIUM", strategyStyle, setup = "neutral", circuit = null, startEngineMode = "standard") {
  const trackPenalty = (gridPosition - 1) * 0.45;
  const startDelta = computeStartDelta(entry);
  const style = strategyStyle || (entry.team.isPlayer ? "balanced" : pickStrategyStyle());
  const setupEffect = circuit ? setupBonus(setup, circuit) : 0;
  return {
    id: entry.id,
    number: entry.number,
    name: entry.name,
    teamId: entry.teamId,
    team: entry.team,
    skill: entry.skill,
    form: entry.form ?? 0,
    consistency: entry.consistency ?? 0.55,
    gridPosition,
    startDelta,
    strategyStyle: style,
    setup,
    engineMode: startEngineMode,
    compound: startCompound,
    tireAge: 0,
    pitQueued: false,
    pendingCompound: null,
    pendingPitLoss: AVG_PIT_LOSS,
    pit: null, // live pit stop clock while the car is in the lane
    spinPenalty: 0,
    limitStrikes: 0,
    penaltySec: 0,
    forcedPit: false,
    inPit: false,
    pitCount: 0,
    lapsCompleted: 0,
    timeInLap: 0,
    currentLapTarget: baseLap + trackPenalty + startDelta - setupEffect - (entry.form ?? 0) * FORM_PACE_SEC,
    raceTime: 0,
    lapHistory: [],
    status: "running",
    lastLapTime: null,
    stintTargetLaps: stintTargetForStyle(style),
  };
}

function computeQualiTime(entry, circuit, playerDev, teamPerf, setup) {
  const basePerf = teamPerf[entry.teamId] ?? entry.team.perf;
  let t = circuit.baseLap;
  t -= basePerf * 3.0;
  t -= entry.skill * 1.6;
  t -= (entry.form ?? 0) * FORM_PACE_SEC;
  t += COMPOUNDS.SOFT.paceDelta;
  const affinity = entry.team.downforceAffinity ?? 0;
  t -= affinity * (circuit.downforce - 0.5) * 3.2;
  t -= setupBonus(setup, circuit);
  if (entry.team.isPlayer) {
    const bonus = getPlayerDevBonus(playerDev, circuit);
    t -= bonus.paceBonus;
  }
  t += (Math.random() - 0.5) * 0.9 * (1.3 - (entry.consistency ?? 0.55) * 0.6);
  return Math.max(t, circuit.baseLap * 0.66);
}

function getPlayerDevBonus(playerDev, circuit) {
  const aeroGain = playerDev.aero * circuit.downforce * 2.4;
  const engineGain = playerDev.engine * (1 - circuit.downforce) * 2.4;
  const chassisGain = playerDev.chassis * 0.6;
  return {
    paceBonus: aeroGain + engineGain + chassisGain,
    degReduction: playerDev.chassis * 0.35,
  };
}

function computeLapTarget(car, trackCondition, circuit, playerDev, teamPerf, cautionSectors, gapAhead) {
  const compound = COMPOUNDS[car.compound];
  const mode = ENGINE_MODES[car.engineMode];

  const basePerf = teamPerf[car.teamId] ?? car.team.perf;

  let t = circuit.baseLap;
  t -= basePerf * 3.0;
  t -= car.skill * 1.4;
  t -= (car.form ?? 0) * FORM_PACE_SEC;
  t += compound.paceDelta;

  // Every car concept suits some tracks better than others — a low-drag,
  // engine-focused car shines on the straights, a high-downforce design
  // shines through technical, high-downforce circuits.
  const affinity = car.team.downforceAffinity ?? 0;
  t -= affinity * (circuit.downforce - 0.5) * 3.2;

  // The weekend's setup choice (Speed / Neutral / Aero) is a separate call
  // from the car's underlying concept — picked after practice, it rewards
  // reading the circuit correctly and punishes guessing wrong.
  t -= setupBonus(car.setup, circuit);

  let degMult = mode.degMult;
  if (car.team.isPlayer) {
    const bonus = getPlayerDevBonus(playerDev, circuit);
    t -= bonus.paceBonus;
    degMult = mode.degMult * (1 - bonus.degReduction);
  }

  const age = car.tireAge;
  const linearDeg = compound.degRate * age * degMult;
  const overCliff = Math.max(0, age - compound.cliffAge);
  const cliffDeg = compound.cliffMult * overCliff * overCliff * degMult;
  t += linearDeg + cliffDeg;

  t += mode.paceDelta;
  t -= Math.min(car.lapsCompleted, circuit.laps) * 0.028;

  const wetTire = !!compound.wet;
  if (trackCondition === "wet" && !wetTire) t += 14 + Math.random() * 3;
  else if (trackCondition === "damp" && car.compound !== "INTER") t += car.compound === "WET" ? 3 : 6;
  else if (trackCondition === "dry" && wetTire) t += car.compound === "WET" ? 9 : 4;

  // Slipstream vs dirty air: running close behind another car gives a tow
  // on low-downforce, high-speed circuits (net gain), but costs grip through
  // corners on high-downforce circuits (net loss) — which is exactly why
  // some tracks are famous for overtaking and others are a defensive parade.
  t += draftDirtyAirEffect(gapAhead, circuit);

  t += (Math.random() - 0.5) * 0.35;
  const normalPace = Math.max(t, circuit.baseLap * 0.68);

  // Yellow flags are local to a single sector: only the fraction of the lap
  // spent inside a cautioned sector is slowed, blended in proportionally.
  // This is computed the same way whether the car is pitting or not, so a
  // pit stop never lets a car dodge a sector's yellow-flag penalty.
  const cautionedCount = cautionSectors ? cautionSectors.filter(Boolean).length : 0;
  // Yellow flags are no longer baked into the lap target: they slow a car only
  // while it is physically inside the flagged sector (see the race tick).
  if (false && cautionedCount > 0) {
    const cautionFullLapPace = circuit.baseLap * 1.42 + (Math.random() - 0.5) * 2.2;
    const frac = cautionedCount / 3;
    return normalPace * (1 - frac) + cautionFullLapPace * frac;
  }
  return normalPace;
}

// Net seconds added (positive) or gained (negative) from running close
// behind another car. Only meaningful within ~2s of the car ahead.
// How easy it is to pass on this circuit: long straights / low downforce make
// it much easier than a tight, high-downforce layout.
function circuitOvertakeEase(circuit) {
  return circuit.overtake ?? 0.25 + (1 - circuit.downforce) * 0.6;
}

// Chance that a faster car sitting right behind another one actually gets the
// move done this lap. Pace advantage matters most, then driver skill and form,
// tyre age difference and how passable the circuit is.
function passSuccessChance(attacker, defender, advantage, gap, circuit) {
  const skillEdge = (attacker.skill - defender.skill) * 0.5 + ((attacker.form ?? 0) - (defender.form ?? 0)) * 0.08;
  const tyreEdge = Math.max(-0.1, Math.min(0.15, (defender.tireAge - attacker.tireAge) * 0.006));
  let p = 0.1 + advantage * 0.55 + circuitOvertakeEase(circuit) * 0.3 + skillEdge + tyreEdge;
  if (gap > 0.4) p *= 0.7; // not close enough to get a run
  return Math.max(0.06, Math.min(0.95, p));
}

function draftDirtyAirEffect(gapAhead, circuit) {
  if (gapAhead == null || !isFinite(gapAhead) || gapAhead > 2.0 || gapAhead < 0) return 0;
  const closeness = 1 - gapAhead / 2.0; // 0 (2s back) .. 1 (right on their gearbox)
  const draftBonus = closeness * (1 - circuit.downforce) * 1.8;
  const dirtyAirPenalty = closeness * circuit.downforce * 1.4;
  return dirtyAirPenalty - draftBonus;
}

function decideAiPit(car, condition, lapsRemaining, caution, context = {}) {
  if (car.pitQueued || car.inPit) return null;
  const compound = COMPOUNDS[car.compound];
  const mismatched =
    (condition === "wet" && !compound.wet) ||
    (condition === "dry" && compound.wet) ||
    (condition === "damp" && car.compound === "SOFT" && car.tireAge > 4);

  if (mismatched) {
    if (condition === "wet") return "WET";
    if (condition === "damp") return "INTER";
    return "MEDIUM";
  }

  if (lapsRemaining <= 3) return null;

  const { rivalBehindPitted, leading } = context;
  const style = car.strategyStyle || "balanced";

  if (rivalBehindPitted && car.tireAge >= car.stintTargetLaps * 0.55) {
    return pickCompound(car, compoundPoolForStyle(style, lapsRemaining, car.pitCount));
  }

  const jitter = (seeded(car.id, car.pitCount + 11) - 0.5) * 6;
  const cautionBonus = caution ? 8 : 0;
  const leadBonus = leading ? 4 : 0;
  if (car.tireAge >= car.stintTargetLaps - cautionBonus + leadBonus + jitter) {
    return pickCompound(car, compoundPoolForStyle(style, lapsRemaining, car.pitCount));
  }
  return null;
}

// ---- Pit lane geometry/timing shared by the simulation and the renderer.
// The lane peels off the track at 95% of a lap, runs past the garages (the
// timing line is crossed inside the lane) and rejoins at 105% of the lap.
const PIT_ENTRY_FRAC = 0.95;
const PIT_LANE_SPAN = 0.1;
const pitSlotBase = (teamIdx) => 0.24 + 0.52 * ((teamIdx + 0.5) / TEAMS.length);
function pitSlotFor(car) {
  const teamIdx = Math.max(0, TEAMS.findIndex((t) => t.id === car.teamId));
  const mateShift = (car.id % 2 === 0 ? -1 : 1) * 0.012;
  return Math.min(0.9, Math.max(0.1, pitSlotBase(teamIdx) + mateShift));
}
// Where the car is along the lane (u: 0 = entry, 1 = exit) and whether it is
// standing still in its box, from the stop's own clock (pit.t, seconds).
function pitProfile(car) {
  const pit = car.pit;
  if (!pit) return null;
  const slotU = pitSlotFor(car);
  const { t, D, tr } = pit;
  if (t < tr) return { u: slotU * easeInOutQuad(Math.max(0, t) / tr), stopped: false, stopElapsed: 0 };
  if (t < D - tr) return { u: slotU, stopped: true, stopElapsed: t - tr };
  return { u: slotU + (1 - slotU) * easeInOutQuad(Math.min(1, (t - (D - tr)) / tr)), stopped: false, stopElapsed: 0 };
}

function pickCompound(car, pool) {
  const varied = pool.filter((p) => p !== car.compound);
  const finalPool = varied.length ? varied : pool;
  return finalPool[Math.floor(seeded(car.id, car.pitCount + 3) * finalPool.length)];
}

// AI engine mode choice: nurse worn tyres near their cliff, otherwise mix in
// some Push laps for aggressive strategies or just for unpredictability.
function decideAiEngineMode(car) {
  const cliffAge = COMPOUNDS[car.compound].cliffAge;
  if (car.tireAge >= cliffAge - 3) return "save";
  if (car.strategyStyle === "aggressive" && car.tireAge < 6) return "push";
  if (car.strategyStyle === "conservative") return "standard";
  const roll = seeded(car.id, car.lapsCompleted * 17 + 41);
  if (roll < 0.15) return "push";
  if (roll < 0.3) return "save";
  return "standard";
}

// Development costs both R&D points (from race results) and hard cash
// (from the team budget) — both rise as a stat approaches its cap, so late
// gains get progressively more expensive on both fronts. Steep enough that
// climbing from a weak starting car to the front realistically takes several
// seasons of sustained investment, not one lucky year. A strong Technical
// Director trims both costs, up to 30% off at max level.
function devCost(level, technicalDirector = 0) {
  const discount = 1 - Math.min(technicalDirector, 1) * 0.3;
  return {
    points: Math.round((16 + level * 72) * discount),
    money: Math.round((26 + level * 105) * discount),
  };
}

// Staff investment — a Pit Crew Chief and a Technical Director, each 0-1.
// Costs money only (personnel, not R&D) and rises with level like everything
// else here.
function staffCost(level) {
  return Math.round(70 + level * 210);
}

// Sponsors: at the start of every season three fictional backers make an
// offer — a safe one that pays up front, a balanced one, and a bold one that
// pays nothing now but a lot if you deliver. Targets scale with the team tier.
const SPONSOR_NAMES = ["Norvik Logistics", "Helix Energy", "Aurelia Bank", "Kestrel Telecom", "Vantage Lubricants", "Orbis Software", "Ferrant Watches", "Tidewater Foods"];

function generateSponsorOffers(teamTierId) {
  const targets = {
    top: { rank: 3, bonus: 420, dp: 5, pod: 4 },
    midfield: { rank: 5, bonus: 320, dp: 3, pod: 2 },
    newteam: { rank: 7, bonus: 260, dp: 2, pod: 1 },
  };
  const t = targets[teamTierId] || targets.midfield;
  const names = shuffleArray(SPONSOR_NAMES).slice(0, 3);
  return [
    {
      id: "safe", sponsor: names[0], risk: "Low", type: "doublepoints", target: t.dp,
      upfront: Math.round(t.bonus * 0.55), bonus: Math.round(t.bonus * 0.5),
      description: `Score points with both cars in at least ${t.dp} races.`,
    },
    {
      id: "balanced", sponsor: names[1], risk: "Medium", type: "rank", target: t.rank, targetRank: t.rank,
      upfront: Math.round(t.bonus * 0.3), bonus: t.bonus,
      description: `Finish P${t.rank} or higher in the Constructors' Championship.`,
    },
    {
      id: "bold", sponsor: names[2], risk: "High", type: "podiums", target: t.pod,
      upfront: 0, bonus: Math.round(t.bonus * 2),
      description: `Take at least ${t.pod} podium finish${t.pod > 1 ? "es" : ""} this season.`,
    },
  ];
}

// Legacy saves hold the old single objective (rank only) — treat as rank.
function sponsorProgressText(obj, progress, currentRank) {
  const type = obj.type || "rank";
  if (type === "podiums") return `${progress?.podiums || 0}/${obj.target} podiums`;
  if (type === "doublepoints") return `${progress?.doublePoints || 0}/${obj.target} double-points finishes`;
  return currentRank > 0 ? `currently P${currentRank}` : "";
}

function resolveSponsor(obj, finalRank, progress) {
  const type = obj.type || "rank";
  let achieved;
  let text;
  if (type === "podiums") {
    achieved = (progress?.podiums || 0) >= obj.target;
    text = achieved ? `Podium target reached (${progress.podiums}/${obj.target}).` : `Only ${progress?.podiums || 0} of ${obj.target} podiums.`;
  } else if (type === "doublepoints") {
    achieved = (progress?.doublePoints || 0) >= obj.target;
    text = achieved ? `Double-points target reached (${progress.doublePoints}/${obj.target}).` : `Only ${progress?.doublePoints || 0} of ${obj.target} double-points finishes.`;
  } else {
    const need = obj.targetRank ?? obj.target;
    achieved = finalRank > 0 && finalRank <= need;
    text = achieved ? `Finished P${finalRank} (needed P${need}).` : `Finished P${finalRank}, needed P${need} or higher.`;
  }
  return { achieved, resultText: text };
}

function aiDevelopmentTick(teamPerf, roundIndex) {
  const next = { ...teamPerf };
  TEAMS.forEach((team, i) => {
    if (team.isPlayer) return;
    const delta = (seeded(i * 7 + 1, roundIndex * 13 + 5) - 0.2) * 0.066 * (SETTINGS.aiDev || 1);
    const base = next[team.id] ?? team.perf;
    next[team.id] = Math.min(1.05, Math.max(0.3, base + delta));
  });
  return next;
}

function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function buildCalendar() {
  let ids = shuffleArray(CIRCUITS.map((c) => c.id));
  if (SETTINGS.seasonLength > 0) ids = ids.slice(0, SETTINGS.seasonLength);
  return ids.map((cid, i) => ({ round: i + 1, circuitId: cid, completed: false, playerResult: null }));
}

// A one-off swing applied to EVERY team (including the player's own
// baseline) at the start of a new season — simulating a winter of car
// development that some teams nail and others fumble. Kept modest and close
// to neutral so it can't act as a shortcut back to the front for a team
// that started weak — real progress has to come from sustained development.
function preseasonShuffle(teamPerf) {
  const next = { ...teamPerf };
  TEAMS.forEach((team) => {
    const delta = (Math.random() - 0.48) * 0.09;
    const base = next[team.id] ?? team.perf;
    next[team.id] = Math.min(1.08, Math.max(0.28, base + delta));
  });
  return next;
}

function makeInitialSeason() {
  const teamPerf = {};
  TEAMS.forEach((t) => (teamPerf[t.id] = t.perf));
  const aiRosters = generateAiRosters();
  const usedNames = Object.values(aiRosters).flat().map((d) => d.name);
  return {
    seasonNumber: 1,
    teamTierId: null, // set once the player picks Top / Midfield / New Team
    roundIndex: 0,
    calendar: buildCalendar(),
    driverPoints: {},
    constructorPoints: {},
    devPoints: 90,
    playerDev: { aero: 0.2, engine: 0.2, chassis: 0.2 },
    teamPerf,
    lastRacePerf: { ...teamPerf }, // snapshot used to report development gains/losses before each race
    raceHistory: [],
    budget: STARTING_BUDGET,
    staff: { pitCrew: 0.3, technicalDirector: 0.3 }, // rebalanced once a team tier is chosen
    sponsorObjective: null, // chosen from three offers at the start of every season
    sponsorProgress: { podiums: 0, doublePoints: 0 },
    aiRosters,
    transferNews: [], // driver market movement from the last off-season, shown on that screen
    playerDrivers: [], // filled in once the player signs their two drivers
    driverMarket: generateMarketPool(6, usedNames),
    needsTesting: true, // winter testing hasn't been shown for this season yet
    history: [], // one record per completed season (champions, player result)
    titles: {}, // driver name -> world titles won
    driverStats: {}, // driver name -> career wins / podiums / points…
    driverHistory: [], // cumulative driver points after each round (this season)
    board: { confidence: 60, objective: null, verdict: null, fired: false },
    pressLog: [],
  };
}

// Winter testing: a few days of pre-season running that gives the paddock
// its first real read on the competitive order, before a single point is on
// the line. Uses a neutral reference circuit (no downforce bias either way)
// so no team's aero/engine affinity skews the picture, plus each team's
// average driver pace and a little on-track noise.
function runWinterTesting(season) {
  const neutralCircuit = { baseLap: 90, downforce: 0.5 };
  return TEAMS.map((team) => {
    const perf = season.teamPerf[team.id] ?? team.perf;
    const drivers = (team.isPlayer ? season.playerDrivers : season.aiRosters[team.id]) || [];
    const avgSkill = drivers.length ? drivers.reduce((s, d) => s + d.skill, 0) / drivers.length : 0.55;
    let t = neutralCircuit.baseLap;
    t -= perf * 3.0;
    t -= avgSkill * 1.0;
    if (team.isPlayer) {
      t -= getPlayerDevBonus(season.playerDev, neutralCircuit).paceBonus;
    }
    t += (Math.random() - 0.5) * 0.6;
    return { team, time: t };
  }).sort((a, b) => a.time - b.time);
}

// Looks up which signed driver currently occupies a given car slot (0-11),
// for display purposes — slot->driver mapping stays fixed within a season.
function getDriverForSlot(season, slotId) {
  const teamIdx = Math.floor(slotId / 2);
  const team = TEAMS[teamIdx];
  const seatIdx = slotId % 2;
  const drivers = team.isPlayer ? season.playerDrivers : season.aiRosters[team.id];
  return drivers ? drivers[seatIdx] : null;
}

function computeStandings(carList, circuit, applyPenalties = false) {
  const running = carList.filter((c) => c.status !== "dnf");
  const dnf = carList.filter((c) => c.status === "dnf");

  const scored = running.map((c) => ({
    ...c,
    score:
      c.lapsCompleted +
      Math.min(c.timeInLap / Math.max(c.currentLapTarget, 1), 0.999) -
      (applyPenalties ? (c.penaltySec || 0) / Math.max(c.currentLapTarget, 1) : 0),
  }));
  scored.sort((a, b) => b.score - a.score);
  const leaderScore = scored[0]?.score ?? 0;
  const leaderPace = scored[0]?.currentLapTarget ?? (circuit ? circuit.baseLap : 90);

  const rankedRunning = scored.map((c) => ({
    ...c,
    gapLaps: leaderScore - c.score,
    gapSeconds: (leaderScore - c.score) * leaderPace,
  }));

  const rankedDnf = [...dnf]
    .sort((a, b) => b.lapsCompleted - a.lapsCompleted)
    .map((c) => ({ ...c, gapLaps: Infinity, gapSeconds: Infinity }));

  return [...rankedRunning, ...rankedDnf].map((c, i) => ({ ...c, position: i + 1 }));
}

const SAVE_KEY = "career-save-v1";

/* ---------- Local saves (named slots + JSON export/import) ---------- */

const SAVES_KEY = "pwm-saves-v1";
const SAVE_FORMAT = "pit-wall-manager";
const SAVE_VERSION = 1;

// Storage adapter: Claude's window.storage if present, else localStorage, else memory.
const memStore = {};
const storageAdapter = {
  async get(key) {
    try {
      if (typeof window !== "undefined" && window.storage && window.storage.get) {
        const r = await window.storage.get(key, false);
        return r && r.value != null ? r.value : null;
      }
    } catch (e) { /* fall through */ }
    try {
      if (typeof localStorage !== "undefined") return localStorage.getItem(key);
    } catch (e) { /* fall through */ }
    return key in memStore ? memStore[key] : null;
  },
  async set(key, value) {
    try {
      if (typeof window !== "undefined" && window.storage && window.storage.set) {
        await window.storage.set(key, value, false);
        return;
      }
    } catch (e) { /* fall through */ }
    try {
      if (typeof localStorage !== "undefined") { localStorage.setItem(key, value); return; }
    } catch (e) { /* fall through */ }
    memStore[key] = value;
  },
  async del(key) {
    try {
      if (typeof window !== "undefined" && window.storage && window.storage.delete) {
        await window.storage.delete(key, false);
        return;
      }
    } catch (e) { /* fall through */ }
    try {
      if (typeof localStorage !== "undefined") { localStorage.removeItem(key); return; }
    } catch (e) { /* fall through */ }
    delete memStore[key];
  },
};

function describeSeason(season) {
  if (!season || !season.teamTierId) return "Career not started";
  const tier = TEAM_TIERS.find((t) => t.id === season.teamTierId);
  const total = season.calendar ? season.calendar.length : 0;
  const done = Math.min(season.roundIndex || 0, total);
  return `${tier ? tier.name : "Team"} · Season ${season.seasonNumber || 1} · Round ${done}/${total} · ${season.budget ?? 0} cr`;
}

// Brings any saved season (autosave, named save, import) in line with the
// current TEAMS list: remaps legacy ids, drops unknown teams and fills in
// the ones that are missing so lookups never return undefined.
function normalizeSeason(raw) {
  const base = makeInitialSeason();
  const out = { ...base, ...raw };
  const ids = TEAMS.map((t) => t.id);
  const remap = (obj, make) => {
    const src = obj && typeof obj === "object" ? { ...obj } : {};
    if (src.falcon !== undefined && src.mclaren === undefined) src.mclaren = src.falcon;
    const res = {};
    ids.forEach((id) => { res[id] = src[id] !== undefined ? src[id] : make(id); });
    return res;
  };
  out.teamPerf = remap(raw.teamPerf, (id) => base.teamPerf[id]);
  out.lastRacePerf = remap(raw.lastRacePerf, (id) => out.teamPerf[id]);
  out.constructorPoints = remap(raw.constructorPoints, () => 0);
  const aiIds = ids.filter((id) => !TEAMS.find((t) => t.id === id).isPlayer);
  const rosters = {};
  aiIds.forEach((id) => {
    const r = raw.aiRosters && raw.aiRosters[id];
    rosters[id] = Array.isArray(r) && r.length >= 2 ? r : base.aiRosters[id];
  });
  out.aiRosters = rosters;
  if (!Array.isArray(out.playerDrivers)) out.playerDrivers = [];
  // Circuits renamed or removed since the save was made: map them onto a
  // current circuit (legacy equivalent first, otherwise one not yet on the
  // calendar) so every round resolves to a real track.
  if (Array.isArray(out.calendar)) {
    const LEGACY_CIRCUITS = { vallenroad: "silverstone", dunefire: "redbullring" };
    const valid = new Set(CIRCUITS.map((c) => c.id));
    const used = new Set(out.calendar.map((r) => r && r.circuitId).filter((id) => valid.has(id)));
    out.calendar = out.calendar.map((r, i) => {
      const round = r && typeof r === "object" ? { ...r } : { round: i + 1, completed: false, playerResult: null };
      if (!valid.has(round.circuitId)) {
        let id = LEGACY_CIRCUITS[round.circuitId];
        if (!id || used.has(id)) id = CIRCUITS.map((c) => c.id).find((cid) => !used.has(cid)) || CIRCUITS[0].id;
        used.add(id);
        round.circuitId = id;
      }
      return round;
    });
  }
  if (!out.teamTierId || !TEAM_TIERS.find((t) => t.id === out.teamTierId)) {
    if (out.teamTierId) out.teamTierId = null;
  }
  return out;
}

function isValidSeason(s) {
  return !!s && typeof s === "object" && Array.isArray(s.calendar) && typeof s.roundIndex === "number" &&
    s.constructorPoints && typeof s.constructorPoints === "object";
}

function buildExport(name, season, savedAt) {
  return { format: SAVE_FORMAT, version: SAVE_VERSION, name, savedAt: savedAt || Date.now(), season };
}

function safeFileName(name) {
  return (String(name).trim().replace(/[^\w\-]+/g, "_").replace(/^_+|_+$/g, "") || "save").slice(0, 60);
}

function downloadJson(filename, obj) {
  const blob = new Blob([JSON.stringify(obj, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// Accepts an export file ({format, season, name}) or a bare season object.
function parseImportedSave(text) {
  let data;
  try { data = JSON.parse(text); } catch (e) { return { error: "This is not valid JSON." }; }
  if (data && data.format === SAVE_FORMAT && data.season) {
    if (!isValidSeason(data.season)) return { error: "The save data is incomplete or corrupted." };
    return { name: String(data.name || "Imported save"), season: data.season, savedAt: data.savedAt || Date.now() };
  }
  if (isValidSeason(data)) return { name: "Imported save", season: data, savedAt: Date.now() };
  return { error: "This file is not a Pit Wall Manager save." };
}

function fmtSaveDate(ts) {
  try { return new Date(ts).toLocaleString(); } catch (e) { return ""; }
}

function SavesPanel({ open, onClose, saves, hasGame, currentSeason, onSave, onLoad, onRename, onDelete, onImport }) {
  const [name, setName] = useState("");
  const [notice, setNotice] = useState(null);
  const [confirm, setConfirm] = useState(null); // { kind: 'load'|'delete', id }
  const [renaming, setRenaming] = useState(null); // { id, value }
  const [showPaste, setShowPaste] = useState(false);
  const [pasteText, setPasteText] = useState("");
  const fileRef = useRef(null);

  if (!open) return null;
  const say = (text, ok = true) => setNotice({ text, ok });
  const trimmed = name.trim();
  const exists = saves.some((s) => s.name.toLowerCase() === trimmed.toLowerCase());

  async function doSave() {
    if (!trimmed) return say("Give your save a name first.", false);
    await onSave(trimmed);
    say(exists ? `Save "${trimmed}" overwritten.` : `Saved as "${trimmed}".`);
    setName("");
  }

  async function onFile(e) {
    const f = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!f) return;
    const res = await onImport(await f.text());
    say(res.error || `Imported "${res.name}".`, !res.error);
  }

  async function doPaste() {
    const res = await onImport(pasteText);
    say(res.error || `Imported "${res.name}".`, !res.error);
    if (!res.error) { setPasteText(""); setShowPaste(false); }
  }

  function exportOne(s) {
    downloadJson(`pit-wall-${safeFileName(s.name)}.json`, buildExport(s.name, s.season, s.savedAt));
    say(`Exported "${s.name}".`);
  }

  async function copyOne(s) {
    try {
      await navigator.clipboard.writeText(JSON.stringify(buildExport(s.name, s.season, s.savedAt)));
      say("JSON copied to clipboard.");
    } catch (e) {
      say("Clipboard unavailable — use Export instead.", false);
    }
  }

  return (
    <div className="pw-overlay" onClick={onClose}>
      <div className="pw-saves" role="dialog" aria-label="Saves" onClick={(e) => e.stopPropagation()}>
        <div className="pw-saves-head">
          <strong>Saves</strong>
          <button className="pw-hq-devbtn" onClick={onClose}>Close</button>
        </div>

        {hasGame && (
          <div className="pw-saves-new">
            <div className="pw-saves-label">Save current game as</div>
            <div className="pw-saves-row">
              <input
                className="pw-saves-input"
                value={name}
                maxLength={40}
                placeholder="Save name…"
                onChange={(e) => setName(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter") doSave(); }}
              />
              <button className="pw-hq-devbtn" onClick={doSave}>{exists ? "Overwrite" : "Save"}</button>
            </div>
            <div className="pw-saves-hint">{describeSeason(currentSeason)}</div>
          </div>
        )}

        {notice && <div className={`pw-saves-notice ${notice.ok ? "ok" : "bad"}`}>{notice.text}</div>}

        <div className="pw-saves-list">
          {saves.length === 0 && <div className="pw-saves-empty">No saves yet.</div>}
          {saves.map((s) => (
            <div className="pw-save-item" key={s.id}>
              <div className="pw-save-main">
                {renaming && renaming.id === s.id ? (
                  <div className="pw-saves-row">
                    <input
                      className="pw-saves-input"
                      autoFocus
                      value={renaming.value}
                      maxLength={40}
                      onChange={(e) => setRenaming({ id: s.id, value: e.target.value })}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" && renaming.value.trim()) { onRename(s.id, renaming.value.trim()); setRenaming(null); }
                        if (e.key === "Escape") setRenaming(null);
                      }}
                    />
                    <button className="pw-hq-devbtn" onClick={() => { if (renaming.value.trim()) { onRename(s.id, renaming.value.trim()); setRenaming(null); } }}>OK</button>
                    <button className="pw-hq-devbtn" onClick={() => setRenaming(null)}>Cancel</button>
                  </div>
                ) : (
                  <div className="pw-save-name">{s.name}</div>
                )}
                <div className="pw-save-meta">{describeSeason(s.season)} · {fmtSaveDate(s.savedAt)}</div>
              </div>
              <div className="pw-save-actions">
                {confirm && confirm.id === s.id && confirm.kind === "load" ? (
                  <>
                    <button className="pw-hq-devbtn pw-danger-btn" onClick={() => { onLoad(s.id); setConfirm(null); onClose(); }}>Replace current game</button>
                    <button className="pw-hq-devbtn" onClick={() => setConfirm(null)}>Cancel</button>
                  </>
                ) : confirm && confirm.id === s.id && confirm.kind === "delete" ? (
                  <>
                    <button className="pw-hq-devbtn pw-danger-btn" onClick={() => { onDelete(s.id); setConfirm(null); say(`Deleted "${s.name}".`); }}>Delete for good</button>
                    <button className="pw-hq-devbtn" onClick={() => setConfirm(null)}>Cancel</button>
                  </>
                ) : (
                  <>
                    <button className="pw-hq-devbtn" onClick={() => {
                      if (hasGame) setConfirm({ kind: "load", id: s.id });
                      else { onLoad(s.id); onClose(); }
                    }}>Load</button>
                    <button className="pw-hq-devbtn" onClick={() => setRenaming({ id: s.id, value: s.name })}>Rename</button>
                    <button className="pw-hq-devbtn" onClick={() => exportOne(s)}>Export</button>
                    <button className="pw-hq-devbtn" onClick={() => copyOne(s)}>Copy JSON</button>
                    <button className="pw-hq-devbtn pw-danger-btn" onClick={() => setConfirm({ kind: "delete", id: s.id })}>Delete</button>
                  </>
                )}
              </div>
            </div>
          ))}
        </div>

        <div className="pw-saves-import">
          <input ref={fileRef} type="file" accept="application/json,.json" style={{ display: "none" }} onChange={onFile} />
          <button className="pw-hq-devbtn" onClick={() => fileRef.current && fileRef.current.click()}>Import JSON file</button>
          <button className="pw-hq-devbtn" onClick={() => setShowPaste((v) => !v)}>Paste JSON</button>
          {hasGame && (
            <button className="pw-hq-devbtn" onClick={() => { downloadJson(`pit-wall-current-${safeFileName(describeSeason(currentSeason).slice(0, 30))}.json`, buildExport("Current game", currentSeason)); say("Current game exported."); }}>Export current game</button>
          )}
        </div>
        {showPaste && (
          <div className="pw-saves-paste">
            <textarea className="pw-saves-textarea" rows={5} value={pasteText} onChange={(e) => setPasteText(e.target.value)} placeholder="Paste exported save JSON here…" />
            <button className="pw-hq-devbtn" onClick={doPaste}>Import</button>
          </div>
        )}
      </div>
    </div>
  );
}


/* ---------- Settings store (persisted separately from career saves) ---------- */

const SETTINGS_KEY = "pwm-settings-v1";
const DEFAULT_SETTINGS = {
  teamName: "",       // empty = default team name
  teamColor: "",      // empty = default livery colour
  sound: true,
  volume: 0.6,
  voice: true,        // speaker / engineer voice lines
  aiDev: 1,           // rivals' development speed multiplier
  seasonLength: 0,    // 0 = every circuit
};
const PLAYER_BASE = (() => {
  const t = TEAMS.find((x) => x.isPlayer);
  return { name: t.name, color: t.color };
})();
const LIVERY_COLORS = ["#ff7d03", "#e10600", "#00d2be", "#1e41ff", "#f2b33d", "#9b5cff", "#ff4fa3", "#3de281", "#e8ecf1", "#00a3e0"];

let SETTINGS = { ...DEFAULT_SETTINGS };
let CURRENT_TITLES = {};
const settingsSubs = new Set();

function applyTeamCustom() {
  const t = TEAMS.find((x) => x.isPlayer);
  t.name = (SETTINGS.teamName || "").trim() || PLAYER_BASE.name;
  t.color = SETTINGS.teamColor || PLAYER_BASE.color;
}
function updateSettings(patch, persist = true) {
  SETTINGS = { ...SETTINGS, ...patch };
  applyTeamCustom();
  settingsSubs.forEach((f) => f());
  if (persist) storageAdapter.set(SETTINGS_KEY, JSON.stringify(SETTINGS)).catch(() => {});
}
function useSettings() {
  return useSyncExternalStore(
    (cb) => { settingsSubs.add(cb); return () => settingsSubs.delete(cb); },
    () => SETTINGS
  );
}
const playerTeamName = () => TEAMS.find((x) => x.isPlayer).name;

/* ---------- Sound (WebAudio ambience + speech synthesis voices) ---------- */

const Sound = (() => {
  let ctx = null;
  let master = null;
  let noiseBuf = null;
  const lastSaid = {};

  function ensure() {
    if (!SETTINGS.sound) return null;
    try {
      if (!ctx) {
        const AC = typeof window !== "undefined" && (window.AudioContext || window.webkitAudioContext);
        if (!AC) return null;
        ctx = new AC();
        master = ctx.createGain();
        master.connect(ctx.destination);
      }
      if (ctx.state === "suspended") ctx.resume();
      master.gain.value = Math.max(0, Math.min(1, SETTINGS.volume));
      return ctx;
    } catch (e) {
      return null;
    }
  }

  function noise() {
    if (!noiseBuf) {
      noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
      const d = noiseBuf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    }
    return noiseBuf;
  }

  // ---- V10 engine voice (2004-era, ~18-19k rpm) --------------------------
  // Rather than stacking raw sawtooths (buzzy, "chiptune"), the note is one
  // periodic waveform built on the engine CYCLE frequency (crank/2): a
  // ten-cylinder fires at the 10th harmonic of the cycle (the scream, ~1.5 kHz),
  // each bank at the 5th, and small uneven contributions on every other order
  // give the real-engine texture. On top: combustion jitter (noise FM), exhaust
  // and airbox resonances, distance air-absorption (top end opens up as the car
  // approaches), doppler, stereo pan and a shared grandstand reverb.
  let engineWave = null;
  function engineWaveform() {
    if (engineWave) return engineWave;
    const N = 48;
    const re = new Float32Array(N + 1), im = new Float32Array(N + 1);
    let seed = 7;
    const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
    for (let h = 1; h <= N; h++) {
      let a;
      if (h % 10 === 0) a = 1.0 / Math.pow(h / 10, 0.9);          // firing order + harmonics
      else if (h % 5 === 0) a = 0.55 / Math.pow(h / 5, 0.8);      // bank order
      else a = (0.05 + rnd() * 0.12) / Math.pow(h, 0.35);         // cylinder-to-cylinder unevenness
      const ph = rnd() * Math.PI * 2;
      re[h] = a * Math.cos(ph);
      im[h] = a * Math.sin(ph);
    }
    engineWave = ctx.createPeriodicWave(re, im);
    return engineWave;
  }
  let reverbBus = null;
  function reverb() {
    if (reverbBus) return reverbBus;
    const len = Math.floor(ctx.sampleRate * 1.6);
    const ir = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const d = ir.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        const t = i / ctx.sampleRate;
        // a couple of early reflections (grandstand / pit building), then a diffuse tail
        const early = (Math.abs(t - 0.031 - ch * 0.007) < 0.0012 ? 0.5 : 0) + (Math.abs(t - 0.072 + ch * 0.01) < 0.0012 ? 0.32 : 0);
        d[i] = (Math.random() * 2 - 1) * Math.exp(-t * 3.4) * 0.35 + early * (Math.random() * 2 - 1);
      }
    }
    const conv = ctx.createConvolver();
    conv.buffer = ir;
    const lp = ctx.createBiquadFilter(); lp.type = "lowpass"; lp.frequency.value = 4200;
    const wet = ctx.createGain(); wet.gain.value = 0.32;
    conv.connect(lp); lp.connect(wet); wet.connect(master);
    reverbBus = conv;
    return reverbBus;
  }
  let raspCurve = null;
  function rasp() {
    if (!raspCurve) {
      raspCurve = new Float32Array(1024);
      for (let i = 0; i < 1024; i++) { const x = (i / 511.5) - 1; raspCurve[i] = Math.tanh(1.8 * x); }
    }
    return raspCurve;
  }
  function v10(delay, level, pitch, opt = {}) {
    const t0 = ctx.currentTime + delay;
    const dur = opt.dur ?? 2.1 + Math.random() * 0.3;
    const peak = opt.peak ?? 0.3;
    const from = opt.from ?? 0.8;
    const doppler = opt.doppler ?? true;
    const NS = 128;
    const tAt = (k) => (k / (NS - 1)) * dur;
    // distance law: closest at `peak`, ~1/r falloff either side
    const dist = (t) => Math.sqrt(1 + Math.pow((t - peak) / 0.22, 2));

    const out = ctx.createGain();
    const gCurve = new Float32Array(NS);
    for (let k = 0; k < NS; k++) {
      const t = tAt(k);
      const fadeIn = Math.min(1, t / 0.08), fadeOut = Math.min(1, (dur - t) / 0.25);
      gCurve[k] = Math.max(0.0001, (0.14 * level / dist(t)) * fadeIn * Math.max(0, fadeOut));
    }
    out.gain.setValueCurveAtTime(gCurve, t0, dur);
    let tail = out;
    if (ctx.createStereoPanner) {
      const pan = ctx.createStereoPanner();
      const dir = Math.random() < 0.5 ? -1 : 1;
      const pc = new Float32Array(NS);
      for (let k = 0; k < NS; k++) pc[k] = dir * Math.tanh((tAt(k) - peak) / 0.3) * 0.85;
      pan.pan.setValueCurveAtTime(pc, t0, dur);
      out.connect(pan);
      tail = pan;
    }
    tail.connect(master);
    tail.connect(reverb());

    // air absorption: the far car is dull, the close one bright
    const air = ctx.createBiquadFilter(); air.type = "lowpass"; air.Q.value = 0.5;
    const ac = new Float32Array(NS);
    for (let k = 0; k < NS; k++) ac[k] = 1400 + 9000 / Math.pow(dist(tAt(k)), 1.6);
    air.frequency.setValueCurveAtTime(ac, t0, dur);
    air.connect(out);

    // exhaust + airbox resonances in parallel with the dry note
    const body = ctx.createGain(); body.gain.value = 1;
    const shaper = ctx.createWaveShaper(); shaper.curve = rasp(); shaper.oversample = "2x";
    const hp = ctx.createBiquadFilter(); hp.type = "highpass"; hp.frequency.value = 180;
    body.connect(shaper); shaper.connect(hp);
    const dry = ctx.createGain(); dry.gain.value = 0.55; hp.connect(dry); dry.connect(air);
    [[720, 1.3, 0.5], [1650, 1.6, 0.75], [3100, 2.2, 0.35]].forEach(([f, q, g]) => {
      const bp = ctx.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = f; bp.Q.value = q;
      const bg = ctx.createGain(); bg.gain.value = g;
      hp.connect(bp); bp.connect(bg); bg.connect(air);
    });

    // revs: climb to the limiter then hold, doppler on top
    const fr = (pitch || 300) * (0.97 + Math.random() * 0.06);   // crank frequency
    const riseEnd = dur * (opt.rise ?? 0.3);
    const rev = (t) => (t >= riseEnd ? 1 : from + (1 - from) * Math.sin((t / riseEnd) * Math.PI / 2));
    const dop = (t) => (doppler ? 1 - 0.11 * Math.tanh((t - peak) / 0.16) : 1);
    const fc = new Float32Array(NS);
    for (let k = 0; k < NS; k++) { const t = tAt(k); fc[k] = (fr / 2) * rev(t) * dop(t); } // cycle frequency
    // combustion jitter: band-limited noise frequency-modulating the note
    const jit = ctx.createBufferSource(); jit.buffer = noise(); jit.loop = true;
    const jlp = ctx.createBiquadFilter(); jlp.type = "lowpass"; jlp.frequency.value = 70;
    const jg = ctx.createGain(); jg.gain.value = fr * 0.012;
    jit.connect(jlp); jlp.connect(jg);
    [[0, 0.62], [9, 0.38]].forEach(([det, g]) => { // two exhaust banks, slightly apart
      const o = ctx.createOscillator();
      o.setPeriodicWave(engineWaveform());
      o.detune.value = det;
      o.frequency.setValueCurveAtTime(fc, t0, dur);
      jg.connect(o.frequency);
      const og = ctx.createGain(); og.gain.value = g;
      o.connect(og); og.connect(body);
      o.start(t0); o.stop(t0 + dur + 0.05);
    });
    jit.start(t0); jit.stop(t0 + dur + 0.05);

    // intake roar / mechanical hiss
    const src = ctx.createBufferSource(); src.buffer = noise();
    const bp = ctx.createBiquadFilter(); bp.type = "bandpass"; bp.Q.value = 0.7; bp.frequency.value = 2600;
    const ng = ctx.createGain(); ng.gain.value = 0.09;
    src.connect(bp); bp.connect(ng); ng.connect(air);
    src.start(t0); src.stop(t0 + dur + 0.05);
  }
  function flyby(delay, level, pitch) {
    v10(delay, level, pitch, { from: 0.95, rise: 0.12 });
  }

  // Circuit ambience while the race runs: wind/crowd murmur plus the far-off
  // scream of cars on the other side of the track, slowly swelling and fading.
  let amb = null;
  function ambience(on) {
    if (!on) {
      if (amb) { const a = amb; amb = null; try { a.g.gain.setTargetAtTime(0.0001, ctx.currentTime, 0.4); setTimeout(() => a.nodes.forEach((n) => { try { n.stop(); } catch (e) {} }), 1500); } catch (e) {} }
      return;
    }
    if (amb || !ensure()) return;
    const t0 = ctx.currentTime;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(1, t0 + 2);
    g.connect(master);
    const nodes = [];
    // crowd / wind bed
    const src = ctx.createBufferSource(); src.buffer = noise(); src.loop = true;
    const lp = ctx.createBiquadFilter(); lp.type = "bandpass"; lp.frequency.value = 520; lp.Q.value = 0.5;
    const ng = ctx.createGain(); ng.gain.value = 0.02;
    src.connect(lp); lp.connect(ng); ng.connect(g); src.start(t0); nodes.push(src);
    // distant engines: heavily filtered V10 note whose level and pitch drift
    const eg = ctx.createGain(); eg.gain.value = 0.0;
    const elp = ctx.createBiquadFilter(); elp.type = "lowpass"; elp.frequency.value = 1700; elp.Q.value = 0.3;
    elp.connect(eg); eg.connect(g);
    [[145, 0.5], [146.3, 0.35], [151, 0.2]].forEach(([f, lv]) => {
      const o = ctx.createOscillator(); o.setPeriodicWave(engineWaveform()); o.frequency.value = f;
      const vib = ctx.createOscillator(); vib.frequency.value = 0.07 + Math.random() * 0.05;
      const vd = ctx.createGain(); vd.gain.value = f * 0.06;
      vib.connect(vd); vd.connect(o.frequency);
      const og = ctx.createGain(); og.gain.value = lv;
      o.connect(og); og.connect(elp);
      o.start(t0); vib.start(t0); nodes.push(o, vib);
    });
    const swell = ctx.createOscillator(); swell.frequency.value = 0.11;
    const sd = ctx.createGain(); sd.gain.value = 0.006;
    const base = ctx.createConstantSource ? ctx.createConstantSource() : null;
    swell.connect(sd); sd.connect(eg.gain);
    if (base) { base.offset.value = 0.007; base.connect(eg.gain); base.start(t0); nodes.push(base); }
    swell.start(t0); nodes.push(swell);
    amb = { g, nodes };
  }

  // Pit stop: the rattle of the wheel guns (four corners, slightly staggered)
  function pitGun() {
    if (!ensure()) return;
    const t0 = ctx.currentTime + 0.05;
    [0, 0.09, 0.2, 0.27].forEach((d, i) => {
      const t = t0 + d;
      const src = ctx.createBufferSource(); src.buffer = noise();
      const bp = ctx.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = 2600 + i * 350; bp.Q.value = 2.2;
      const am = ctx.createGain(); am.gain.value = 0;
      const lfo = ctx.createOscillator(); lfo.type = "square"; lfo.frequency.value = 55 + i * 6;
      const ld = ctx.createGain(); ld.gain.value = 0.5;
      lfo.connect(ld); ld.connect(am.gain);
      const env = ctx.createGain();
      env.gain.setValueAtTime(0.0001, t);
      env.gain.exponentialRampToValueAtTime(0.09, t + 0.02);
      env.gain.setValueAtTime(0.09, t + 0.32);
      env.gain.exponentialRampToValueAtTime(0.0001, t + 0.42);
      src.connect(bp); bp.connect(am); am.connect(env); env.connect(master);
      src.start(t); src.stop(t + 0.45); lfo.start(t); lfo.stop(t + 0.45);
    });
  }

  // Chequered flag: the grandstands erupt
  function cheer() {
    if (!ensure()) return;
    const t0 = ctx.currentTime;
    const src = ctx.createBufferSource(); src.buffer = noise(); src.loop = true;
    const bp = ctx.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = 1100; bp.Q.value = 0.45;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(0.07, t0 + 0.7);
    g.gain.setValueAtTime(0.07, t0 + 2.6);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + 5.5);
    // irregular swell of voices
    const lfo = ctx.createOscillator(); lfo.frequency.value = 3.3;
    const ld = ctx.createGain(); ld.gain.value = 0.02;
    lfo.connect(ld); ld.connect(g.gain);
    src.connect(bp); bp.connect(g); g.connect(master);
    src.start(t0); src.stop(t0 + 5.6); lfo.start(t0); lfo.stop(t0 + 5.6);
    // horns
    [0.4, 1.3, 2.1].forEach((d, i) => {
      const o = ctx.createOscillator(); o.type = "sawtooth"; o.frequency.value = [440, 523, 392][i];
      const og = ctx.createGain(); const t = t0 + d;
      og.gain.setValueAtTime(0.0001, t); og.gain.exponentialRampToValueAtTime(0.012, t + 0.05); og.gain.exponentialRampToValueAtTime(0.0001, t + 0.6);
      const f = ctx.createBiquadFilter(); f.type = "lowpass"; f.frequency.value = 1800;
      o.connect(f); f.connect(og); og.connect(master); o.start(t); o.stop(t + 0.65);
    });
  }

  // Standing start / restart: the whole pack on the throttle, climbing through
  // the gears as it streams past.
  function launch(cars = 8) {
    if (!ensure()) return;
    const n = Math.max(3, Math.min(9, cars));
    for (let i = 0; i < n; i++) {
      v10(i * (0.16 + Math.random() * 0.14), (0.95 - i * 0.07) * 0.65, 286 + ((i * 37) % 11) * 4, { dur: 3.6 + Math.random() * 0.8, peak: 1.9 + i * 0.08, from: 0.55, rise: 0.4, doppler: true });
    }
  }

  // Leader crosses the line: a handful of cars stream past, lightly.
  let lastPass = 0;
  function pass(cars = 4) {
    const now = Date.now();
    if (now - lastPass < 1500) return;
    lastPass = now;
    if (!ensure()) return;
    const n = Math.max(2, Math.min(6, cars));
    for (let i = 0; i < n; i++) flyby(i * (0.14 + Math.random() * 0.22), 1 - i * 0.1);
  }

  // One specific car crossing the line: its own engine note (pitch depends on
  // the car), quiet for cars in the pit lane. Slightly staggered when several
  // cars cross in the same moment so they don't stack into a single blob.
  let carBurst = 0;
  function car(carId, { inPit = false, stagger = 0 } = {}) {
    if (!ensure()) return;
    const pitch = 284 + ((Number(carId) * 37) % 11) * 4 + Math.random() * 4;
    flyby(stagger * 0.12 + Math.random() * 0.05, inPit ? 0.35 : 0.8, pitch);
  }

  function squelch() {
    if (!ensure()) return;
    const t0 = ctx.currentTime;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(0.06, t0 + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.16);
    g.connect(master);
    const src = ctx.createBufferSource();
    src.buffer = noise();
    const bp = ctx.createBiquadFilter();
    bp.type = "bandpass";
    bp.frequency.value = 2000;
    bp.Q.value = 1.2;
    src.connect(bp);
    bp.connect(g);
    src.start(t0);
    src.stop(t0 + 0.18);
    const o = ctx.createOscillator();
    o.type = "sine";
    o.frequency.value = 1450;
    const og = ctx.createGain();
    og.gain.setValueAtTime(0.0001, t0 + 0.05);
    og.gain.exponentialRampToValueAtTime(0.05, t0 + 0.06);
    og.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.14);
    o.connect(og);
    og.connect(master);
    o.start(t0 + 0.05);
    o.stop(t0 + 0.16);
  }

  let voices = [];
  function loadVoices() {
    try { voices = window.speechSynthesis.getVoices() || []; } catch (e) { voices = []; }
  }
  const FEMALE = /female|zira|hazel|susan|samantha|karen|moira|tessa|fiona|victoria|serena|kate|catherine|linda|heera|ava\b|allison|jenny|aria|sonia|libby|amelie|joana|helena|laura|monica|paulina|veena/i;
  const MALE = /\bmale\b|daniel|david|mark|george|ryan|alex|fred|oliver|arthur|thomas|james|guy|christopher|eric|roger|rishi|aaron|gordon|lee\b/i;
  function pickVoice(role) {
    if (!voices.length) loadVoices();
    const en = voices.filter((v) => /^en/i.test(v.lang));
    if (!en.length) return null;
    const males = en.filter((v) => !FEMALE.test(v.name));
    const pool = males.length ? males : en;
    const gb = pool.filter((v) => /en-GB/i.test(v.lang));
    const prefer = role === "engineer"
      ? [gb.find((v) => MALE.test(v.name)), pool.find((v) => MALE.test(v.name)), gb[0]]
      : [pool.find((v) => /en-US/i.test(v.lang) && MALE.test(v.name)), pool.find((v) => MALE.test(v.name)), pool[0]];
    return prefer.find(Boolean) || pool[0];
  }

  // Team-radio texture laid over the engineer's voice: a band-limited hiss with
  // random crackle while he talks, opened and closed by a squelch. (The browser
  // does not let us filter the speech itself, so the effect sits around it.)
  let staticNodes = null;
  function startStatic() {
    if (!ensure() || staticNodes) return;
    const src = ctx.createBufferSource();
    src.buffer = noise();
    src.loop = true;
    const hp = ctx.createBiquadFilter();
    hp.type = "highpass";
    hp.frequency.value = 700;
    const bp = ctx.createBiquadFilter();
    bp.type = "bandpass";
    bp.frequency.value = 2200;
    bp.Q.value = 0.6;
    const g = ctx.createGain();
    g.gain.value = 0.018;
    src.connect(hp);
    hp.connect(bp);
    bp.connect(g);
    g.connect(master);
    src.start();
    const timer = setInterval(() => {
      try {
        const t = ctx.currentTime;
        const spike = Math.random() < 0.3;
        g.gain.setValueAtTime(spike ? 0.05 + Math.random() * 0.04 : 0.012 + Math.random() * 0.012, t);
      } catch (e) { /* ignore */ }
    }, 90);
    staticNodes = { src, g, timer };
  }
  function stopStatic() {
    if (!staticNodes) return;
    const { src, g, timer } = staticNodes;
    staticNodes = null;
    clearInterval(timer);
    try {
      g.gain.setValueAtTime(g.gain.value, ctx.currentTime);
      g.gain.linearRampToValueAtTime(0.0001, ctx.currentTime + 0.08);
      src.stop(ctx.currentTime + 0.1);
    } catch (e) { /* ignore */ }
  }

  // role: "speaker" (circuit PA announcer) or "engineer" (team radio)
  function say(text, role = "speaker") {
    if (!SETTINGS.sound || !SETTINGS.voice) return;
    const now = Date.now();
    if (lastSaid[text] && now - lastSaid[text] < 2500) return;
    lastSaid[text] = now;
    try {
      const ss = window.speechSynthesis;
      if (!ss || typeof SpeechSynthesisUtterance === "undefined") return;
      ensure();
      const radio = role === "engineer";
      if (radio) {
        squelch();
        ss.cancel();
        stopStatic();
      }
      const u = new SpeechSynthesisUtterance(text);
      u.lang = "en-GB";
      const v = pickVoice(role);
      if (v) u.voice = v;
      u.volume = Math.max(0, Math.min(1, SETTINGS.volume));
      u.pitch = radio ? 0.65 : 0.9;
      u.rate = radio ? 1.12 : 1.0;
      if (radio) {
        let closed = false;
        const close = () => { if (closed) return; closed = true; stopStatic(); squelch(); };
        u.onstart = () => { if (!closed) startStatic(); };
        u.onend = close;
        u.onerror = close;
        // safety net in case the engine never fires onend
        setTimeout(close, 1500 + text.length * 120);
      }
      setTimeout(() => { try { ss.speak(u); } catch (e) { /* ignore */ } }, radio ? 240 : 0);
    } catch (e) { /* sound is best-effort */ }
  }

  try {
    if (typeof window !== "undefined" && window.speechSynthesis) {
      loadVoices();
      window.speechSynthesis.onvoiceschanged = loadVoices;
    }
  } catch (e) { /* ignore */ }

  return { pass, car, launch, ambience, pitGun, cheer, say, squelch, unlock: ensure };
})();

/* ---------- Champion stars, career stats, board and press helpers ---------- */

function Stars({ name }) {
  const n = (CURRENT_TITLES && CURRENT_TITLES[name]) || 0;
  if (!n) return null;
  return (
    <span className="pw-stars" title={`${n} world title${n > 1 ? "s" : ""}`} aria-label={`${n} world titles`}>
      {n <= 6 ? "★".repeat(n) : `★×${n}`}
    </span>
  );
}

function playerRankFromPoints(constructorPoints) {
  const pid = TEAMS.find((t) => t.isPlayer).id;
  const rows = TEAMS.map((t) => ({ id: t.id, pts: constructorPoints[t.id] || 0 }));
  rows.sort((a, b) => b.pts - a.pts);
  return rows.findIndex((r) => r.id === pid) + 1;
}

function playerRankFromPerf(teamPerf) {
  const pid = TEAMS.find((t) => t.isPlayer).id;
  const rows = TEAMS.map((t) => ({ id: t.id, perf: teamPerf[t.id] ?? t.perf }));
  rows.sort((a, b) => b.perf - a.perf);
  return rows.findIndex((r) => r.id === pid) + 1;
}

const ordinal = (n) => `P${n}`;

function seasonPlayerTally(calendar) {
  let wins = 0, podiums = 0, scoringRaces = 0;
  calendar.forEach((r) => {
    if (!r.completed || !r.playerResult) return;
    if (r.playerResult.some((p) => p === 1)) wins += r.playerResult.filter((p) => p === 1).length;
    podiums += r.playerResult.filter((p) => p <= 3).length;
    if (r.playerResult.some((p) => p <= 10)) scoringRaces += 1;
  });
  return { wins, podiums, scoringRaces };
}

function generateBoardObjective(season) {
  const rank = playerRankFromPerf(season.teamPerf);
  let target;
  if (rank <= 1) target = 1;
  else if (rank <= 3) target = Math.max(1, rank - (Math.random() < 0.5 ? 1 : 0));
  else target = Math.max(1, rank - 1 - (Math.random() < 0.35 ? 1 : 0));
  const rounds = season.calendar.length;
  let secondary;
  if (target <= 3) {
    const n = target === 1 ? Math.max(3, Math.round(rounds * 0.45)) : Math.max(2, Math.round(rounds * 0.25));
    secondary = { type: "podiums", n, text: `Score at least ${n} podium finishes` };
  } else {
    const n = Math.max(3, Math.round(rounds * 0.5));
    secondary = { type: "scoring", n, text: `Score points in at least ${n} races` };
  }
  return {
    target,
    text: target === 1 ? "Win the Constructors' Championship" : `Finish ${ordinal(target)} or better in the Constructors' Championship`,
    secondary,
  };
}

function boardMood(c) {
  if (c >= 80) return { label: "Delighted", tone: "great" };
  if (c >= 60) return { label: "Satisfied", tone: "good" };
  if (c >= 40) return { label: "Concerned", tone: "warn" };
  if (c >= 20) return { label: "Under pressure", tone: "bad" };
  return { label: "Considering your position", tone: "crit" };
}

function secondaryProgress(obj, calendar) {
  const t = seasonPlayerTally(calendar);
  return obj.type === "podiums" ? t.podiums : t.scoringRaces;
}

// Updates board confidence after a race; at the end of the season it also
// issues the verdict, pays any bonus and decides whether the manager is sacked.
function updateBoardAfterRace(board, { constructorPoints, calendar, seasonJustEnded, playerPositions, round }) {
  const b = board || { confidence: 60, objective: null, verdict: null, fired: false };
  if (!b.objective) return { board: b, bonus: 0 };
  const obj = b.objective;
  const rank = playerRankFromPoints(constructorPoints);
  let conf = b.confidence;
  const roundsDone = calendar.filter((r) => r.completed).length;
  let delta = 0;
  if (roundsDone >= 2) delta += Math.max(-4, Math.min(3, (obj.target - rank) * 1.5));
  if (playerPositions.some((p) => p === 1)) delta += 3;
  else if (playerPositions.some((p) => p <= 3)) delta += 2;
  else if (playerPositions.every((p) => p > 10)) delta -= 2;
  conf += delta;
  let verdict = b.verdict;
  let bonus = 0;
  let fired = false;
  if (seasonJustEnded) {
    const gap = obj.target - rank; // >0 beat the target
    let mainDelta;
    if (gap >= 2) mainDelta = 25;
    else if (gap >= 0) mainDelta = 15;
    else if (gap === -1) mainDelta = -10;
    else mainDelta = -25;
    const prog = secondaryProgress(obj.secondary, calendar);
    const secOk = prog >= obj.secondary.n;
    const secDelta = secOk ? 5 : -5;
    if (gap >= 0) bonus += gap >= 2 ? 200 : 120;
    if (secOk) bonus += 50;
    conf += mainDelta + secDelta;
    conf = Math.max(0, Math.min(100, conf));
    fired = conf < 20;
    verdict = {
      round,
      rank,
      mainOk: gap >= 0,
      secOk,
      progress: prog,
      objective: obj,
      confDelta: mainDelta + secDelta,
      bonus,
      fired,
    };
  }
  conf = Math.max(0, Math.min(100, conf));
  return { board: { ...b, confidence: conf, verdict, fired: b.fired || fired }, bonus };
}

const PRESS_OUTLETS = ["Paddock Daily", "Grid Weekly", "The Apex", "Parc Fermé", "Pit Lane Post", "Motorsport Herald"];
const pickOne = (arr) => arr[Math.floor(Math.random() * arr.length)];

function generatePress(finalStandings, circuit, season) {
  const ptsOf = (i) => POINTS_TABLE[i] || 0;
  const winner = finalStandings[0];
  const players = finalStandings.filter((c) => c.team.isPlayer);
  const posOf = (c) => finalStandings.findIndex((x) => x.id === c.id) + 1;
  const bestPos = Math.min(...players.map((c) => (c.status === "dnf" ? 99 : posOf(c))));
  const dnfs = finalStandings.filter((c) => c.status === "dnf");
  const playerDnf = players.filter((c) => c.status === "dnf");
  const penalised = finalStandings.filter((c) => c.penaltySec > 0);
  const outlets = [...PRESS_OUTLETS].sort(() => Math.random() - 0.5);
  const team = playerTeamName();
  const articles = [];

  articles.push({
    outlet: outlets[0],
    headline: `${winner.name} takes the win at ${circuit.name}`,
    body: `${winner.team.name} convert strong pace into victory${winner.team.isPlayer ? " — and the paddock is talking about it." : "."}`,
  });

  let context;
  if (players.length && bestPos === 1) {
    context = "win";
    articles.push({ outlet: outlets[1], headline: `${team} on top of the world`, body: `A flawless weekend for ${team}, with ${winner.name} leading home the field.` });
  } else if (bestPos <= 3) {
    context = "podium";
    articles.push({ outlet: outlets[1], headline: `${team} back on the podium`, body: `P${bestPos} at ${circuit.name} keeps ${team} in the conversation.` });
  } else if (bestPos <= 10) {
    context = "points";
    articles.push({ outlet: outlets[1], headline: `${team} grind out points`, body: `A solid, if unspectacular, afternoon: best finisher P${bestPos}.` });
  } else if (playerDnf.length) {
    context = "dnf";
    articles.push({ outlet: outlets[1], headline: `Retirement blow for ${team}`, body: `${playerDnf.map((c) => c.name).join(" and ")} did not see the flag, raising questions over reliability.` });
  } else {
    context = "poor";
    articles.push({ outlet: outlets[1], headline: `${team} left in the shadows`, body: `Outside the points in Round ${season.roundIndex + 1}. Pressure is building on the pit wall.` });
  }
  if (players.some((c) => c.penaltySec > 0)) context = context === "dnf" ? context : "penalty";

  const leaderPts = {};
  finalStandings.forEach((c, i) => { leaderPts[c.id] = (season.driverPoints[c.id] || 0) + ptsOf(i); });
  const leaderId = Object.keys(leaderPts).sort((a, b) => leaderPts[b] - leaderPts[a])[0];
  const leader = finalStandings.find((c) => String(c.id) === String(leaderId));
  if (penalised.length) {
    articles.push({ outlet: outlets[2], headline: "Stewards under the microscope", body: `${penalised.length} driver${penalised.length > 1 ? "s" : ""} hit with time penalties — expect debate in the paddock.` });
  } else if (dnfs.length >= 3) {
    articles.push({ outlet: outlets[2], headline: "Attrition takes its toll", body: `${dnfs.length} cars failed to finish a chaotic race.` });
  } else if (leader) {
    articles.push({ outlet: outlets[2], headline: `${leader.name} leads the championship`, body: `${leader.name} (${leader.team.name}) heads the standings with ${leaderPts[leaderId]} points.` });
  }

  const Q = {
    win: {
      text: "A big win today. How do you frame it for the press?",
      options: [
        { label: "Credit the whole team, stay humble", effect: { conf: 3 }, reply: "The factory staff will love that." },
        { label: "\"We're coming for the title!\"", effect: { conf: 7, risk: { p: 0.35, conf: -6 } }, reply: "Bold. The headlines write themselves.", bold: true },
        { label: "Thank the sponsors loudly", effect: { conf: 1, budget: 25 }, reply: "Your partners are delighted." },
      ],
    },
    podium: {
      text: "A podium finish. Are you satisfied?",
      options: [
        { label: "\"Good, but we want more.\"", effect: { conf: 3 }, reply: "Ambitious and measured." },
        { label: "\"Next stop: the top step.\"", effect: { conf: 6, risk: { p: 0.35, conf: -5 } }, reply: "You've raised expectations.", bold: true },
        { label: "Praise the drivers", effect: { conf: 2 }, reply: "The garage appreciates it." },
      ],
    },
    points: {
      text: "Points in the bag, but nothing spectacular. Your thoughts?",
      options: [
        { label: "\"Steady progress, we'll build on it.\"", effect: { conf: 2 }, reply: "Reasonable, and the board nods." },
        { label: "\"We left performance on the table.\"", effect: { conf: 1 }, reply: "Honest, if slightly worrying." },
        { label: "\"Upgrades arrive soon — watch us.\"", effect: { conf: 4, risk: { p: 0.4, conf: -5 } }, reply: "That's a promise you'll have to keep.", bold: true },
      ],
    },
    poor: {
      text: "Another race without points. Fans are getting impatient.",
      options: [
        { label: "Take responsibility publicly", effect: { conf: 2 }, reply: "Accountability goes down well upstairs." },
        { label: "Blame bad luck", effect: { conf: -2 }, reply: "Few are convinced." },
        { label: "\"A big upgrade is coming.\"", effect: { conf: 4, risk: { p: 0.45, conf: -6 } }, reply: "The board will hold you to that.", bold: true },
      ],
    },
    dnf: {
      text: "A retirement today. Questions about reliability — what do you say?",
      options: [
        { label: "\"We'll investigate every component.\"", effect: { conf: 2 }, reply: "A measured, professional answer." },
        { label: "Defend the drivers, blame the parts", effect: { conf: 0 }, reply: "Neutral reaction." },
        { label: "\"It's racing. It happens.\"", effect: { conf: -3 }, reply: "That doesn't land well with the board." },
      ],
    },
    penalty: {
      text: "Stewards penalised one of your cars. How do you react?",
      options: [
        { label: "Accept it and move on", effect: { conf: 2 }, reply: "Professional." },
        { label: "Publicly criticise the stewards", effect: { conf: 1, budget: -30, risk: { p: 0.5, conf: -5 } }, reply: "A fine looms and the FIA isn't amused.", bold: true },
        { label: "\"We'll review the footage.\"", effect: { conf: 1 }, reply: "Calm and diplomatic." },
      ],
    },
  };
  const question = Q[context] || Q.points;
  return { articles: articles.slice(0, 3), question, context, round: season.roundIndex + 1, circuitName: circuit.name, answered: null };
}

/* ============================== GLOBAL CHROME / SETTINGS ============================== */

function SettingsPanel({ onClose }) {
  const s = useSettings();
  const [name, setName] = useState(s.teamName || "");
  const colour = s.teamColor || PLAYER_BASE.color;
  const lengthOptions = [0, 6, 8, 10, 12];
  return (
    <div className="pw-overlay pw-overlay-top" onClick={onClose}>
      <div className="pw-saves pw-settings" role="dialog" aria-label="Settings" onClick={(e) => e.stopPropagation()}>
        <div className="pw-saves-head">
          <strong>Settings</strong>
          <button className="pw-hq-devbtn" onClick={onClose}>Close</button>
        </div>

        <div className="pw-set-group">
          <div className="pw-saves-label">Team</div>
          <div className="pw-saves-row">
            <input
              className="pw-saves-input"
              value={name}
              maxLength={24}
              placeholder={PLAYER_BASE.name}
              onChange={(e) => { setName(e.target.value); updateSettings({ teamName: e.target.value }); }}
              aria-label="Team name"
            />
            <button className="pw-hq-devbtn" onClick={() => { setName(""); updateSettings({ teamName: "", teamColor: "" }); }}>Reset</button>
          </div>
          <div className="pw-saves-label" style={{ marginTop: 10 }}>Car colour</div>
          <div className="pw-swatches">
            {LIVERY_COLORS.map((c) => (
              <button
                key={c}
                className={`pw-swatch ${c.toLowerCase() === colour.toLowerCase() ? "on" : ""}`}
                style={{ background: c }}
                onClick={() => updateSettings({ teamColor: c })}
                aria-label={`Colour ${c}`}
              />
            ))}
            <input type="color" className="pw-colorpick" value={colour} onChange={(e) => updateSettings({ teamColor: e.target.value })} aria-label="Custom colour" />
          </div>
          <div className="pw-set-preview">
            <span className="pw-teamchip" style={{ background: colour }} /> {playerTeamName()}
          </div>
        </div>

        <div className="pw-set-group">
          <div className="pw-saves-label">Sound</div>
          <label className="pw-set-row">
            <input type="checkbox" checked={s.sound} onChange={(e) => { updateSettings({ sound: e.target.checked }); if (e.target.checked) Sound.unlock(); }} /> Sound effects
          </label>
          <label className="pw-set-row">
            <input type="checkbox" checked={s.voice} onChange={(e) => updateSettings({ voice: e.target.checked })} /> Speaker &amp; engineer voices
          </label>
          <label className="pw-set-row">
            Volume
            <input type="range" min="0" max="1" step="0.05" value={s.volume} onChange={(e) => updateSettings({ volume: Number(e.target.value) })} />
            <button className="pw-hq-devbtn" onClick={() => { Sound.unlock(); Sound.launch(5); }}>Test</button>
            <button className="pw-hq-devbtn" onClick={() => Sound.say("Box this lap", "engineer")}>Test radio</button>
          </label>
        </div>

        <div className="pw-set-group">
          <div className="pw-saves-label">Gameplay (applies to the next season where noted)</div>
          <label className="pw-set-row">
            Rivals' development
            <select className="pw-saves-input" value={s.aiDev} onChange={(e) => updateSettings({ aiDev: Number(e.target.value) })}>
              <option value={0.6}>Relaxed</option>
              <option value={1}>Normal</option>
              <option value={1.5}>Ruthless</option>
            </select>
          </label>
          <label className="pw-set-row">
            Season length (next season)
            <select className="pw-saves-input" value={s.seasonLength} onChange={(e) => updateSettings({ seasonLength: Number(e.target.value) })}>
              {lengthOptions.map((n) => (
                <option key={n} value={n}>{n === 0 ? "Every circuit" : `${n} races`}</option>
              ))}
            </select>
          </label>
        </div>
      </div>
    </div>
  );
}

// Floating buttons available on every screen: settings and a quick mute toggle.
function GlobalChrome() {
  const s = useSettings();
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const unlock = () => Sound.unlock();
    window.addEventListener("pointerdown", unlock, { once: true });
    return () => window.removeEventListener("pointerdown", unlock);
  }, []);
  return (
    <>
      <div className="pw-fab">
        <button className="pw-fab-btn" onClick={() => setOpen(true)} aria-label="Settings">⚙ Settings</button>
        <button
          className="pw-fab-btn"
          onClick={() => { updateSettings({ sound: !s.sound }); if (!s.sound) Sound.unlock(); }}
          aria-label={s.sound ? "Mute" : "Unmute"}
          title={s.sound ? "Sound on" : "Sound off"}
        >
          {s.sound ? "🔊" : "🔇"}
        </button>
      </div>
      {open && <SettingsPanel onClose={() => setOpen(false)} />}
    </>
  );
}

/* ============================== BOARD / PRESS PANELS ============================== */

function BoardPanel({ season }) {
  const b = season.board;
  if (!b || !b.objective) return null;
  const rows = Object.entries(season.constructorPoints).map(([id, pts]) => ({ id, pts }));
  const rank = rows.length ? playerRankFromPoints(season.constructorPoints) : null;
  const sec = b.objective.secondary;
  const prog = secondaryProgress(sec, season.calendar);
  const mood = boardMood(b.confidence);
  const started = season.calendar.some((r) => r.completed);
  return (
    <section className="pw-panel pw-board">
      <h2>Board of Directors</h2>
      <div className="pw-board-meter" role="meter" aria-valuenow={Math.round(b.confidence)} aria-valuemin={0} aria-valuemax={100} aria-label="Board confidence">
        <div className={`pw-board-fill ${mood.tone}`} style={{ width: `${b.confidence}%` }} />
      </div>
      <div className="pw-board-line"><strong>{mood.label}</strong> — confidence {Math.round(b.confidence)}/100</div>
      <ul className="pw-board-obj">
        <li>
          <span className={`pw-obj-dot ${started && rank && rank <= b.objective.target ? "ok" : ""}`} />
          {b.objective.text}
          {started && rank ? <em> — currently P{rank}</em> : null}
        </li>
        <li>
          <span className={`pw-obj-dot ${prog >= sec.n ? "ok" : ""}`} />
          {sec.text} <em>— {prog}/{sec.n}</em>
        </li>
      </ul>
      {b.confidence < 35 && <div className="pw-board-warn">The board is losing patience — results are needed.</div>}
    </section>
  );
}

function PressFeed({ season }) {
  const log = season.pressLog || [];
  if (!log.length) return null;
  return (
    <section className="pw-panel">
      <h2>Paddock News</h2>
      <ul className="pw-press-list">
        {log.slice(0, 5).map((a, i) => (
          <li key={i}>
            <span className="pw-press-outlet">{a.outlet}</span>
            <strong>{a.headline}</strong>
            <span className="pw-press-body">{a.body}</span>
          </li>
        ))}
      </ul>
    </section>
  );
}

function PressScreen({ press, onAnswer, onContinue }) {
  const a = press.answered;
  return (
    <div className="pw-hq">
      <header className="pw-hq-header">
        <div className="pw-brand">
          <span className="pw-brand-mark">PW</span>
          <span className="pw-brand-name">PRESS ROOM — {press.circuitName}</span>
        </div>
      </header>
      <section className="pw-panel">
        <h2>Today's headlines</h2>
        <div className="pw-press-cards">
          {press.articles.map((art, i) => (
            <article key={i} className="pw-press-card">
              <div className="pw-press-outlet">{art.outlet}</div>
              <h3>{art.headline}</h3>
              <p>{art.body}</p>
            </article>
          ))}
        </div>
      </section>
      <section className="pw-panel" style={{ marginTop: 14 }}>
        <h2>Press conference</h2>
        <p className="pw-devnote">“{press.question.text}”</p>
        {!a ? (
          <div className="pw-press-opts">
            {press.question.options.map((o, i) => (
              <button key={i} className="pw-press-opt" onClick={() => onAnswer(o)}>
                {o.label}
                {o.bold && <span className="pw-press-risk">risky</span>}
              </button>
            ))}
          </div>
        ) : (
          <div className="pw-press-reply">
            <p>{a.reply}</p>
            <p className="pw-board-line">
              Board confidence <strong className={a.conf >= 0 ? "pw-pos-txt" : "pw-neg-txt"}>{a.conf >= 0 ? "+" : ""}{a.conf}</strong>
              {a.budget ? <> · Budget <strong className={a.budget >= 0 ? "pw-pos-txt" : "pw-neg-txt"}>{a.budget >= 0 ? "+" : ""}{a.budget} cr</strong></> : null}
              {a.backfired ? <> · <em>it backfired</em></> : null}
            </p>
            <button className="pw-start-btn" onClick={onContinue}>Continue</button>
          </div>
        )}
      </section>
    </div>
  );
}

function VerdictPanel({ season }) {
  const v = season.board && season.board.verdict;
  const last = season.history && season.history[season.history.length - 1];
  if (!v) return null;
  return (
    <section className="pw-panel pw-board" style={{ marginBottom: 14 }}>
      <h2>Season {last ? last.season : season.seasonNumber} review</h2>
      {last && (
        <p className="pw-devnote">
          Drivers' champion: <strong>{last.champion.name}</strong> <Stars name={last.champion.name} /> · Constructors' champion:{" "}
          <strong>{(TEAMS.find((t) => t.id === last.constructorChampion.teamId) || {}).name}</strong>
        </p>
      )}
      <ul className="pw-board-obj">
        <li><span className={`pw-obj-dot ${v.mainOk ? "ok" : ""}`} />{v.objective.text} — finished P{v.rank} {v.mainOk ? "✔" : "✘"}</li>
        <li><span className={`pw-obj-dot ${v.secOk ? "ok" : ""}`} />{v.objective.secondary.text} — {v.progress}/{v.objective.secondary.n} {v.secOk ? "✔" : "✘"}</li>
      </ul>
      <div className="pw-board-line">
        Board confidence {v.confDelta >= 0 ? "+" : ""}{v.confDelta}
        {v.bonus > 0 ? <> · Bonus <strong>+{v.bonus} cr</strong></> : null}
      </div>
    </section>
  );
}

function FiredScreen({ season, onNewCareer, onOpenSaves }) {
  const v = season.board.verdict;
  return (
    <div className="pw-hq">
      <header className="pw-hq-header">
        <div className="pw-brand">
          <span className="pw-brand-mark">PW</span>
          <span className="pw-brand-name">DISMISSED</span>
        </div>
      </header>
      <section className="pw-panel pw-fired">
        <h2>The board has relieved you of your duties</h2>
        <p className="pw-devnote">
          After season {season.seasonNumber}, {playerTeamName()} finished P{v ? v.rank : "—"} against an objective of {v ? `P${v.objective.target}` : "—"}.
          Confidence ended at {Math.round(season.board.confidence)}/100.
        </p>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <button className="pw-start-btn" onClick={onNewCareer}>Start a new career</button>
          <button className="pw-hq-devbtn" onClick={onOpenSaves}>Load a save</button>
        </div>
      </section>
    </div>
  );
}

/* ============================== STATISTICS ============================== */

function StatsScreen({ season, onBack }) {
  const [tab, setTab] = useState("season");
  const history = season.history || [];
  const stats = season.driverStats || {};
  const rows = Object.entries(stats).map(([name, s]) => ({ name, ...s, titles: (season.titles || {})[name] || 0 }));
  const top = (key, n = 8) => [...rows].sort((a, b) => b[key] - a[key] || b.points - a.points).filter((r) => r[key] > 0).slice(0, n);
  const playerId = TEAMS.find((t) => t.isPlayer).id;

  // championship progression (cumulative points, top 6 drivers this season)
  const dh = season.driverHistory || [];
  const lastPts = dh.length ? dh[dh.length - 1].pts : {};
  const topSlots = Object.keys(lastPts).sort((a, b) => lastPts[b] - lastPts[a]).slice(0, 6);
  const chartData = dh.map((h) => {
    const row = { round: `R${h.round}` };
    topSlots.forEach((s) => { row[`s${s}`] = h.pts[s] || 0; });
    return row;
  });
  const slotName = (s) => {
    const d = getDriverForSlot(season, Number(s));
    return d ? d.name : `#${Number(s) + 1}`;
  };
  const slotColor = (s) => (TEAMS[Math.floor(Number(s) / 2)] || {}).color || "#888";

  const tabs = [["season", "This season"], ["fame", "Hall of fame"], ["records", "Records"]];
  const titlesBoard = Object.entries(season.titles || {}).sort((a, b) => b[1] - a[1]);
  const cTitles = {};
  history.forEach((h) => { cTitles[h.constructorChampion.teamId] = (cTitles[h.constructorChampion.teamId] || 0) + 1; });
  const playerSeasons = history;
  const careerWins = playerSeasons.reduce((s, h) => s + h.player.wins, 0);
  const careerPodiums = playerSeasons.reduce((s, h) => s + h.player.podiums, 0);
  const bestRank = playerSeasons.length ? Math.min(...playerSeasons.map((h) => h.player.rank)) : null;

  return (
    <div className="pw-hq">
      <header className="pw-hq-header">
        <div className="pw-brand">
          <span className="pw-brand-mark">PW</span>
          <span className="pw-brand-name">STATISTICS</span>
        </div>
        <button className="pw-hq-devbtn" onClick={onBack}>← Back</button>
      </header>

      <div className="pw-tabs" role="tablist">
        {tabs.map(([id, label]) => (
          <button key={id} role="tab" aria-selected={tab === id} className={`pw-tab ${tab === id ? "on" : ""}`} onClick={() => setTab(id)}>{label}</button>
        ))}
      </div>

      {tab === "season" && (
        <section className="pw-panel">
          <h2>Drivers' championship — Season {season.seasonNumber}</h2>
          {chartData.length === 0 ? (
            <p className="pw-empty">Complete a race to see the points progression.</p>
          ) : (
            <div style={{ width: "100%", height: 280 }}>
              <ResponsiveContainer>
                <LineChart data={chartData} margin={{ top: 8, right: 16, bottom: 0, left: -10 }}>
                  <CartesianGrid stroke="#232B38" strokeDasharray="3 3" />
                  <XAxis dataKey="round" stroke="#6B7684" fontSize={11} />
                  <YAxis stroke="#6B7684" fontSize={11} />
                  <Tooltip contentStyle={{ background: "#131822", border: "1px solid #232B38", fontSize: 12 }} />
                  <Legend wrapperStyle={{ fontSize: 11 }} />
                  {topSlots.map((s) => (
                    <Line key={s} type="monotone" dataKey={`s${s}`} name={slotName(s)} stroke={slotColor(s)} strokeWidth={Math.floor(Number(s) / 2) === 0 ? 3 : 1.6} strokeDasharray={Number(s) % 2 ? "5 3" : undefined} dot={{ r: 2 }} />
                  ))}
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}
          <div className="pw-stat-cards">
            <div className="pw-stat-card"><span>Races done</span><strong>{season.calendar.filter((r) => r.completed).length}/{season.calendar.length}</strong></div>
            <div className="pw-stat-card"><span>Team wins</span><strong>{seasonPlayerTally(season.calendar).wins}</strong></div>
            <div className="pw-stat-card"><span>Team podiums</span><strong>{seasonPlayerTally(season.calendar).podiums}</strong></div>
            <div className="pw-stat-card"><span>Constructors' rank</span><strong>{season.calendar.some((r) => r.completed) ? `P${playerRankFromPoints(season.constructorPoints)}` : "—"}</strong></div>
          </div>
        </section>
      )}

      {tab === "fame" && (
        <>
          <section className="pw-panel">
            <h2>Champions by season</h2>
            {history.length === 0 ? (
              <p className="pw-empty">No completed season yet.</p>
            ) : (
              <div className="pw-table-wrap">
                <table className="pw-table">
                  <thead><tr><th>Season</th><th>Drivers' champion</th><th>Constructors' champion</th><th>Your team</th></tr></thead>
                  <tbody>
                    {[...history].reverse().map((h) => {
                      const ct = TEAMS.find((t) => t.id === h.constructorChampion.teamId);
                      return (
                        <tr key={h.season}>
                          <td>{h.season}</td>
                          <td>{h.champion.name} <Stars name={h.champion.name} /> <span className="pw-carno">{h.champion.pts} pts</span></td>
                          <td>{ct ? ct.name : "—"}</td>
                          <td>P{h.player.rank} · {h.player.pts} pts · {h.player.wins}W {h.player.podiums}P</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </section>
          <section className="pw-panel" style={{ marginTop: 14 }}>
            <h2>World champions</h2>
            {titlesBoard.length === 0 ? (
              <p className="pw-empty">No champion crowned yet.</p>
            ) : (
              <ol className="pw-standings-list">
                {titlesBoard.map(([name, n], i) => (
                  <li key={name}><span className="pw-pos">{i + 1}</span>{name} <Stars name={name} /><span className="pw-final-gap">{n} title{n > 1 ? "s" : ""}</span></li>
                ))}
              </ol>
            )}
            {Object.keys(cTitles).length > 0 && (
              <p className="pw-devnote" style={{ marginTop: 10 }}>
                Constructors' titles: {Object.entries(cTitles).sort((a, b) => b[1] - a[1]).map(([id, n]) => `${(TEAMS.find((t) => t.id === id) || {}).name} ×${n}`).join(" · ")}
              </p>
            )}
          </section>
        </>
      )}

      {tab === "records" && (
        <>
          <section className="pw-panel">
            <h2>Your team</h2>
            <div className="pw-stat-cards">
              <div className="pw-stat-card"><span>Seasons completed</span><strong>{history.length}</strong></div>
              <div className="pw-stat-card"><span>Constructors' titles</span><strong>{cTitles[playerId] || 0}</strong></div>
              <div className="pw-stat-card"><span>Race wins</span><strong>{careerWins}</strong></div>
              <div className="pw-stat-card"><span>Podiums</span><strong>{careerPodiums}</strong></div>
              <div className="pw-stat-card"><span>Best season</span><strong>{bestRank ? `P${bestRank}` : "—"}</strong></div>
            </div>
          </section>
          <div className="pw-hq-grid" style={{ marginTop: 14 }}>
            {[["wins", "Most wins"], ["podiums", "Most podiums"], ["points", "Most points"]].map(([key, title]) => (
              <section className="pw-panel" key={key}>
                <h2>{title}</h2>
                {top(key).length === 0 ? <p className="pw-empty">No data yet.</p> : (
                  <ol className="pw-standings-list">
                    {top(key).map((r, i) => (
                      <li key={r.name}><span className="pw-pos">{i + 1}</span>{r.name} <Stars name={r.name} /><span className="pw-final-gap">{r[key]}</span></li>
                    ))}
                  </ol>
                )}
              </section>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

/* ============================== MAIN APP ============================== */

export default function App() {
  const [screen, setScreen] = useState("calendar"); // 'calendar' | 'development' | 'qualifying' | 'race'
  const [season, setSeason] = useState(makeInitialSeason);
  const [saveLoaded, setSaveLoaded] = useState(false);
  const settings = useSettings(); // re-render on settings changes (team name / colour…)
  CURRENT_TITLES = season.titles || {};
  const [press, setPress] = useState(null); // post-race press room state

  useEffect(() => {
    (async () => {
      try {
        const raw = await storageAdapter.get(SETTINGS_KEY);
        if (raw) updateSettings({ ...DEFAULT_SETTINGS, ...JSON.parse(raw) }, false);
      } catch (e) { /* defaults */ }
    })();
  }, []);

  // Load any existing career from persistent storage once, before the first
  // real render decision — otherwise we'd briefly flash the team-select
  // screen for a returning player.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const value = await storageAdapter.get(SAVE_KEY);
        if (!cancelled && value) {
          setSeason(normalizeSeason(JSON.parse(value)));
        }
      } catch (e) {
        // no save yet, or storage unavailable — start fresh
      } finally {
        if (!cancelled) setSaveLoaded(true);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  // Auto-save on every career change (team/driver choices, development,
  // race results, off-season decisions). Race-in-progress state is not
  // persisted — reloading mid-race drops back to Team HQ, which is a fair
  // trade-off for keeping saves simple and always in a consistent state.
  useEffect(() => {
    if (!saveLoaded) return;
    (async () => {
      try {
        await storageAdapter.set(SAVE_KEY, JSON.stringify(season));
      } catch (e) {
        // best-effort — a failed save shouldn't interrupt play
      }
    })();
  }, [season, saveLoaded]);

  function startNewCareer() {
    (async () => {
      try {
        await storageAdapter.del(SAVE_KEY);
      } catch (e) {
        // ignore — the next auto-save will overwrite it anyway
      }
    })();
    setSeason(makeInitialSeason());
    setScreen("calendar");
    setCars([]);
    setFinished(false);
  }

  // ---- Named saves ----
  const [saves, setSaves] = useState([]);
  const [savesOpen, setSavesOpen] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const raw = await storageAdapter.get(SAVES_KEY);
        if (raw) { const list = JSON.parse(raw); if (Array.isArray(list)) setSaves(list); }
      } catch (e) { /* no saves */ }
    })();
  }, []);

  async function persistSaves(list) {
    setSaves(list);
    try { await storageAdapter.set(SAVES_KEY, JSON.stringify(list)); } catch (e) { /* best-effort */ }
  }
  const newSaveId = () => `s${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

  async function saveCurrentGame(name) {
    const snapshot = JSON.parse(JSON.stringify(season));
    const idx = saves.findIndex((s) => s.name.toLowerCase() === name.toLowerCase());
    const entry = { id: idx >= 0 ? saves[idx].id : newSaveId(), name, savedAt: Date.now(), season: snapshot };
    const list = idx >= 0 ? saves.map((s, i) => (i === idx ? entry : s)) : [entry, ...saves];
    await persistSaves(list);
  }

  async function importSave(text) {
    const res = parseImportedSave(text);
    if (res.error) return res;
    let name = res.name;
    let n = 2;
    while (saves.some((s) => s.name.toLowerCase() === name.toLowerCase())) name = `${res.name} (${n++})`;
    await persistSaves([{ id: newSaveId(), name, savedAt: res.savedAt, season: res.season }, ...saves]);
    return { name };
  }

  function loadSavedGame(id) {
    const s = saves.find((x) => x.id === id);
    if (!s) return;
    setSeason(normalizeSeason(JSON.parse(JSON.stringify(s.season))));
    setScreen("calendar");
    setCars([]);
    setFinished(false);
  }

  async function renameSave(id, name) {
    const clash = saves.some((s) => s.id !== id && s.name.toLowerCase() === name.toLowerCase());
    const finalName = clash ? `${name} (2)` : name;
    await persistSaves(saves.map((s) => (s.id === id ? { ...s, name: finalName } : s)));
  }

  async function deleteSave(id) {
    await persistSaves(saves.filter((s) => s.id !== id));
  }

  const savesPanel = (
    <SavesPanel
      open={savesOpen}
      onClose={() => setSavesOpen(false)}
      saves={saves}
      hasGame={!!season.teamTierId}
      currentSeason={season}
      onSave={saveCurrentGame}
      onLoad={loadSavedGame}
      onRename={renameSave}
      onDelete={deleteSave}
      onImport={importSave}
    />
  );

  useEffect(() => {
    if (!season.teamTierId || !season.sponsorObjective || season.board?.objective || season.board?.fired) return;
    if (season.playerDrivers.length < 2 || !season.playerDrivers.every(Boolean)) return;
    setSeason((prev) => ({ ...prev, board: { ...(prev.board || {}), confidence: prev.board?.confidence ?? 60, objective: generateBoardObjective(prev) } }));
  }, [season.teamTierId, season.sponsorObjective, season.board, season.playerDrivers]);

  const currentRound = season.calendar[season.roundIndex];
  const currentCircuit = currentRound ? circuitById(currentRound.circuitId) : null;

  const [cars, setCars] = useState([]);
  const [speed, setSpeed] = useState(1);
  const [raceClock, setRaceClock] = useState(0);
  const [condition, setCondition] = useState("dry");
  const [rainChance, setRainChance] = useState(8);
  const [cautionSectorsUI, setCautionSectorsUI] = useState([]); // e.g. [2] — 1-based sector numbers currently under yellow
  const [events, setEvents] = useState([{ id: 0, lap: 0, text: "Lights out! The race is underway.", type: "flag" }]);
  const [activeCarId, setActiveCarId] = useState(0);
  const [finished, setFinished] = useState(false);
  const [pathLen, setPathLen] = useState(0);
  const [raceLoading, setRaceLoading] = useState(false);
  const [geoReady, setGeoReady] = useState(false);
  const [geoStage, setGeoStage] = useState(0);
  const [gridHold, setGridHold] = useState(false);
  const [startLights, setStartLights] = useState(0);
  const [raceId, setRaceId] = useState(0);
  const [qualiRoster, setQualiRoster] = useState(null);
  const [qualiTimes, setQualiTimes] = useState(null);
  const [startTireChoice, setStartTireChoice] = useState({});
  const [startEngineMode, setStartEngineMode] = useState({});
  const [carSetups, setCarSetups] = useState({});
  const [practiceReport, setPracticeReport] = useState(null);
  const [weekendForm, setWeekendForm] = useState({});
  const pathRef = useRef(null);
  const eventIdRef = useRef(1);
  const lapSeenRef = useRef({});
  const orderRef = useRef([]);
  const cautionRef = useRef([0, 0, 0]); // remaining ticks of yellow, per sector (0/1/2)
  const scRef = useRef({ mode: null, endLap: 0 }); // Safety Car / Virtual Safety Car
  const [scMode, setScMode] = useState(null);
  const pitStopRef = useRef({});
  const pitHistoryRef = useRef({});
  const strategistLapRef = useRef(0);
  const engineerLapRef = useRef(0);
  const rainChanceRef = useRef(8);

  useEffect(() => {
    if (screen === "race" && pathRef.current) {
      setPathLen(pathRef.current.getTotalLength());
    }
  }, [screen, currentCircuit, raceId]);

  // The loading overlay sits on top of the already-mounted race UI, so the
  // circuit geometry gets measured and sampled underneath it. It only lifts
  // once a minimum time has passed AND the track path is actually ready —
  // no pop-in of missing scenery when the lights go out.
  const [loadMinElapsed, setLoadMinElapsed] = useState(false);
  useEffect(() => {
    if (screen === "race" && raceLoading) {
      setLoadMinElapsed(false);
      const t = setTimeout(() => setLoadMinElapsed(true), 1000);
      return () => clearTimeout(t);
    }
  }, [screen, raceLoading, raceId]);

  // While the loading screen is up, build the racing line, scenery, pit lane
  // and sector overlays so none of it has to be computed during the race.
  useEffect(() => {
    if (screen === "race" && raceLoading && pathLen > 0 && pathRef.current && currentCircuit) {
      let dead = false;
      setGeoStage(0);
      prepareTrackGeometry(currentCircuit, pathRef.current, pathLen, (n) => { if (!dead) setGeoStage(n); }).then(() => { if (!dead) setGeoReady(true); });
      return () => { dead = true; };
    }
  }, [screen, raceLoading, pathLen, currentCircuit]);

  // Lights out: the circuit speaker calls the start once loading is done.
  const wasLoadingRef = useRef(false);
  useEffect(() => {
    let timers = [];
    if (screen === "race" && wasLoadingRef.current && !raceLoading) {
      const fresh = standings.length > 0 && standings.every((c) => !c.lapsCompleted && !c.timeInLap);
      if (fresh) {
        // Formation on the grid, five red lights, then lights out.
        setStartLights(0);
        setGridHold(true);
        for (let k = 1; k <= 5; k++) timers.push(setTimeout(() => setStartLights(k), 700 + k * 800));
        timers.push(setTimeout(() => {
          setStartLights(0);
          setGridHold(false);
          Sound.launch(9);
          Sound.say("Lights out!", "speaker");
        }, 700 + 5 * 800 + 700 + Math.random() * 900));
      } else {
        Sound.say("Green flag!", "speaker");
      }
    }
    wasLoadingRef.current = raceLoading;
    return () => timers.forEach(clearTimeout);
  }, [raceLoading, screen]);

  // Circuit ambience while the cars are running; crowd at the flag
  useEffect(() => {
    Sound.ambience(screen === "race" && !finished && !raceLoading && !gridHold && speed > 0);
  }, [screen, finished, raceLoading, gridHold, speed]);
  useEffect(() => () => Sound.ambience(false), []);
  useEffect(() => {
    if (screen === "race" && finished) Sound.cheer();
  }, [finished, screen]);
  // Wheel guns when one of our cars is stationary in its box
  useEffect(() => {
    if (screen !== "race") return;
    cars.forEach((c) => {
      if (!c.team?.isPlayer) return;
      const st = !!(c.inPit && pitProfile(c)?.stopped);
      if (st && !pitStopRef.current[c.id]) Sound.pitGun();
      pitStopRef.current[c.id] = st;
    });
  }, [cars, screen]);

  useEffect(() => {
    if (raceLoading && loadMinElapsed && pathLen > 0 && geoReady) {
      setRaceLoading(false);
    }
  }, [raceLoading, loadMinElapsed, pathLen, geoReady]);

  useEffect(() => {
    rainChanceRef.current = rainChance;
  }, [rainChance]);

  const pushEvent = useCallback((lap, text, type = "info") => {
    // The id is captured NOW: this is often called from inside another
    // state updater, and reading the ref later (when React flushes) gave many
    // events the same id/key — which scrambled the list order and made the
    // type filters show stale rows.
    const id = ++eventIdRef.current;
    // Keep a generous history — with a small cap, rare event types (flags,
    // weather) used to get pushed out entirely by frequent ones (pit stops,
    // overtakes), which made filtering by type look broken/empty.
    setEvents((prev) => {
      // Updaters may run twice (strict mode); never log the same event twice.
      if (prev.slice(0, 20).some((e) => e.text === text && e.lap === lap)) return prev;
      return [{ id, lap, text, type }, ...prev].slice(0, 150);
    });
  }, []);

  function completeTesting() {
    setSeason((prev) => ({ ...prev, needsTesting: false }));
    setScreen("calendar");
  }

  function goToFiaReport() {
    setScreen("fiaReport");
  }

  function goToPractice() {
    setWeekendForm(rollWeekendForm(TEAMS.length * 2));
    setPracticeReport(runPracticeSession());
    setScreen("practice");
  }

  function goToSetup() {
    const roster = buildRosterFromSeason(season, weekendForm);
    setQualiRoster(roster);
    const rec = recommendedSetup(currentCircuit);
    const setups = {};
    roster.forEach((r) => {
      setups[r.id] = r.team.isPlayer ? rec : chooseAiSetup(currentCircuit);
    });
    setCarSetups(setups);
    setScreen("setup");
  }

  function goToQualifying() {
    const times = qualiRoster
      .map((r) => ({ id: r.id, time: computeQualiTime(r, currentCircuit, season.playerDev, season.teamPerf, carSetups[r.id]) }))
      .sort((a, b) => a.time - b.time);
    setQualiTimes(times);
    setScreen("qualifying");
  }

  function goToTireChoice() {
    const advice = strategistTireAdvice(currentCircuit, practiceReport);
    const defaults = {};
    const engineDefaults = {};
    qualiRoster.filter((r) => r.team.isPlayer).forEach((r) => {
      defaults[r.id] = advice.compound;
      engineDefaults[r.id] = "standard";
    });
    setStartTireChoice(defaults);
    setStartEngineMode(engineDefaults);
    setScreen("tireChoice");
  }

  function chooseTeamTier(tierId) {
    const tier = TEAM_TIERS.find((t) => t.id === tierId);
    if (!tier) return;
    setSeason((prev) => {
      const usedNames = Object.values(prev.aiRosters).flat().map((d) => d.name);
      return {
        ...prev,
        calendar: buildCalendar(), // honour the season-length setting chosen before the career started
        teamTierId: tierId,
        budget: tier.budget,
        devPoints: tier.devPoints,
        staff: { ...tier.staff },
        sponsorObjective: null,
        teamPerf: { ...prev.teamPerf, mclaren: tier.perf },
        driverMarket: generateMarketPool(6, usedNames, tier.driverSkillRange),
      };
    });
  }

  function investStaff(role) {
    setSeason((prev) => {
      const level = prev.staff[role];
      if (level >= 1) return prev;
      const cost = staffCost(level);
      if (prev.budget < cost) return prev;
      return {
        ...prev,
        budget: prev.budget - cost,
        staff: { ...prev.staff, [role]: Math.min(1, level + 0.08) },
      };
    });
  }

  function confirmDriverSelection(selectedDrivers) {
    setSeason((prev) => {
      const cost = selectedDrivers.reduce((sum, d) => sum + d.price, 0);
      return {
        ...prev,
        budget: prev.budget - cost,
        playerDrivers: selectedDrivers.map((d) => ({ ...d })),
        driverMarket: [],
      };
    });
  }

  function startRaceFromQuali() {
    setPathLen(0);
    setGeoReady(false);
    const gridOrder = qualiTimes.map((t) => t.id);
    const advice = strategistTireAdvice(currentCircuit, practiceReport);
    const carsBuilt = gridOrder.map((id, i) => {
      const entry = qualiRoster.find((r) => r.id === id);
      if (entry.team.isPlayer) {
        const compound = startTireChoice[id] || advice.compound;
        const engineMode = startEngineMode[id] || "standard";
        return carFromRoster(entry, currentCircuit.baseLap, i + 1, compound, "balanced", carSetups[id], currentCircuit, engineMode);
      }
      // Every AI team makes its own call on starting rubber — an aggressive
      // outfit gambles on Softs for track position, a conservative one
      // protects itself on Hards, weather/incident risk overrides both.
      const style = pickStrategyStyle();
      const compound = chooseAiStartCompound(style, currentCircuit, advice);
      return carFromRoster(entry, currentCircuit.baseLap, i + 1, compound, style, carSetups[id], currentCircuit, "standard");
    });
    setCars(carsBuilt);
    setRaceClock(0);
    setCondition("dry");
    setRainChance(8);
    cautionRef.current = [0, 0, 0];
    scRef.current = { mode: null, endLap: 0 };
    setScMode(null);
    setCautionSectorsUI([]);
    strategistLapRef.current = 0;
    engineerLapRef.current = 0;
    const poleName = qualiRoster.find((r) => r.id === gridOrder[0])?.name;

    // Build the opening moments as a small chronological batch: formation
    // lap, lights out, then whatever happened off the line — reaction time
    // is rolled per driver in carFromRoster, so a good or bad launch can
    // shuffle the order before the first corner even arrives.
    const startEvents = [
      { text: "Formation lap complete — the grid is set.", type: "flag" },
      { text: `Lights out at ${currentCircuit.name}! ${poleName} leads them away from pole.`, type: "flag" },
    ];
    carsBuilt.filter((c) => c.team.isPlayer).forEach((c) => {
      if (c.form >= 0.7) startEvents.push({ text: `Engineer: #${c.number} ${c.name} says the car feels perfect today — he is on fire, expect strong pace and a sharp launch.`, type: "strategist" });
      else if (c.form > 0) startEvents.push({ text: `Engineer: #${c.number} ${c.name} is feeling good in the car this weekend.`, type: "strategist" });
      else if (c.form <= -0.7) startEvents.push({ text: `Engineer: #${c.number} ${c.name} is struggling for confidence today — slower pace and a higher risk of mistakes. Be ready.`, type: "strategist" });
      else if (c.form < 0) startEvents.push({ text: `Engineer: #${c.number} ${c.name} is a little off his rhythm today.`, type: "strategist" });
    });
    carsBuilt.forEach((c) => {
      if (c.startDelta > 2.3) {
        startEvents.push({ text: `${c.name} (#${c.number}) nearly stalls at the start!`, type: "incident" });
      } else if (c.startDelta > 0.9 && c.team.isPlayer) {
        startEvents.push({ text: `${c.name} (#${c.number}) gets a poor launch off the line.`, type: "incident" });
      } else if (c.startDelta < -0.5) {
        startEvents.push({ text: `Great start for ${c.name} (#${c.number})!`, type: "overtake" });
      }
    });
    setEvents(startEvents.reverse().map((e, i) => ({ ...e, id: i, lap: 0 })));
    eventIdRef.current = startEvents.length;
    setActiveCarId(0);
    setFinished(false);
    setSpeed(1);
    orderRef.current = gridOrder;
    pitHistoryRef.current = {};
    lapSeenRef.current = {};
    Sound.unlock();
    setRaceId((id) => id + 1);
    setRaceLoading(true);
    setScreen("race");
  }

  function quitToHQ() {
    setSpeed(0);
    setScreen("calendar");
  }

  function continueToHQ() {
    const finalStandings = computeStandings(cars, currentCircuit, true);
    const seasonJustEnded = season.roundIndex + 1 >= season.calendar.length;
    const pressData = generatePress(finalStandings, currentCircuit, season);
    setPress({ ...pressData, next: seasonJustEnded ? "offseason" : "calendar" });
    setSeason((prev) => {
      const driverPoints = { ...prev.driverPoints };
      const constructorPoints = { ...prev.constructorPoints };
      const roundTeamPoints = {};
      TEAMS.forEach((t) => (roundTeamPoints[t.id] = 0));

      finalStandings.forEach((c, i) => {
        const pts = POINTS_TABLE[i] || 0;
        driverPoints[c.id] = (driverPoints[c.id] || 0) + pts;
        constructorPoints[c.teamId] = (constructorPoints[c.teamId] || 0) + pts;
        roundTeamPoints[c.teamId] = (roundTeamPoints[c.teamId] || 0) + pts;
      });

      const playerCarsFinal = finalStandings.filter((c) => c.team.isPlayer);
      const playerPtsThisRace = roundTeamPoints["mclaren"] || 0;
      // A modest base keeps a backmarker team afloat, but real funding comes
      // from scoring — a team stuck at the back should feel a genuinely slow
      // climb, not casually out-develop the field within a season.
      const devEarned = 42 + playerPtsThisRace * 3;
      const raceIncome = 25 + playerPtsThisRace * 7;

      const calendar = prev.calendar.map((r, i) =>
        i === prev.roundIndex
          ? { ...r, completed: true, playerResult: playerCarsFinal.map((c) => finalStandings.findIndex((x) => x.id === c.id) + 1) }
          : r
      );

      // At season's end, open a fresh driver market right away so the
      // off-season screen has replacement options ready if a seat is released.
      const usedNames = [
        ...Object.values(prev.aiRosters).flat().map((d) => d.name),
        ...prev.playerDrivers.filter(Boolean).map((d) => d.name),
      ];

      const posOf = (c) => finalStandings.findIndex((x) => x.id === c.id);
      const podThis = playerCarsFinal.filter((c) => c.status !== "dnf" && posOf(c) >= 0 && posOf(c) < 3).length;
      const dblThis = playerCarsFinal.length >= 2 && playerCarsFinal.every((c) => (POINTS_TABLE[posOf(c)] || 0) > 0) ? 1 : 0;
      const sponsorProgress = {
        podiums: (prev.sponsorProgress?.podiums || 0) + podThis,
        doublePoints: (prev.sponsorProgress?.doublePoints || 0) + dblThis,
      };
      let sponsorObjective = prev.sponsorObjective;
      let sponsorBonus = 0;
      if (seasonJustEnded && sponsorObjective && !sponsorObjective.resolved) {
        const ranked = Object.entries(constructorPoints)
          .map(([tid, pts]) => ({ tid, pts }))
          .sort((a, b) => b.pts - a.pts);
        const finalRank = ranked.findIndex((r) => r.tid === "mclaren") + 1;
        const { achieved, resultText } = resolveSponsor(sponsorObjective, finalRank, sponsorProgress);
        sponsorObjective = { ...sponsorObjective, resolved: true, achieved, finalRank, resultText };
        if (achieved) sponsorBonus = sponsorObjective.bonus;
      }

      // Career progression happens once per season, right as it wraps up:
      // every driver ages, AI seats can change hands, and the player's own
      // two drivers age too so the off-season contract screen already shows
      // their new numbers before a renew/release decision is made.
      let aiRosters = prev.aiRosters;
      let transferNews = prev.transferNews;
      let playerDrivers = prev.playerDrivers;
      if (seasonJustEnded) {
        const evolved = evolveAiRosters(prev.aiRosters, prev.teamPerf);
        aiRosters = evolved.rosters;
        transferNews = evolved.news;
        playerDrivers = prev.playerDrivers.map((d) => (d ? ageDriver(d) : d));
      }

      // --- career statistics (per-driver records, season history, titles)
      const driverStats = { ...(prev.driverStats || {}) };
      finalStandings.forEach((c, i) => {
        const st = { races: 0, wins: 0, podiums: 0, points: 0, dnfs: 0, ...(driverStats[c.name] || {}) };
        const ran = c.status !== "dnf";
        st.races += 1;
        if (ran && i === 0) st.wins += 1;
        if (ran && i < 3) st.podiums += 1;
        st.points += POINTS_TABLE[i] || 0;
        if (!ran) st.dnfs += 1;
        driverStats[c.name] = st;
      });
      const driverHistory = [...(prev.driverHistory || []), { round: currentRound.round, pts: { ...driverPoints } }];
      let history = prev.history || [];
      let titles = prev.titles || {};
      if (seasonJustEnded) {
        const champSlot = Object.keys(driverPoints).sort((a, b) => driverPoints[b] - driverPoints[a])[0];
        const champCar = finalStandings.find((c) => String(c.id) === String(champSlot));
        const ctop = Object.keys(constructorPoints).sort((a, b) => constructorPoints[b] - constructorPoints[a])[0];
        const tally = seasonPlayerTally(calendar);
        if (champCar) {
          titles = { ...titles, [champCar.name]: (titles[champCar.name] || 0) + 1 };
          history = [
            ...history,
            {
              season: prev.seasonNumber,
              champion: { name: champCar.name, teamId: champCar.teamId, pts: driverPoints[champSlot] },
              constructorChampion: { teamId: ctop, pts: constructorPoints[ctop] },
              player: {
                rank: playerRankFromPoints(constructorPoints),
                pts: constructorPoints[TEAMS.find((t) => t.isPlayer).id] || 0,
                wins: tally.wins,
                podiums: tally.podiums,
              },
            },
          ];
        }
      }

      // --- board confidence / verdict
      const boardRes = updateBoardAfterRace(prev.board, {
        constructorPoints,
        calendar,
        seasonJustEnded,
        playerPositions: calendar[prev.roundIndex].playerResult || [],
        round: currentRound.round,
      });
      sponsorBonus += boardRes.bonus;
      const pressLog = [
        ...pressData.articles.map((a) => ({ ...a, season: prev.seasonNumber, round: currentRound.round })),
        ...(prev.pressLog || []),
      ].slice(0, 12);

      return {
        ...prev,
        driverStats,
        driverHistory,
        history,
        titles,
        board: boardRes.board,
        pressLog,
        calendar,
        driverPoints,
        constructorPoints,
        devPoints: prev.devPoints + devEarned,
        budget: prev.budget + raceIncome + sponsorBonus,
        lastRacePerf: prev.teamPerf,
        teamPerf: aiDevelopmentTick(prev.teamPerf, prev.roundIndex),
        raceHistory: [...prev.raceHistory, { round: currentRound.round, teamPoints: roundTeamPoints }],
        roundIndex: Math.min(prev.roundIndex + 1, calendar.length),
        driverMarket: seasonJustEnded ? generateMarketPool(6, usedNames, getTierSkillRange(prev.teamTierId)) : prev.driverMarket,
        sponsorObjective,
        sponsorProgress,
        aiRosters,
        transferNews,
        playerDrivers,
      };
    });
    setScreen("press");
  }

  function answerPress(opt) {
    let conf = opt.effect.conf || 0;
    let backfired = false;
    if (opt.effect.risk && Math.random() < opt.effect.risk.p) {
      conf = opt.effect.risk.conf;
      backfired = true;
    }
    const budget = opt.effect.budget || 0;
    setSeason((prev) => ({
      ...prev,
      budget: prev.budget + budget,
      board: { ...(prev.board || {}), confidence: Math.max(0, Math.min(100, (prev.board?.confidence ?? 60) + conf)) },
    }));
    setPress((p) => ({ ...p, answered: { reply: opt.reply, conf, budget, backfired } }));
  }

  function finishPress() {
    const next = press ? press.next : "calendar";
    setPress(null);
    setScreen(next);
  }

  function renewDriver(seatIndex) {
    setSeason((prev) => {
      const driver = prev.playerDrivers[seatIndex];
      if (!driver || prev.budget < driver.price) return prev;
      const updated = [...prev.playerDrivers];
      updated[seatIndex] = { ...driver };
      return { ...prev, budget: prev.budget - driver.price, playerDrivers: updated };
    });
  }

  function releaseDriver(seatIndex) {
    setSeason((prev) => {
      const usedNames = [
        ...Object.values(prev.aiRosters).flat().map((d) => d.name),
        ...prev.playerDrivers.filter(Boolean).map((d) => d.name),
      ];
      const updated = [...prev.playerDrivers];
      updated[seatIndex] = null;
      return {
        ...prev,
        playerDrivers: updated,
        driverMarket: prev.driverMarket.length ? prev.driverMarket : generateMarketPool(6, usedNames, getTierSkillRange(prev.teamTierId)),
      };
    });
  }

  function hireDriver(seatIndex, driver) {
    setSeason((prev) => {
      if (prev.budget < driver.price) return prev;
      const updated = [...prev.playerDrivers];
      updated[seatIndex] = { ...driver };
      return {
        ...prev,
        budget: prev.budget - driver.price,
        playerDrivers: updated,
        driverMarket: prev.driverMarket.filter((d) => d.id !== driver.id),
      };
    });
  }

  function chooseSponsor(offer) {
    setSeason((prev) => ({
      ...prev,
      budget: prev.budget + offer.upfront,
      sponsorObjective: { ...offer, resolved: false, achieved: false },
      sponsorProgress: { podiums: 0, doublePoints: 0 },
    }));
  }

  function startNewSeason() {
    setSeason((prev) => ({
      ...prev,
      seasonNumber: prev.seasonNumber + 1,
      roundIndex: 0,
      calendar: buildCalendar(),
      driverPoints: {},
      constructorPoints: {},
      raceHistory: [],
      driverHistory: [],
      board: { ...(prev.board || {}), objective: null },
      lastRacePerf: prev.teamPerf,
      teamPerf: preseasonShuffle(prev.teamPerf),
      budget: prev.budget + SEASON_SIGNING_BONUS,
      driverMarket: [],
      sponsorObjective: null,
      sponsorProgress: { podiums: 0, doublePoints: 0 },
      needsTesting: true,
    }));
    setScreen("calendar");
  }

  function investDev(stat) {
    setSeason((prev) => {
      const level = prev.playerDev[stat];
      if (level >= 1.2) return prev;
      const { points, money } = devCost(level, prev.staff.technicalDirector);
      if (prev.devPoints < points || prev.budget < money) return prev;
      return {
        ...prev,
        devPoints: prev.devPoints - points,
        budget: prev.budget - money,
        playerDev: { ...prev.playerDev, [stat]: Math.min(1.2, level + 0.05) },
      };
    });
  }

  /* ---------- Simulation tick ---------- */
  useEffect(() => {
    if (screen !== "race" || speed === 0 || finished || !currentCircuit || raceLoading || gridHold) return;
    const interval = setInterval(() => {
      setRaceClock((rc) => rc + 1 * speed);
      setRainChance((rc) => Math.min(100, Math.max(0, rc + (Math.random() - 0.5) * 4 * currentCircuit.rainRisk)));

      setCars((prevCars) => {
        const approxLap = Math.min(Math.max(...prevCars.map((c) => c.lapsCompleted)) + 1, currentCircuit.laps);

        // Every car about to cross the line makes its own pass-by sound. It is
        // fired two ticks ahead of the crossing (one tick earlier than the
        // crossing itself) so the engine's loudest moment lands on the line.
        {
          let n = 0;
          prevCars.forEach((c) => {
            if (c.status === "dnf") return;
            const nextLap = c.lapsCompleted + 1;
            const seen = lapSeenRef.current[c.id] ?? 0;
            if (nextLap > seen && nextLap <= currentCircuit.laps && c.timeInLap + 2 * speed >= c.currentLapTarget && n < 4) {
              lapSeenRef.current[c.id] = nextLap;
              Sound.car(c.id, { inPit: c.inPit, stagger: n++ });
            }
          });
        }

        // --- sector-local yellow flags: trigger / countdown ---
        // Each sector tracks its own remaining caution time, so a yellow in
        // Sector 2 never touches pace in Sectors 1 or 3 — and since pitting
        // doesn't change which sector a car's lap-time formula accounts for,
        // a pit stop can't be used to dodge a sector's penalty.
        for (let s = 0; s < 3; s++) {
          if (cautionRef.current[s] > 0) {
            cautionRef.current[s] -= speed;
            if (cautionRef.current[s] <= 0) {
              pushEvent(approxLap, `Green flag — Sector ${s + 1} is clear.`, "flag");
            }
          }
        }
        if (approxLap > 2 && approxLap < currentCircuit.laps - 2) {
          const clearSectors = [0, 1, 2].filter((s) => cautionRef.current[s] <= 0);
          if (clearSectors.length && Math.random() < 0.00012 * speed * currentCircuit.incidentRisk) {
            const sector = clearSectors[Math.floor(Math.random() * clearSectors.length)];
            cautionRef.current[sector] = 140 + Math.random() * 90; // sim seconds
            pushEvent(approxLap, `Yellow flag in Sector ${sector + 1}! Incident reported — cars slow through that section only.`, "flag");
            Sound.say(`Yellow flag, sector ${sector + 1}`, "speaker");
          }
        }
        const cautionSectors = [cautionRef.current[0] > 0, cautionRef.current[1] > 0, cautionRef.current[2] > 0];
        if (scRef.current.mode && approxLap >= scRef.current.endLap) {
          const was = scRef.current.mode;
          scRef.current = { mode: null, endLap: 0 };
          if (was === "SC") {
            pushEvent(approxLap, "Safety Car in this lap — the leader controls the restart. Green flag, racing resumes!", "flag");
            Sound.launch(9);
          } else {
            pushEvent(approxLap, "VSC ending — green flag, back to racing speed.", "flag");
            Sound.launch(5);
          }
        }
        setScMode(scRef.current.mode);
        const neutralT = scRef.current.mode ? currentCircuit.baseLap * (scRef.current.mode === "SC" ? 1.5 : 1.35) : null;
        const caution = !!scRef.current.mode;
        const yellowAt = (c) => {
          if (c.inPit || !cautionSectors.some(Boolean)) return false;
          const d = distFracOf(c.timeInLap / Math.max(c.currentLapTarget, 1));
          return cautionSectors[Math.min(2, Math.floor(d * 3))];
        };
        setCautionSectorsUI(cautionSectors.map((c, i) => (c ? i + 1 : null)).filter(Boolean));

        // Strategist update every 10 laps: our own cars' tyre state plus a
        // weather read, so you get a periodic prompt without watching the
        // sidebar constantly.
        if (approxLap > 0 && approxLap % 10 === 0 && strategistLapRef.current !== approxLap) {
          strategistLapRef.current = approxLap;
          const ourCars = prevCars.filter((c) => c.team.isPlayer);
          const tireBits = ourCars.map((c) => {
            if (c.status === "dnf") return `#${c.number} retired`;
            const cliffIn = Math.max(COMPOUNDS[c.compound].cliffAge - c.tireAge, 0);
            const cliffText = cliffIn <= 0 ? "past its cliff" : `~${cliffIn} laps from its cliff`;
            return `#${c.number} on ${COMPOUNDS[c.compound].label} (${c.tireAge}L, ${cliffText})`;
          });
          const rc = Math.round(rainChanceRef.current);
          const weatherBit =
            condition === "dry"
              ? `track dry, rain risk ${rc}%`
              : `track ${condition}, rain risk ${rc}%`;
          pushEvent(approxLap, `Strategist: ${tireBits.join(" · ")}. Weather — ${weatherBit}.`, "strategist");
        }

        // Engineer radio midway between strategist calls: how each of our
        // drivers is coping given today's form.
        if (approxLap > 0 && approxLap % 10 === 5 && engineerLapRef.current !== approxLap) {
          engineerLapRef.current = approxLap;
          prevCars.filter((c) => c.team.isPlayer && c.status !== "dnf" && (c.form ?? 0) !== 0).forEach((c) => {
            const lastGood = c.lapHistory.length ? c.lapHistory[c.lapHistory.length - 1].time : null;
            const lapBit = lastGood ? ` Last lap ${fmtLap(lastGood)}.` : "";
            const msg =
              c.form > 0
                ? `Engineer: #${c.number} is in the groove today — good rhythm, the car is working for him.${lapBit}`
                : `Engineer: #${c.number} is not comfortable today — watch for mistakes, consider a safer approach.${lapBit}`;
            pushEvent(approxLap, msg, "strategist");
          });
        }

        const oldOrder = orderRef.current;
        const justExitedPit = [];
        let anyFinished = false;

        // Gap to the car directly ahead (not the leader) for each car —
        // this is what actually drives slipstream/dirty-air, computed from
        // last tick's running order and pace so it's available the instant a
        // lap completes and a new lap time needs to be set.
        const gapAheadMap = {};
        const aheadIdMap = {};
        {
          const runningScored = prevCars
            .filter((c) => c.status !== "dnf")
            .map((c) => ({ id: c.id, score: c.lapsCompleted + Math.min(c.timeInLap / Math.max(c.currentLapTarget, 1), 0.999), pace: c.currentLapTarget }))
            .sort((a, b) => b.score - a.score);
          for (let i = 1; i < runningScored.length; i++) {
            const ahead = runningScored[i - 1];
            const behind = runningScored[i];
            gapAheadMap[behind.id] = (ahead.score - behind.score) * ahead.pace;
            aheadIdMap[behind.id] = ahead.id;
          }
        }

        let contactPair = null;
        // Lap 1 is when the whole field is still bunched up from the grid —
        // cold tyres, tight braking zones, cars three-wide into Turn 1. Both
        // contact and individual incidents are noticeably more likely.
        const firstLapContactMult = approxLap <= 1 ? 5.5 : 1;
        if (!caution && Math.random() < 0.00018 * currentCircuit.incidentRisk * firstLapContactMult) {
          const runningOrder = oldOrder.filter((id) => {
            const c = prevCars.find((x) => x.id === id);
            return c && c.status === "running" && !c.inPit;
          });
          if (runningOrder.length >= 2) {
            const idx = Math.floor(Math.random() * (runningOrder.length - 1));
            contactPair = [runningOrder[idx], runningOrder[idx + 1]];
            const a = prevCars.find((c) => c.id === contactPair[0]);
            const b = prevCars.find((c) => c.id === contactPair[1]);
            if (a && b) {
              pushEvent(approxLap, `Contact between ${a.name} and ${b.name}! Both lose ground.`, "incident");
            }
          }
        }

        const next = prevCars.map((car) => {
          if (car.status === "finished" || car.status === "dnf") return car;
          if (!car.inPit && car.timeInLap > 0) {
            if (neutralT && car.scHold == null) {
              car = { ...car, scHold: car.currentLapTarget, timeInLap: car.timeInLap * (neutralT / car.currentLapTarget), currentLapTarget: neutralT };
            } else if (!neutralT && car.scHold != null) {
              car = { ...car, scHold: null, timeInLap: car.timeInLap * (car.scHold / car.currentLapTarget), currentLapTarget: car.scHold };
            }
          }
          const dt = 1 * speed;
          // Yellow flag: only the time spent inside the flagged sector is slowed,
          // so every car pays the same price whenever it crosses the line.
          let dtRun = dt;
          if (yellowAt(car)) {
            dtRun = dt / YELLOW_SLOW;
            car = { ...car, lapExtra: (car.lapExtra || 0) + (dt - dtRun) };
          }
          let timeInLap = car.timeInLap + dtRun;
          let penaltyAdd = 0;
          let pitState = car.inPit && car.pit ? car.pit : null;
          if (pitState) {
            pitState = { ...pitState, t: pitState.t + dt };
            if (pitState.t >= pitState.D) {
              if (pitState.crossed) {
                // Out of the lane: back on the racing line at 5% of the lap.
                justExitedPit.push(car.id);
                return { ...car, inPit: false, pit: null, timeInLap: PIT_TIME.exit * car.currentLapTarget };
              }
              // The stop ended in the same tick as the line crossing (fast
              // sim speeds): hold the car at the lane exit for this tick so the
              // lap is validated first, then it leaves on the next one.
              pitState = { ...pitState, t: pitState.D - 0.001 };
            }
            const prof = pitProfile({ ...car, pit: pitState });
            const frac = PIT_TIME.entry + pitSpan() * prof.u;
            timeInLap = (pitState.crossed ? frac - 1 : frac) * car.currentLapTarget;
          }

          if (contactPair && contactPair.includes(car.id)) {
            timeInLap += 3 + seeded(car.id, approxLap * 13 + 7) * 4;
            // The car behind is usually the one at fault
            if (car.id === contactPair[1] && seeded(car.id, approxLap * 17 + 3) < 0.6) {
              penaltyAdd = 5;
              pushEvent(approxLap, `Stewards: ${car.name} (#${car.number}) given a 5s time penalty for causing a collision.`, "steward");
            }
          }

          // Pit entry: the car commits to the stop when it reaches the pit lane
          // entrance (just before the line), not after crossing the line.
          const entryT = PIT_TIME.entry * car.currentLapTarget;
          if (
            !car.inPit && car.status === "running" &&
            car.lapsCompleted + 1 < currentCircuit.laps &&
            car.timeInLap < entryT && timeInLap >= entryT
          ) {
            let wantsPit = car.pitQueued ? car.pendingCompound : null;
            const lapsRemaining = currentCircuit.laps - (car.lapsCompleted + 1);
            const probe = { ...car, lapsCompleted: car.lapsCompleted + 1, tireAge: car.tireAge + 1 };
            if (!wantsPit && car.forcedPit) {
              wantsPit = pickCompound(probe, ["MEDIUM", "HARD"]);
            } else if (!wantsPit && !car.team.isPlayer) {
              const position = oldOrder.indexOf(car.id) + 1;
              const rivalBehindId = position > 0 ? oldOrder[position] : null;
              const rivalBehindPitLap = rivalBehindId != null ? pitHistoryRef.current[rivalBehindId] : null;
              const rivalBehindPitted = rivalBehindPitLap != null && probe.lapsCompleted - rivalBehindPitLap <= 2;
              wantsPit = decideAiPit(probe, condition, lapsRemaining, caution, { rivalBehindPitted, leading: position === 1 });
            }
            if (wantsPit) {
              const prevPos = (oldOrder.indexOf(car.id) + 1) || "?";
              const pc = {
                ...car,
                timeInLap: entryT,
                penaltySec: (car.penaltySec || 0) + penaltyAdd,
                compound: wantsPit,
                tireAge: 0,
                pitCount: car.pitCount + 1,
                pitQueued: false,
                pendingCompound: null,
                forcedPit: false,
                inPit: true,
                stintTargetLaps: stintTargetForStyle(car.strategyStyle || "balanced"),
              };
              pitHistoryRef.current[pc.id] = probe.lapsCompleted;
              const crewLevel = car.team.isPlayer ? season.staff.pitCrew : 0.5;
              const { loss, tier } = rollPitLoss(pc.id, pc.pitCount, crewLevel);
              pc.pendingPitLoss = loss;
              // Time penalties can be served standing still in the box
              if (pc.penaltySec > 0) {
                const served = pc.penaltySec;
                pc.pendingPitLoss = loss + served;
                pc.penaltySec = 0;
                pushEvent(approxLap, `Stewards: ${car.name} (#${car.number}) serves a ${served}s penalty during the stop.`, "steward");
              }
              if (seeded(pc.id, probe.lapsCompleted * 41 + 9) < 0.035) {
                pc.penaltySec = 5;
                pushEvent(approxLap, `Stewards: ${car.name} (#${car.number}) caught speeding in the pit lane — 5s time penalty.`, "steward");
              }
              // The stop's own clock: lane transit in, stand still, transit out.
              // Total = time lost in the stop + the time the lane would take at race pace.
              pc.pit = {
                t: 0,
                loss: pc.pendingPitLoss,
                D: pc.pendingPitLoss + pitSpan() * car.currentLapTarget,
                tr: Math.min(1.4, pc.pendingPitLoss * 0.18),
                crossed: false,
              };
              const tierText = tier === "botched" ? " Wheel gun drama — slow stop!" : tier === "slow" ? " Sluggish release." : " Clean stop.";
              pushEvent(
                approxLap,
                `${car.name} (#${car.number}) dives into the pits from P${prevPos} — fits ${COMPOUNDS[wantsPit].label} tyres.${tierText} (${pc.pendingPitLoss.toFixed(1)}s)`,
                "pit"
              );
              return pc;
            }
          }

          if (timeInLap < car.currentLapTarget) {
            const out = penaltyAdd ? { ...car, timeInLap, penaltySec: (car.penaltySec || 0) + penaltyAdd } : { ...car, timeInLap };
            if (pitState) out.pit = pitState;
            return out;
          }

          const wasInPit = car.inPit;
          // A lap that includes a stop is timed with the stop in it.
          const lapTime = car.currentLapTarget + (car.lapExtra || 0) + (pitState && !pitState.crossed ? pitState.loss : 0);
          let newCar = {
            ...car,
            lapsCompleted: car.lapsCompleted + 1,
            raceTime: car.raceTime + lapTime,
            lastLapTime: lapTime,
            lapExtra: 0,
            lapHistory: [...car.lapHistory, { lap: car.lapsCompleted + 1, time: lapTime, compound: car.compound }].slice(-40),
            timeInLap: pitState ? Math.max(0, timeInLap - car.currentLapTarget) : Math.min(timeInLap - car.currentLapTarget, 2),
            penaltySec: (car.penaltySec || 0) + penaltyAdd,
            tireAge: car.tireAge + 1,
            inPit: !!pitState,
            pit: pitState ? { ...pitState, crossed: true } : null,
          };

          const isFirstLap = newCar.lapsCompleted === 1;
          const incidentRoll = seeded(newCar.id, newCar.lapsCompleted * 31 + 17);
          const incidentMult = (1.35 - (newCar.consistency ?? 0.55) * 0.7) * (isFirstLap ? 3.2 : 1) * (1 - (newCar.form ?? 0) * 0.35);
          if (!wasInPit && incidentRoll < INCIDENT_PROB * currentCircuit.incidentRisk * incidentMult) {
            const kindRoll = seeded(newCar.id, newCar.lapsCompleted * 31 + 55);
            // On lap 1 it's almost always a racing incident (contact, a spin
            // avoiding someone) rather than a straight mechanical failure.
            const dnfCut = isFirstLap ? 0.1 : 0.22;
            const punctureCut = isFirstLap ? 0.28 : 0.4;
            if (kindRoll < dnfCut) {
              newCar.status = "dnf";
              pushEvent(approxLap, `${car.name} (#${car.number}) stops on track — retires with a mechanical issue!`, "incident");
              // A car parked on track usually neutralises the race.
              if (!scRef.current.mode && approxLap > 1 && approxLap < currentCircuit.laps - 3) {
                const r = seeded(newCar.id, newCar.lapsCompleted * 31 + 77);
                if (r < 0.75) {
                  const full = r < 0.35;
                  scRef.current = { mode: full ? "SC" : "VSC", endLap: approxLap + (full ? 3 + (Math.floor(r * 100) % 3) : 2) };
                  pushEvent(approxLap, full
                    ? `SAFETY CAR deployed to recover ${car.name}'s car — no overtaking, the field bunches up behind it. A cheap moment to pit!`
                    : `VIRTUAL SAFETY CAR — every driver must respect the delta while ${car.name}'s car is cleared.`, "flag");
                  Sound.say(full ? "Safety car, safety car" : "Virtual safety car deployed", "engineer");
                }
              }
              return newCar;
            } else if (kindRoll < punctureCut) {
              newCar.forcedPit = true;
              if (car.team.isPlayer) Sound.say("Box this lap", "engineer");
              pushEvent(approxLap, `${car.name} (#${car.number}) suffers a puncture — forced into the pits!`, "incident");
            } else {
              newCar.spinPenalty = 4 + seeded(newCar.id, newCar.lapsCompleted * 31 + 91) * 6;
              const msg = isFirstLap
                ? `${car.name} (#${car.number}) gets caught up in first-lap chaos and loses time!`
                : `${car.name} (#${car.number}) runs wide and loses time!`;
              pushEvent(approxLap, msg, "incident");
            }
          }

          if (!car.team.isPlayer) {
            newCar.engineMode = decideAiEngineMode(newCar);
          }

          const spinAdd = newCar.spinPenalty || 0;
          newCar.spinPenalty = 0;
          const gapAhead = gapAheadMap[car.id];

          // Occasional flavour commentary when the draft/dirty-air effect is
          // strong enough to matter, so the mechanic is visible in the feed.
          const draftEffect = draftDirtyAirEffect(gapAhead, currentCircuit);
          if (Math.abs(draftEffect) > 0.55 && Math.random() < 0.12) {
            if (draftEffect < 0) {
              pushEvent(approxLap, `${car.name} (#${car.number}) gets a strong tow down the straight!`, "overtake");
            } else {
              pushEvent(approxLap, `${car.name} (#${car.number}) is stuck in dirty air, losing time.`, "info");
            }
          }

          let rawPace = computeLapTarget(newCar, condition, currentCircuit, season.playerDev, season.teamPerf, cautionSectors, gapAhead);

          // Overtaking attempt: right behind a slower car, passing is not
          // automatic — the move can fail, leaving us stuck behind (or even
          // end in contact).
          const aheadCar = prevCars.find((c) => c.id === aheadIdMap[car.id]);
          if (
            aheadCar && !newCar.inPit && !caution && !cautionSectors[0] && !cautionSectors[2] && !justExitedPit.includes(newCar.id) &&
            aheadCar.status === "running" && !aheadCar.inPit &&
            gapAhead != null && gapAhead < 0.9 && gapAhead >= 0
          ) {
            const advantage = aheadCar.currentLapTarget - rawPace;
            if (advantage > 0.04) {
              const pSuccess = passSuccessChance(newCar, aheadCar, advantage, gapAhead, currentCircuit);
              if (Math.random() > pSuccess) {
                rawPace = Math.max(rawPace, aheadCar.currentLapTarget + 0.08 + Math.random() * 0.12);
                if (Math.random() < 0.45 && (newCar.team.isPlayer || aheadCar.team.isPlayer || (aheadIdMap[car.id] != null && oldOrder.indexOf(car.id) < 8))) {
                  pushEvent(approxLap, `${car.name} (#${car.number}) lines up ${aheadCar.name} but can't make the move stick.`, "overtake");
                }
                // A desperate lunge sometimes ends in contact
                if (Math.random() < 0.012 * (1.3 - (newCar.consistency ?? 0.55))) {
                  newCar.penaltySec = (newCar.penaltySec || 0) + 5;
                  newCar.spinPenalty = (newCar.spinPenalty || 0) + 2;
                  pushEvent(approxLap, `Stewards: ${car.name} (#${car.number}) clips ${aheadCar.name} going for the pass — 5s time penalty.`, "steward");
                }
              }
            }
          }

          // Track limits: pushing hard, in traffic or off-form means more
          // off-track moments. Repeated offences earn a time penalty.
          if (!newCar.inPit && newCar.status === "running") {
            const pushing = newCar.engineMode === "push" ? 1.5 : 1;
            const traffic = gapAhead != null && gapAhead < 0.8 ? 1.3 : 1;
            const pLimits = 0.05 * currentCircuit.incidentRisk * (1.5 - (newCar.consistency ?? 0.55)) * (1 - (newCar.form ?? 0) * 0.4) * pushing * traffic;
            if (Math.random() < pLimits) {
              newCar.limitStrikes = (newCar.limitStrikes || 0) + 1;
              rawPace -= 0.08; // the lap time gained by cutting it
              const n = newCar.limitStrikes;
              if (n < 3) {
                pushEvent(approxLap, `Track limits: ${car.name} (#${car.number}) runs wide — warning ${n}/3.`, "steward");
              } else if (n === 3) {
                pushEvent(approxLap, `Track limits: black-and-white flag for ${car.name} (#${car.number}) — next offence is a penalty.`, "steward");
              } else if ((n - 3) % 2 === 1) {
                newCar.penaltySec = (newCar.penaltySec || 0) + 5;
                pushEvent(approxLap, `Stewards: ${car.name} (#${car.number}) given a 5s time penalty for repeated track-limit offences.`, "steward");
              }
            }
          }

          newCar.currentLapTarget = rawPace + spinAdd;
          newCar.scHold = null;
          if (neutralT && !newCar.inPit) {
            newCar.scHold = newCar.currentLapTarget;
            newCar.currentLapTarget = neutralT + (seeded(newCar.id, newCar.lapsCompleted * 7 + 3) - 0.5) * 0.3;
          }

          if (newCar.lapsCompleted >= currentCircuit.laps) {
            newCar.status = "finished";
            anyFinished = true;
          }
          return newCar;
        });

        // Two cars cannot share the same piece of tarmac: unless the car behind
        // is genuinely quicker (a pass in progress), it sits a realistic
        // ~0.25s off the gearbox ahead instead of closing to zero.
        {
          const MIN_FOLLOW = 0.25;
          const field = next
            .filter((c) => c.status === "running" && !c.inPit)
            .map((c) => ({ c, sc: c.lapsCompleted + Math.min(c.timeInLap / Math.max(c.currentLapTarget, 1), 0.999) }))
            .sort((a, b) => b.sc - a.sc);
          for (let i = 1; i < field.length; i++) {
            const A = field[i - 1], B = field[i];
            const gap = (A.sc - B.sc) * B.c.currentLapTarget;
            const faster = B.c.currentLapTarget <= A.c.currentLapTarget - 0.05;
            const zoned = PASS_ZONES.length > 0 && B.c.lapsCompleted > 0;
            // A move needs a real pace advantage, and a driver who has just been
            // passed cannot simply take the place straight back.
            const scm = scRef.current.mode;
            if (scm === "SC" && gap > 0.9) {
              // queue up behind the safety car train
              B.c.timeInLap += Math.min(gap - 0.9, 0.12 * speed);
              B.sc = B.c.lapsCompleted + Math.min(B.c.timeInLap / Math.max(B.c.currentLapTarget, 1), 0.999);
            }
            const canMove = !scm && !yellowAt(B.c) && !yellowAt(A.c) && B.c.currentLapTarget <= A.c.currentLapTarget - 0.28 &&
              !(B.c.noRepass && B.c.noRepass.id === A.c.id && B.c.lapsCompleted < B.c.noRepass.until);
            if (canMove && zoned && gap >= 0 && gap < 0.45 && inPassZone(B.c.timeInLap / Math.max(B.c.currentLapTarget, 1))) {
              // The move is made here: slipstream down the straight, out-brake into the corner.
              A.c.noRepass = { id: B.c.id, until: A.c.lapsCompleted + 3 };
              if (typeof window !== "undefined") window.__PASSES = (window.__PASSES || 0) + 1;
              B.c.timeInLap += gap + 0.12;
              B.sc = B.c.lapsCompleted + Math.min(B.c.timeInLap / Math.max(B.c.currentLapTarget, 1), 0.999);
              field[i - 1] = B; field[i] = A;
              continue;
            }
            // (gap can be negative when the car ahead was itself just held back)
            // each driver sits at a slightly different distance, varying lap to lap
            const follow = MIN_FOLLOW + (((B.c.id * 37 + B.c.lapsCompleted * 11) % 10) / 10) * 0.4;
            if (gap < follow && (!faster || zoned || scRef.current.mode)) {
              const back = follow - gap;
              if (B.c.timeInLap > back) {
                B.c.timeInLap -= back;
                B.sc = B.c.lapsCompleted + Math.min(B.c.timeInLap / Math.max(B.c.currentLapTarget, 1), 0.999);
              }
            }
          }
        }

        // Real elapsed time per lap (holds behind other cars, Safety Car
        // bunching and yellow sectors all count) and sector splits S1/S2/S3,
        // interpolated inside the tick so they don't depend on sim speed.
        next.forEach((nc, idx) => {
          const pc = prevCars[idx];
          if (!pc || nc === pc || pc.status === "dnf" || pc.status === "finished") return;
          const dtR = speed;
          const dOf = (c) => (c.timeInLap > 0 ? distFracOf(c.timeInLap / Math.max(c.currentLapTarget, 1)) : 0);
          const cur = [...(pc.curSectors || [])];
          const sum = (a) => a.reduce((x, y) => x + y, 0);
          if (nc.lapsCompleted > pc.lapsCompleted) {
            const before = Math.max(0, pc.currentLapTarget - pc.timeInLap);
            const after = Math.max(0, nc.timeInLap);
            const reach = before + after > 0 ? (dtR * before) / (before + after) : dtR;
            const lapTime = (pc.lapClock || 0) + reach;
            // sectors still missing when the line is reached (very high sim speed)
            const dP = dOf(pc);
            while (cur.length < 2) {
              const bnd = (cur.length + 1) / 3;
              if (dP >= bnd) break;
              const a = (1 - bnd) / Math.max(1e-6, 1 - dP);
              cur.push((pc.lapClock || 0) + reach * (1 - a) - sum(cur));
            }
            const last = cur.length === 2 ? [cur[0], cur[1], lapTime - cur[0] - cur[1]] : null;
            const best = pc.bestSectors ? [...pc.bestSectors] : [Infinity, Infinity, Infinity];
            if (last && pc.lapsCompleted > 0) last.forEach((v, k) => { if (v > 0 && v < best[k]) best[k] = v; });
            nc.lapClock = dtR - reach;
            nc.lastLapTime = lapTime;
            nc.raceTime = (pc.raceTime || 0) + lapTime;
            if (nc.lapHistory && nc.lapHistory.length) {
              nc.lapHistory = [...nc.lapHistory];
              nc.lapHistory[nc.lapHistory.length - 1] = { ...nc.lapHistory[nc.lapHistory.length - 1], time: lapTime };
            }
            nc.lastSectors = last;
            nc.bestSectors = best;
            nc.curSectors = [];
          } else {
            nc.lapClock = (pc.lapClock || 0) + dtR;
            const dP = dOf(pc), dN = dOf(nc);
            while (cur.length < 2 && dN > dP) {
              const bnd = (cur.length + 1) / 3;
              if (!(dP < bnd && dN >= bnd)) break;
              const a = (dN - bnd) / (dN - dP);
              cur.push(nc.lapClock - a * dtR - sum(cur));
            }
            nc.curSectors = cur;
          }
        });

        const scored = next
          .filter((c) => c.status !== "dnf")
          .map((c) => ({ id: c.id, score: c.lapsCompleted + Math.min(c.timeInLap / Math.max(c.currentLapTarget, 1), 0.999) }))
          .sort((a, b) => b.score - a.score);
        const newOrder = scored.map((s) => s.id);

        if (oldOrder.length && newOrder.length) {
          for (let pos = 0; pos < newOrder.length; pos++) {
            if (newOrder[pos] !== oldOrder[pos] && pos < 8) {
              const overtaker = next.find((c) => c.id === newOrder[pos]);
              const overtaken = next.find((c) => c.id === oldOrder[pos]);
              if (
                overtaker &&
                overtaken &&
                overtaker.id !== overtaken.id &&
                overtaken.status !== "dnf" &&
                !justExitedPit.includes(overtaker.id) &&
                !justExitedPit.includes(overtaken.id) &&
                overtaker.lapsCompleted === overtaken.lapsCompleted
              ) {
                pushEvent(approxLap, `${overtaker.name} passes ${overtaken.name} for P${pos + 1}.`, "overtake");
              }
              break;
            }
          }
        }

        justExitedPit.forEach((id) => {
          const c = next.find((x) => x.id === id);
          const pos = newOrder.indexOf(id) + 1;
          if (c) pushEvent(approxLap, `${c.name} (#${c.number}) rejoins the track in P${pos || "?"}.`, "pit");
        });

        orderRef.current = newOrder.length ? newOrder : oldOrder;

        if (anyFinished) {
          const leaderId = newOrder[0];
          const leaderCar = next.find((c) => c.id === leaderId);
          if (leaderCar && leaderCar.status === "finished") {
            setFinished(true);
            pushEvent(currentCircuit.laps, "CHEQUERED FLAG! The race is over.", "flag");
          }
        }

        return next;
      });
    }, TICK_MS);
    return () => clearInterval(interval);
  }, [screen, speed, finished, condition, currentCircuit, season.playerDev, season.teamPerf, season.staff, raceLoading, gridHold, pushEvent]);

  /* ---------- Weather condition shifts ---------- */
  useEffect(() => {
    if (screen !== "race") return;
    if (rainChance > 85 && condition === "dry") {
      setCondition("damp");
      pushEvent(cars[0]?.lapsCompleted ?? 0, "Rain starting to fall around the circuit.", "weather");
    } else if (rainChance > 96 && condition === "damp") {
      setCondition("wet");
      pushEvent(cars[0]?.lapsCompleted ?? 0, "Track is now fully wet.", "weather");
    } else if (rainChance < 55 && condition !== "dry") {
      setCondition("dry");
      pushEvent(cars[0]?.lapsCompleted ?? 0, "Track drying out, back to dry conditions.", "weather");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rainChance]);

  const standings = useMemo(() => computeStandings(cars, currentCircuit, finished), [cars, currentCircuit, finished]);

  const playerCars = cars.filter((c) => c.team.isPlayer);
  const activeCar = cars.find((c) => c.id === activeCarId) || playerCars[0];
  const activeCarStanding = standings.find((s) => s.id === activeCar?.id);
  const carAheadStanding = activeCarStanding
    ? standings.find((s) => s.position === activeCarStanding.position - 1)
    : null;

  const undercutMsg = useMemo(() => {
    if (!carAheadStanding || !activeCarStanding || activeCarStanding.position === 1 || activeCar?.status === "dnf") return null;
    if (carAheadStanding.status === "dnf") return null;
    const gap = activeCarStanding.gapSeconds - carAheadStanding.gapSeconds;
    if (gap < AVG_PIT_LOSS - 3) return { ok: true, text: `Undercut window open on ${carAheadStanding.name} — gap ${gap.toFixed(1)}s` };
    return { ok: false, text: `Track position favours holding — gap ${gap.toFixed(1)}s vs ~${AVG_PIT_LOSS}s average pit loss` };
  }, [carAheadStanding, activeCarStanding, activeCar]);

  const cliffWarning = useMemo(() => {
    if (!activeCar || activeCar.status === "dnf") return null;
    const c = COMPOUNDS[activeCar.compound];
    if (activeCar.tireAge >= c.cliffAge - 3 && activeCar.tireAge < c.cliffAge) {
      return `${c.label} tyres approaching the cliff in ${c.cliffAge - activeCar.tireAge} laps — degradation about to spike.`;
    }
    if (activeCar.tireAge >= c.cliffAge) {
      return `${c.label} tyres are past their cliff — losing serious pace every lap.`;
    }
    return null;
  }, [activeCar]);

  function setEngineMode(carId, mode) {
    setCars((prev) => prev.map((c) => (c.id === carId ? { ...c, engineMode: mode } : c)));
  }
  function queuePit(carId, compoundKey) {
    Sound.say("Box this lap", "engineer");
    setCars((prev) => prev.map((c) => (c.id === carId ? { ...c, pitQueued: true, pendingCompound: compoundKey } : c)));
    pushEvent(activeCar?.lapsCompleted ?? 0, `${cars.find((c) => c.id === carId)?.name} — pit stop queued for ${COMPOUNDS[compoundKey].label}.`, "pit");
  }
  function cancelPit(carId) {
    setCars((prev) => prev.map((c) => (c.id === carId ? { ...c, pitQueued: false, pendingCompound: null } : c)));
  }

  /* ============================== RENDER ============================== */

  if (!saveLoaded) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <div className="pw-loading">Loading your career…</div>
      </div>
    );
  }

  if (!season.teamTierId) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <TeamSelectScreen onChoose={chooseTeamTier} onOpenSaves={() => setSavesOpen(true)} saveCount={saves.length} />
        {savesPanel}
      </div>
    );
  }

  if (season.playerDrivers.length < 2) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <DriverSelectScreen season={season} onConfirm={confirmDriverSelection} />
      </div>
    );
  }

  if (!season.sponsorObjective) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <SponsorSelectScreen season={season} onChoose={chooseSponsor} />
      </div>
    );
  }

  if (season.needsTesting) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <WinterTestingScreen season={season} onContinue={completeTesting} />
      </div>
    );
  }

  if (season.board && season.board.fired) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <FiredScreen season={season} onNewCareer={startNewCareer} onOpenSaves={() => setSavesOpen(true)} />
        {savesPanel}
      </div>
    );
  }

  if (screen === "press" && press) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <PressScreen press={press} onAnswer={answerPress} onContinue={finishPress} />
      </div>
    );
  }

  if (screen === "stats") {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <StatsScreen season={season} onBack={() => setScreen("calendar")} />
      </div>
    );
  }

  if (screen === "offseason") {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <OffseasonScreen
          season={season}
          onRenew={renewDriver}
          onRelease={releaseDriver}
          onHire={hireDriver}
          onStartSeason={startNewSeason}
          onOpenSaves={() => setSavesOpen(true)}
        />
        {savesPanel}
      </div>
    );
  }

  if (screen === "calendar") {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <CalendarScreen season={season} onStartRace={goToFiaReport} onGoDev={() => setScreen("development")} onNewCareer={startNewCareer} onOpenSaves={() => setSavesOpen(true)} onGoStats={() => setScreen("stats")} />
        {savesPanel}
      </div>
    );
  }

  if (screen === "development") {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <DevelopmentScreen season={season} onInvest={investDev} onInvestStaff={investStaff} onBack={() => setScreen("calendar")} />
      </div>
    );
  }

  if (screen === "fiaReport") {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <FiaReportScreen
          season={season}
          round={currentRound?.round}
          totalRounds={season.calendar.length}
          circuitName={currentCircuit?.name}
          onContinue={goToPractice}
        />
      </div>
    );
  }

  if (screen === "practice" && practiceReport) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <PracticeScreen
          circuit={currentCircuit}
          round={currentRound?.round}
          totalRounds={season.calendar.length}
          report={practiceReport}
          onContinue={goToSetup}
        />
      </div>
    );
  }

  if (screen === "setup" && qualiRoster) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <SetupScreen
          circuit={currentCircuit}
          round={currentRound?.round}
          totalRounds={season.calendar.length}
          roster={qualiRoster}
          carSetups={carSetups}
          setCarSetups={setCarSetups}
          onContinue={goToQualifying}
        />
      </div>
    );
  }

  if (screen === "qualifying" && qualiRoster && qualiTimes) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <QualifyingScreen
          circuit={currentCircuit}
          round={currentRound?.round}
          totalRounds={season.calendar.length}
          roster={qualiRoster}
          qualiTimes={qualiTimes}
          onStartRace={goToTireChoice}
          onRerun={goToQualifying}
        />
      </div>
    );
  }

  if (screen === "tireChoice" && qualiRoster && qualiTimes) {
    return (
      <div className="pw-root">
        <style>{CSS}</style>
        <GlobalChrome />
        <TireChoiceScreen
          circuit={currentCircuit}
          round={currentRound?.round}
          totalRounds={season.calendar.length}
          roster={qualiRoster}
          qualiTimes={qualiTimes}
          startTireChoice={startTireChoice}
          setStartTireChoice={setStartTireChoice}
          startEngineMode={startEngineMode}
          setStartEngineMode={setStartEngineMode}
          practiceReport={practiceReport}
          onConfirm={startRaceFromQuali}
        />
      </div>
    );
  }

  const raceLap = currentCircuit ? Math.min(Math.max(...cars.map((c) => c.lapsCompleted)) + 1, currentCircuit.laps) : 1;

  return (
    <div className="pw-root pw-race">
      <style>{CSS}</style>
        <GlobalChrome />

      <TopBar
        circuitName={currentCircuit?.name}
        round={currentRound?.round}
        totalRounds={season.calendar.length}
        raceLap={raceLap}
        totalLaps={currentCircuit?.laps || 0}
        raceClock={raceClock}
        speed={speed}
        setSpeed={setSpeed}
        finished={finished}
        caution={cautionSectorsUI}
        onRestart={() => startRaceFromQuali()}
        onQuit={quitToHQ}
      />

      <div className="pw-grid">
        <section className="pw-panel pw-track">
          <h2>Live Track</h2>
          <TrackMap cars={standings} pathRef={pathRef} pathLen={pathLen} playerTeamId="mclaren" circuit={currentCircuit} raceId={raceId} cautionSectors={cautionSectorsUI} gridHold={gridHold} startLights={startLights} condition={condition} neutral={scMode} followId={activeCar?.id} />
          <WeatherStrip condition={condition} rainChance={rainChance} caution={cautionSectorsUI} />
        </section>

        <section className="pw-panel pw-timing">
          <h2>Timing</h2>
          <TimingTower standings={standings} activeCarId={activeCar?.id} onSelect={setActiveCarId} />
        </section>

        <section className="pw-panel pw-strategy">
          <h2>Strategy — {activeCar?.name}{activeCar && <Stars name={activeCar.name} />} <span className="pw-carno">#{activeCar?.number}</span></h2>
          <MemoStrategyChart car={activeCar} />
          {cliffWarning && <div className="pw-cliffwarn">{cliffWarning}</div>}
          {undercutMsg && <div className={`pw-undercut ${undercutMsg.ok ? "ok" : "hold"}`}>{undercutMsg.text}</div>}
        </section>

        <section className="pw-panel pw-pits">
          <h2>Pit Wall Controls</h2>
          <MemoPitControls
            playerCars={playerCars}
            activeCarId={activeCar?.id}
            setActiveCarId={setActiveCarId}
            onEngineMode={setEngineMode}
            onQueuePit={queuePit}
            onCancelPit={cancelPit}
          />
        </section>

        <section className="pw-panel pw-log">
          <h2>Race Feed</h2>
          <MemoEventLog events={events} />
        </section>
      </div>

      {finished && (
        <ResultsOverlay
          standings={standings}
          onReplay={() => startRaceFromQuali()}
          onContinue={continueToHQ}
          isLastRound={season.roundIndex >= season.calendar.length - 1}
        />
      )}

      {raceLoading && <CircuitLoadingOverlay circuitName={currentCircuit?.name} stage={geoStage} />}
    </div>
  );
}

function CircuitLoadingOverlay({ circuitName, stage = 0 }) {
  const n = GEO_STAGES.length;
  const pct = Math.min(100, Math.round((stage / n) * 100));
  return (
    <div className="pw-overlay">
      <div className="pw-loading-card">
        <div className="pw-loading-spinner" aria-hidden="true" />
        <div className="pw-loading-title">Preparing {circuitName}</div>
        <div className="pw-loading-sub">{GEO_STAGES[Math.min(stage, n - 1)]}…</div>
        <div className="pw-loading-bar"><div className="pw-loading-fill" style={{ width: pct + "%" }} /></div>
        <ul className="pw-loading-steps">
          {GEO_STAGES.map((t, i) => (
            <li key={t} className={i < stage ? "done" : i === stage ? "now" : ""}>{i < stage ? "✓" : i === stage ? "›" : "·"} {t}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}

