// Rubber laid down on the racing line. Opacity is driven by one CSS variable so
// the (static) segments are not re-rendered as the race progresses — corners
// and braking zones darken far more than the straights.
const RubberLayer = React.memo(function RubberLayer({ segs, level }) {
  if (!segs.length) return null;
  return (
    <g style={{ "--rub": level }} pointerEvents="none">
      {segs.map((sg, i) => (
        <polyline key={i} points={sg.pts} fill="none" stroke="#05070a" strokeWidth="8" strokeLinecap="butt" strokeLinejoin="round" style={{ opacity: `calc(var(--rub) * ${sg.w * 0.95})` }} />
      ))}
    </g>
  );
});

// Everything derived from a circuit's measured path (pit lane, scenery, racing
// line, sector overlays) in one place, cached per circuit+length. The race
// loading screen calls this up front so nothing heavy happens once lights are out.
const PASS_ZONES = [];
// Time-fraction -> distance-fraction of the current circuit (speed profile)
const TRACK_WARP = { w: null };
function distFracOf(tf) {
  const w = TRACK_WARP.w;
  const x = Math.min(Math.max(tf, 0), 0.999);
  if (!w) return x;
  const p = x * (w.length - 1), i = Math.floor(p);
  return w[i] + (w[i + 1] - w[i]) * (p - i);
}
const YELLOW_SLOW = 1.07; // a sector under yellow costs ~2s (drivers lift, no overtaking)
const inPassZone = (fr) => PASS_ZONES.some((z) => (z.t0 <= z.t1 ? fr >= z.t0 && fr <= z.t1 : fr >= z.t0 || fr <= z.t1));
const trackGeometryCache = new Map();
// Nothing from the scenery may sit on top of the pit complex.
function clearPitArea(decor, pit) {
  if (!pit || !pit.clear) return decor;
  const near = (x, y, r) => pit.clear.some((p) => Math.hypot(p.x - x, p.y - y) < r);
  decor.trees = decor.trees.filter((t) => !near(t.x, t.y, 26 + t.r));
  decor.buildings = decor.buildings.filter((b) => !near(b.x, b.y, 28 + Math.max(b.w || 0, b.h || 0) * 0.5));
  decor.grandstands = decor.grandstands.filter((g) => !near(g.x, g.y, 42));
  decor.boards = decor.boards.filter((b) => !near(b.x, b.y, 24));
  decor.gravel = decor.gravel.filter((g) => !near(g.x, g.y, 26 + Math.max(g.rx, g.ry)));
  decor.marshals = (decor.marshals || []).filter((m) => !near(m.x, m.y, 22));
  decor.ledPanels = (decor.ledPanels || []).filter((m) => !near(m.x, m.y, 20));
  decor.brakeBoards = (decor.brakeBoards || []).filter((m) => !near(m.x, m.y, 22));
  decor.tyreWalls = decor.tyreWalls.filter((w) => !near((w.x1 + w.x2) / 2, (w.y1 + w.y2) / 2, 26));
  return decor;
}
const GEO_STAGES = ["Measuring the circuit", "Building the pit lane", "Computing the racing line & speed profile", "Placing scenery, kerbs & sectors"];
async function prepareTrackGeometry(circuit, pathEl, pathLen, onStage) {
  const key = `${circuit.id}-${Math.round(pathLen)}`;
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  if (trackGeometryCache.has(key)) { getTrackGeometry(circuit, pathEl, pathLen); onStage(GEO_STAGES.length); return; }
  onStage(0); await wait(260);
  const pit = buildPitLane(pathEl, pathLen, TEAMS.length);
  onStage(1); await wait(260);
  const decor = clearPitArea(sampleTrackDecor(pathEl, pathLen, circuit.id, circuit.scene, { lengthKm: circuitLengthKm(circuit), downforce: circuit.downforce, baseLap: circuit.baseLap }), pit);
  onStage(2); await wait(260);
  const sector = {
    polylines: [0, 1, 2].map((i) => getSectorPolyline(pathEl, pathLen, i)),
    ticks: getSectorBoundaryTicks(pathEl, pathLen),
  };
  trackGeometryCache.set(key, { pit, decor, sector });
  getTrackGeometry(circuit, pathEl, pathLen);
  onStage(3); await wait(200);
  onStage(GEO_STAGES.length);
}
function getTrackGeometry(circuit, pathEl, pathLen) {
  const key = `${circuit.id}-${Math.round(pathLen)}`;
  if (!pathEl || !pathLen) {
    return { pit: null, decor: sampleTrackDecor(null, 0, circuit.id, circuit.scene), sector: { polylines: ["", "", ""], ticks: [] } };
  }
  let g = trackGeometryCache.get(key);
  if (!g) {
    const pit0 = buildPitLane(pathEl, pathLen, TEAMS.length);
    g = {
      pit: pit0,
      decor: clearPitArea(sampleTrackDecor(pathEl, pathLen, circuit.id, circuit.scene, { lengthKm: circuitLengthKm(circuit), downforce: circuit.downforce, baseLap: circuit.baseLap }), pit0),
      sector: {
        polylines: [0, 1, 2].map((i) => getSectorPolyline(pathEl, pathLen, i)),
        ticks: getSectorBoundaryTicks(pathEl, pathLen),
      },
    };
    trackGeometryCache.set(key, g);
  }
  if (g.decor.profile) {
    PASS_ZONES.length = 0;
    (g.decor.profile.zones || []).forEach((z) => PASS_ZONES.push(z));
    TRACK_WARP.w = g.decor.warp || null;
    PIT_TIME.entry = g.decor.profile.entryU;
    PIT_TIME.exit = g.decor.profile.exitU;
  }
  return g;
}


function TrackMap({ cars, pathRef, pathLen, playerTeamId, circuit, raceId, cautionSectors = [], gridHold = false, startLights = 0, condition = "dry", neutral = null, followId = null }) {
  // Precomputed (and cached) while the loading screen is up.
  const carAngleRef = useRef({});
  const latRef = useRef({});
  const geo = getTrackGeometry(circuit, pathRef.current, pathLen);
  const pitInfo = geo.pit;
  const [zoom, setZoom] = useState(1);
  // Sector clears -> its LED panels flash green for a few seconds
  const [greenUntil, setGreenUntil] = useState([0, 0, 0]);
  const prevFlagRef = useRef({ y: [], n: null });
  const flagKey = cautionSectors.join(",") + "|" + (neutral || "");
  useEffect(() => {
    const prev = prevFlagRef.current;
    const now = Date.now();
    const next = [...greenUntil];
    let changed = false;
    [1, 2, 3].forEach((s) => {
      if (prev.y.includes(s) && !cautionSectors.includes(s)) { next[s - 1] = now + 3500; changed = true; }
    });
    if (prev.n && !neutral) { next[0] = next[1] = next[2] = now + 3500; changed = true; }
    prevFlagRef.current = { y: [...cautionSectors], n: neutral };
    if (changed) {
      setGreenUntil(next);
      const t = setTimeout(() => setGreenUntil((g) => [...g]), 3600);
      return () => clearTimeout(t);
    }
  }, [flagKey]);
  const decor = geo.decor;
  const sectorInfo = geo.sector;
  // Sorted by a stable key (car id), not by live race position, so a car's
  // slot inside the pit box never jumps sideways just because someone else's
  // standings position shifted while both are stopped.
  const carsInPit = cars.filter((c) => c.inPit).sort((a, b) => a.id - b.id);

  // Rubber builds with race distance (quantised so it only re-renders in steps)
  const maxLaps = cars.reduce((m, c) => Math.max(m, c.lapsCompleted || 0), 0);
  const rubberLevel = Math.min(1, Math.round((maxLaps / Math.max(circuit.laps, 1)) * 40) / 40);

  // Overtaking: a faster car close behind (or just alongside) another car
  // pulls out to the side of the racing line, passes, then tucks back in.
  const lineAt = (f) => {
    const ln = decor.line;
    if (!ln) return null;
    const x = (((f % 1) + 1) % 1) * ln.count;
    const i0 = Math.floor(x) % ln.count;
    const i1 = (i0 + 1) % ln.count;
    const u = x - Math.floor(x);
    const m = (arr) => arr[i0] * (1 - u) + arr[i1] * u;
    return { x: m(ln.x), y: m(ln.y), nx: m(ln.nx), ny: m(ln.ny), tx: m(ln.tx), ty: m(ln.ty), off: m(ln.offsets) };
  };
  const progOf = (c) => (c.lapsCompleted || 0) + Math.min(Math.max(c.timeInLap / Math.max(c.currentLapTarget, 1), 0), 0.999);
  const racing = cars.filter((c) => c.status !== "dnf" && !c.inPit);
  const attacking = {};
  racing.forEach((me) => {
    const pm = progOf(me);
    for (const o of racing) {
      if (o.id === me.id) continue;
      const gapSec = (progOf(o) - pm) * me.currentLapTarget;
      if (gapSec > -0.3 && gapSec < 0.8 && me.currentLapTarget < o.currentLapTarget) {
        attacking[me.id] = true;
        break;
      }
    }
  });

  // Visual spacing: cars queue nose-to-tail instead of drawing on top of each
  // other (a car alongside for a pass is allowed to overlap in length).
  const fOvAll = {};
  const gridDecay = {};
  if (decor.warp && pathLen > 0) {
    const w = decor.warp;
    const wa = (x) => { const p = x * 1024, i = Math.min(1023, Math.floor(p)); return w[i] + (w[i + 1] - w[i]) * (p - i); };
    const run = cars
      .filter((c) => c.status !== "dnf" && !c.inPit)
      .map((c) => {
        let f = wa(Math.min(Math.max(c.timeInLap / Math.max(c.currentLapTarget, 1), 0), 0.999));
        // Standing start: each car leaves from its own grid slot, two by two,
        // and the stagger melts away over the first part of lap one.
        const gd = !c.lapsCompleted && c.gridPosition ? Math.max(0, 1 - f / 0.07) : 0;
        if (gd > 0) f -= ((10 + (c.gridPosition - 1) * 9) / pathLen) * gd;
        // a slow or sharp reaction shows off the line, then washes out
        if (gd > 0 && gd < 1) f -= (Math.max(-0.6, Math.min(2.5, c.startDelta || 0)) * 9 / pathLen) * Math.min(1, gd * (1 - gd) * 6);
        gridDecay[c.id] = gd;
        return { id: c.id, f, att: !!attacking[c.id] };
      })
      .sort((a, b) => b.f - a.f);
    const mg = 13 / pathLen;
    for (let i = 1; i < run.length; i++) {
      const need = run[i].att ? mg * 0.3 : mg;
      if (gridDecay[run[i].id] > 0.5) continue; // still in grid formation
      if (run[i - 1].f - run[i].f < need) run[i].f = run[i - 1].f - need;
    }
    run.forEach((r) => { fOvAll[r.id] = ((r.f % 1) + 1) % 1; });
  }
  const lineXY = (f) => { const L = lineAt(f); return L ? { x: L.x + L.nx * L.off, y: L.y + L.ny * L.off, a: (Math.atan2(L.ty, L.tx) * 180) / Math.PI } : null; };
  // Safety car: a few car lengths ahead of the race leader
  let scCar = null;
  if (neutral === "SC" && pathLen > 0) {
    const lead = cars.filter((c) => c.status !== "dnf" && !c.inPit).sort((a, b) => a.position - b.position)[0];
    if (lead && fOvAll[lead.id] != null) scCar = lineXY(fOvAll[lead.id] + 26 / pathLen);
  }
  // Follow camera
  let camStyle, camDyn;
  if (zoom > 1 && pathLen > 0) {
    const fc = cars.find((c) => c.id === followId && c.status !== "dnf") || cars.find((c) => c.position === 1);
    let p = null;
    if (fc && fc.inPit && pitInfo) { const pr = pitProfile(fc); p = pitInfo.laneAt(pr ? pr.u : 0); }
    else if (fc && fOvAll[fc.id] != null) p = lineXY(fOvAll[fc.id]);
    if (p) {
      const tx = Math.min(0, Math.max(1000 - zoom * 1000, 500 - zoom * p.x));
      const ty = Math.min(0, Math.max(600 - zoom * 600, 300 - zoom * p.y));
      // Zoom by enlarging the layers (crisp vector re-raster once), pan with a
      // pure translate so the compositor moves cached layers every frame.
      camStyle = { width: `${zoom * 100}%`, height: `${zoom * 100}%`, transform: `translate(${(tx / (10 * zoom)).toFixed(3)}%, ${(ty / (6 * zoom)).toFixed(3)}%)` };
      // the moving layer stays at screen size and pans inside its own viewBox
      camDyn = { transform: `translate(${tx.toFixed(2)}px, ${ty.toFixed(2)}px) scale(${zoom})` };
    }
  }
  return (
    <div className="pw-trackwrap">
      <button className={`pw-cambtn${zoom > 1 ? " on" : ""}`} onClick={() => setZoom(zoom > 1 ? 1 : (typeof window !== "undefined" && window.matchMedia && window.matchMedia("(max-width: 640px)").matches ? 1.8 : 2.4))} title="Follow the selected car">{zoom > 1 ? "⤢ Full track" : "⌖ Follow car"}</button>
      <div className="pw-trackstage">
      <svg viewBox="0 0 1000 600" className="pw-tracksvg pw-layer" style={camStyle} aria-label="Live circuit map">
        <TrackScenery pathRef={pathRef} d={circuit.path} decor={decor} uid={circuit.id} />
        <RubberLayer segs={decor.rubberSegs} level={rubberLevel} />
        {condition !== "dry" && (
          <g pointerEvents="none">
            {/* Standing water darkens the asphalt; in damp conditions the racing line dries first */}
            <path d={circuit.path} fill="none" stroke="#071426" strokeOpacity={condition === "wet" ? 0.5 : 0.26} strokeWidth="26" strokeLinecap="round" strokeLinejoin="round" />
            <path d={circuit.path} fill="none" stroke="#9fc4ff" strokeOpacity={condition === "wet" ? 0.1 : 0.05} strokeWidth="18" strokeLinecap="round" strokeLinejoin="round" />
            {condition === "damp" && decor.rubberSegs.map((sg, i) => (
              <polyline key={`dry-${i}`} points={sg.pts} fill="none" stroke="#5a6372" strokeOpacity="0.55" strokeWidth="7" strokeLinecap="butt" strokeLinejoin="round" />
            ))}
          </g>
        )}
        {(decor.drsZones || []).map((z, i) => (
          <g key={`drs-${i}`} pointerEvents="none">
            <polyline points={z.a} fill="none" stroke="#00d68f" strokeOpacity="0.8" strokeWidth="1.4" strokeDasharray="6 4" />
            <polyline points={z.b} fill="none" stroke="#00d68f" strokeOpacity="0.8" strokeWidth="1.4" strokeDasharray="6 4" />
            <g transform={`translate(${z.sign.x},${z.sign.y})`}>
              <rect x="-8" y="-4" width="16" height="8" rx="1.5" fill="#00d68f" stroke="#0a0a10" strokeWidth="0.8" />
              <text y="2.4" textAnchor="middle" fontSize="5.6" fontWeight="800" fill="#0a0a10" style={{ fontFamily: "inherit" }}>DRS</text>
            </g>
          </g>
        ))}

        {sectorInfo.ticks.map((tk, i) => (
          <line key={`tick-${i}`} x1={tk.x1} y1={tk.y1} x2={tk.x2} y2={tk.y2} stroke="#6B7684" strokeWidth="2" strokeOpacity="0.5" />
        ))}

        {pitInfo && (
          <>
            {/* Soft shadow + concrete apron under the whole complex */}
            <polygon points={pitInfo.apronPoly} fill="#000" fillOpacity="0.35" transform="translate(2,3)" />
            <polygon points={pitInfo.apronPoly} fill="#3b4251" stroke="#1b212c" strokeWidth="1.4" strokeLinejoin="round" />
            <polygon points={pitInfo.apronPoly} fill="none" stroke="#fff" strokeOpacity="0.07" strokeWidth="3" strokeLinejoin="round" />
            {/* Fast lane: same asphalt as the circuit so entry and exit merge seamlessly */}
            <polyline points={pitInfo.lanePoints} fill="none" stroke={`url(#asph-${circuit.id})`} strokeWidth="13" strokeLinecap="butt" strokeLinejoin="round" />
            <polyline points={pitInfo.lanePoints} fill="none" stroke="#fff" strokeOpacity="0.05" strokeWidth="9" strokeLinecap="butt" strokeLinejoin="round" />
            <polyline points={pitInfo.edgeOut} fill="none" stroke="#e8ecf1" strokeOpacity="0.85" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" />
            <polyline points={pitInfo.edgeIn} fill="none" stroke="#e8ecf1" strokeOpacity="0.85" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" />
            {pitInfo.chevrons.map((c, i) => (
              <path key={`chev-${i}`} transform={`translate(${c.x},${c.y}) rotate(${c.angle})`} d="M-2.4,-3 L1.4,0 L-2.4,3" fill="none" stroke="#fff" strokeOpacity="0.55" strokeWidth="1.1" strokeLinecap="round" strokeLinejoin="round" />
            ))}
            {/* Working lane in front of the garages */}
            <polyline points={pitInfo.workPoints} fill="none" stroke="#2a303c" strokeWidth="7" strokeLinecap="butt" strokeLinejoin="round" />
            <polyline points={pitInfo.workPoints} fill="none" stroke="#f2b33d" strokeOpacity="0.7" strokeWidth="0.9" strokeDasharray="5 4" />
            <polyline points={pitInfo.lanePoints} fill="none" stroke="#f2b33d" strokeOpacity="0.5" strokeWidth="0.9" strokeDasharray="7 7" />
            {/* Pit wall with team gantries */}
            <polyline points={pitInfo.wallPoints} fill="none" stroke="#10141c" strokeWidth="3.6" strokeLinecap="round" strokeLinejoin="round" />
            <polyline points={pitInfo.wallPoints} fill="none" stroke="#b4bfce" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
            <polyline points={pitInfo.wallPoints} fill="none" stroke="#e10600" strokeWidth="1.6" strokeDasharray="2 10" />
            {pitInfo.gantries.map((g) => (
              <g key={`gan-${g.k}`} transform={`translate(${g.x},${g.y}) rotate(${g.angle})`}>
                <rect x="-3.2" y="-2.4" width="6.4" height="4.8" rx="0.8" fill="#10141c" stroke={TEAMS[g.k].color} strokeWidth="0.9" />
                <rect x="-2.2" y="-1.4" width="4.4" height="1" fill={TEAMS[g.k].color} fillOpacity={TEAMS[g.k].isPlayer ? 1 : 0.7} />
              </g>
            ))}

            {/* Team service boxes painted on the lane */}
            {pitInfo.bays.map((b) => (
              <g key={`bay-${b.k}`} transform={`translate(${b.x},${b.y}) rotate(${b.angle})`}>
                <rect x="-9" y="-5" width="18" height="10" rx="1.2" fill={TEAMS[b.k].color} fillOpacity={TEAMS[b.k].isPlayer ? 0.16 : 0.07} stroke={TEAMS[b.k].color} strokeOpacity={TEAMS[b.k].isPlayer ? 1 : 0.55} strokeWidth="0.9" strokeDasharray="3 2" />
              </g>
            ))}

            {/* Garage complex: shaded block, lit roof, one door per team */}
            <polygon points={pitInfo.garagePoly} fill="#000" fillOpacity="0.4" transform="translate(2,3)" />
            <polygon points={pitInfo.garagePoly} fill="#0E1219" stroke="#2b3446" strokeWidth="1.2" strokeLinejoin="round" />
            <polygon points={pitInfo.roofPoly} fill="#1a212d" stroke="#3a4557" strokeWidth="0.8" strokeLinejoin="round" />
            <polygon points={pitInfo.roofPoly} fill="url(#roof-sheen)" strokeLinejoin="round" />
            {pitInfo.doors.map((d) => {
              const team = TEAMS[d.k];
              return (
                <g key={team.id} transform={`translate(${d.x},${d.y}) rotate(${d.angle})`}>
                  <rect x="-6.4" y="-5.4" width="12.8" height="2" rx="0.6" fill="#0a0a10" fillOpacity="0.8" />
                  <rect x="-6" y="-3.2" width="12" height="6.4" rx="1" fill={team.color} fillOpacity={team.isPlayer ? 1 : 0.75} stroke={team.isPlayer ? "#e8ecf1" : "#0E1219"} strokeWidth={team.isPlayer ? 0.9 : 0.6} />
                  <rect x="-6" y="-3.2" width="12" height="1.6" fill="#fff" fillOpacity="0.28" />
                </g>
              );
            })}

            {/* Pit-lane entry / exit signs and lights */}
            {[["IN", pitInfo.entrySign], ["OUT", pitInfo.exitSign]].map(([label, sg]) => (
              <g key={label} transform={`translate(${sg.x},${sg.y})`}>
                <circle r="7" fill="#000" fillOpacity="0.35" cx="1" cy="1.5" />
                <circle r="6.4" fill="#f5f7fa" stroke="#d6261b" strokeWidth="1.8" />
                <text y="2" textAnchor="middle" className="pw-pit-sign">{label === "IN" ? "80" : "OUT"}</text>
              </g>
            ))}
            <text x={pitInfo.labelPos.x} y={pitInfo.labelPos.y} textAnchor="middle" className="pw-pitlane-label">PIT LANE</text>
          </>
        )}
      </svg>
      <svg viewBox="0 0 1000 600" className="pw-layer pw-layer-dyn" aria-hidden="true">
        <g className="pw-cam" style={camDyn}>
        {/* Marshalling LED panels: dark when green, flashing yellow in a flagged
            sector, SC / VSC boards everywhere, a short green flash when cleared */}
        {(decor.ledPanels || []).map((lp, i) => {
          const yellow = cautionSectors.includes(lp.sector + 1);
          const green = !yellow && !neutral && greenUntil[lp.sector] > Date.now();
          const state = neutral ? "sc" : yellow ? "yellow" : green ? "green" : "off";
          return (
            <g key={`led-${i}`} transform={`translate(${lp.x.toFixed(1)},${lp.y.toFixed(1)}) rotate(${lp.rot.toFixed(1)}) scale(1.15)`} pointerEvents="none">
              {state !== "off" && <rect x="-11" y="-7.5" width="22" height="15" rx="6" className={`pw-ledglow pw-led-${state}`} />}
              <rect x="-6.6" y="-3.6" width="13.2" height="7.2" rx="1" fill="#000" fillOpacity="0.4" transform="translate(0.8,1.2)" />
              <rect x="-6.6" y="-3.6" width="13.2" height="7.2" rx="1" fill="#0b0e14" stroke="#3a4557" strokeWidth="0.6" />
              <rect x="-5.4" y="-2.5" width="10.8" height="5" rx="0.5" className={`pw-led pw-led-${state}`} />
              {state === "off" && <rect x="-5.4" y="-2.5" width="10.8" height="5" rx="0.5" fill={`url(#led-dots-${circuit.id})`} />}
              {state === "sc" && (
                <text y="1.75" textAnchor="middle" fontSize={neutral === "VSC" ? 3.4 : 4.6} fontWeight="900" fill="#0a0a10" style={{ fontFamily: "inherit" }}>{neutral === "VSC" ? "VSC" : "SC"}</text>
              )}
            </g>
          );
        })}


        {pathLen > 0 &&
          pathRef.current &&
          cars.map((car) => {
            const fOv = fOvAll;
            let pt;
            let angle = 0;
            let stopped = false;
            let stopElapsed = 0;
            let trackN = null;
            const pathAt = (frac) => pathRef.current.getPointAtLength(((frac % 1) + 1) % 1 * pathLen);
            const warp = decor.warp;
            const warpAt = (x) => {
              if (!warp) return x;
              const p = x * 1024;
              const i = Math.min(1023, Math.floor(p));
              return warp[i] + (warp[i + 1] - warp[i]) * (p - i);
            };
            const onTrack = (frac, fo) => {
              const f = fo ?? warpAt(Math.min(Math.max(frac, 0), 0.999));
              const L = lineAt(f);
              if (L) {
                trackN = { nx: L.nx, ny: L.ny, f, off: L.off };
                return { p: { x: L.x, y: L.y }, a: (Math.atan2(L.ty, L.tx) * 180) / Math.PI };
              }
              const p = pathAt(f);
              const q = pathAt(f + 0.012);
              const dl = Math.hypot(q.x - p.x, q.y - p.y) || 1;
              trackN = { nx: -(q.y - p.y) / dl, ny: (q.x - p.x) / dl, f, off: 0 };
              return { p, a: (Math.atan2(q.y - p.y, q.x - p.x) * 180) / Math.PI };
            };
            const headTo = (a, b) => (Math.atan2(b.y - a.y, b.x - a.x) * 180) / Math.PI;
            if (car.status === "dnf") {
              const r = onTrack(car.timeInLap / Math.max(car.currentLapTarget, 1));
              pt = r.p;
              angle = r.a + 35;
            } else if (car.inPit && car.pit && pitInfo) {
              // The car peeled off at the pit entrance, crosses the line inside
              // the lane, stops at its own garage, then rejoins the track.
              const prof = pitProfile(car);
              const l = pitInfo.laneAt(prof.u);
              pt = l;
              angle = l.angle;
              if (prof.stopped) {
                stopped = true;
                stopElapsed = prof.stopElapsed;
              }
            } else {
              const r = onTrack(car.timeInLap / Math.max(car.currentLapTarget, 1), fOv[car.id]);
              pt = r.p;
              angle = r.a;
            }
            // Lateral position: racing line + a pull-out when attacking
            if (trackN) {
              const st = latRef.current[car.id] || (latRef.current[car.id] = { lat: 0, side: car.id % 2 ? 1 : -1, was: false });
              // st.lat is now only the pull-out relative to the racing line
              const lineOff = trackN.off;
              // every driver has a slightly personal line
              let target = Math.sin(car.id * 1.7 + trackN.f * 18) * 1.3;
              if (car.status === "dnf") {
                target = st.side * 10 - lineOff;
              } else if (attacking[car.id]) {
                if (!st.was) st.side = Math.abs(lineOff) > 1.5 ? -Math.sign(lineOff) : st.side;
                target = st.side * 9;
              }
              st.was = !!attacking[car.id];
              const gd = gridDecay[car.id] || 0;
              if (gd > 0 && car.gridPosition) target = target * (1 - gd) + (((car.gridPosition - 1) % 2 === 0 ? -1 : 1) * 6 - lineOff) * gd;
              target = Math.max(-11, Math.min(11, lineOff + target)) - lineOff;
              const prevLat = st.lat;
              st.lat += (target - st.lat) * (gridHold ? 1 : 0.5);
              pt = { x: pt.x + trackN.nx * st.lat, y: pt.y + trackN.ny * st.lat };
              angle += Math.max(-30, Math.min(30, (st.lat - prevLat) * 6));
            }
            // Keep the rotation continuous (no 360° spin when the heading wraps)
            const prevA = carAngleRef.current[car.id];
            if (prevA != null) {
              while (angle - prevA > 180) angle -= 360;
              while (angle - prevA < -180) angle += 360;
            }
            carAngleRef.current[car.id] = angle;

            const isPlayer = car.teamId === playerTeamId;
            const tyre = COMPOUNDS[car.compound]?.color || "#E8ECF1";
            const dnf = car.status === "dnf";
            // Braking lights: the speed profile ahead of the car drops noticeably
            let braking = false;
            if (trackN && decor.profile && !car.inPit && !dnf) {
              const sp = decor.profile.speed, n = sp.length;
              const bi = Math.floor(trackN.f * n) % n;
              braking = sp[(bi + Math.round(n * 0.012)) % n] < sp[bi] - 2.5;
            }
            return (
              <React.Fragment key={`${raceId}-${car.id}`}>
              <g
                className="pw-cardot"
                transform={`translate(${pt.x},${pt.y})`}
                opacity={dnf ? 0.4 : 1}
              >
                {isPlayer && !dnf && (
                  <g>
                    <circle r="19" fill={car.team.color} fillOpacity="0.1" />
                    <circle r="14" fill={car.team.color} fillOpacity="0.14" />
                    <circle r="13" fill="none" stroke={car.team.color} strokeWidth="1.5" opacity="0.7" />
                  </g>
                )}
                {stopped && (
                  <g>
                    <circle r="12" fill="none" stroke={tyre} strokeWidth="1.5" strokeDasharray="4 4" className="pw-pit-ring" />
                    {[[-9, -7], [9, -7], [-9, 7], [9, 7], [-11, 0], [11, 0]].map(([cx, cy], k) => (
                      <circle key={k} cx={cx} cy={cy} r="2" fill={k % 2 ? "#e8ecf1" : car.team.color} stroke="#0B0E14" strokeWidth="0.6" />
                    ))}
                  </g>
                )}
                <ellipse cx="2.5" cy="3.5" rx="11" ry="4.6" fill="#000" fillOpacity="0.38" style={{ transform: `rotate(${angle}deg)` }} />
                <g className="pw-carrot" style={{ transform: `rotate(${angle}deg) scale(1.35)` }}>
                  {/* Top-down single-seater, nose towards +x: tyres with compound
                      stripe, suspension, floor/sidepods, engine cover, halo, wings */}
                  <g stroke="#0B0E14" strokeWidth="0.35">
                    <line x1="-5.6" y1="-1.8" x2="-5.6" y2="-3.4" /><line x1="-5.6" y1="1.8" x2="-5.6" y2="3.4" />
                    <line x1="2.6" y1="-0.9" x2="5" y2="-3.1" /><line x1="2.6" y1="0.9" x2="5" y2="3.1" />
                    <line x1="4" y1="-0.7" x2="5.6" y2="-3.1" /><line x1="4" y1="0.7" x2="5.6" y2="3.1" />
                  </g>
                  {[[-7.4, -5.9, 3.4, 2.7], [-7.4, 3.2, 3.4, 2.7], [4, -5.2, 2.9, 2.2], [4, 3, 2.9, 2.2]].map(([x, y, w, h], k) => (
                    <g key={k}>
                      <rect x={x} y={y} width={w} height={h} rx="0.7" fill="#15171c" />
                      <rect x={x + 0.3} y={y < 0 ? y + 0.1 : y + h - 0.6} width={w - 0.6} height="0.5" fill={tyre} fillOpacity="0.9" />
                    </g>
                  ))}
                  <path d="M -6.9 -2.3 L -4.6 -3 L 0.6 -3 L 2.4 -1.5 L 7.2 -0.6 Q 7.9 0 7.2 0.6 L 2.4 1.5 L 0.6 3 L -4.6 3 L -6.9 2.3 Z" fill={car.team.color} stroke="#0B0E14" strokeWidth="0.55" strokeLinejoin="round" />
                  <path d="M -6.6 -0.9 L -1.5 -1.25 L 1.5 -0.7 L 1.5 0.7 L -1.5 1.25 L -6.6 0.9 Z" fill="#000" fillOpacity="0.22" />
                  <path d="M -4.4 -2.7 L 0.4 -2.7" stroke="#fff" strokeOpacity="0.32" strokeWidth="0.45" />
                  <ellipse cx="-0.9" cy="0" rx="1.7" ry="0.95" fill="#0B0E14" />
                  <circle cx="-1.2" cy="0" r="0.75" fill={isPlayer ? "#ffd23a" : "#f5f7fa"} />
                  <path d="M -2.4 -1 Q 0.8 -1.3 0.9 0 Q 0.8 1.3 -2.4 1" fill="none" stroke="#0B0E14" strokeWidth="0.45" />
                  <rect x="6.9" y="-4" width="1.3" height="8" rx="0.4" fill={car.team.color} stroke="#0B0E14" strokeWidth="0.4" />
                  <rect x="7.6" y="-4" width="0.35" height="8" fill="#0B0E14" fillOpacity="0.6" />
                  <rect x="-8.6" y="-3.5" width="1.7" height="7" rx="0.3" fill="#0B0E14" />
                  <rect x="-8.4" y="-3.2" width="1.3" height="6.4" fill={car.team.color} fillOpacity="0.85" />
                  <rect x="-8.3" y="-0.9" width="0.9" height="1.8" fill={braking ? "#ff2a1f" : "#8a1a14"} />
                  {braking && <rect x="-11" y="-2.6" width="3.4" height="5.2" rx="1.7" fill="#ff2a1f" fillOpacity="0.5" />}
                </g>
                {dnf && <text y="-14" textAnchor="middle" className="pw-track-dnf">OUT</text>}
                {!dnf && car.inPit && (
                  <text y="-15" textAnchor="middle" className="pw-track-pit">
                    {stopped ? `${stopElapsed.toFixed(1)}s` : "PIT"}
                  </text>
                )}
                {!dnf && !car.inPit && car.position <= 3 && (
                  <g transform="translate(0,-17)">
                    <rect x="-11" y="-6.5" width="22" height="13" rx="2" fill="#0a0a10" stroke={car.team.color} strokeWidth="1.6" />
                    <rect x="-11" y="-6.5" width="4" height="13" fill={car.team.color} />
                    <text x="2" y="3.4" textAnchor="middle" className="pw-track-pos" style={{ fontSize: 9.5, strokeWidth: 0 }}>P{car.position}</text>
                  </g>
                )}
              </g>
              </React.Fragment>
            );
          })}
        {scCar && (
          <g className="pw-cardot" style={{ transform: `translate(${scCar.x.toFixed(1)}px, ${scCar.y.toFixed(1)}px)` }} pointerEvents="none">
          <g style={{ transform: `rotate(${scCar.a.toFixed(1)}deg) scale(1.35)` }}>
            <ellipse cx="0.5" cy="1.4" rx="9" ry="4" fill="#000" fillOpacity="0.4" />
            <rect x="-8" y="-3.4" width="16" height="6.8" rx="2.4" fill="#d9dee6" stroke="#0b0e14" strokeWidth="0.7" />
            <rect x="-2.5" y="-2.6" width="5" height="5.2" rx="1" fill="#1b212c" />
            <rect x="-1.2" y="-3.4" width="1.6" height="6.8" className="pw-sc-bar" fill="#ffb000" />
          </g>
          </g>
        )}
        </g>
      </svg>
      <svg viewBox="0 0 1000 600" className="pw-layer pw-layer-ui" aria-hidden="true">
        {condition !== "dry" && (
          <g pointerEvents="none">
            <defs>
              <pattern id="pw-rain-p" width="26" height="48" patternUnits="userSpaceOnUse" patternTransform="rotate(14)">
                <line x1="6" y1="0" x2="6" y2="13" stroke="#cfe3ff" strokeOpacity="0.4" strokeWidth="0.9" />
                <line x1="19" y1="24" x2="19" y2="35" stroke="#cfe3ff" strokeOpacity="0.28" strokeWidth="0.8" />
              </pattern>
            </defs>
            <rect x="0" y="0" width="1000" height="600" fill="#0a1424" fillOpacity={condition === "wet" ? 0.22 : 0.1} />
            <g className="pw-rain" opacity={condition === "wet" ? 1 : 0.4}>
              <rect x="-100" y="-100" width="1200" height="800" fill="url(#pw-rain-p)" />
            </g>
          </g>
        )}
        {neutral && (
          <g transform="translate(500,22)" pointerEvents="none" className="pw-sc-banner">
            <rect x="-112" y="-14" width="224" height="28" rx="4" fill="#ffc400" stroke="#0a0a10" strokeWidth="1.5" />
            <text y="5.5" textAnchor="middle" fontSize="15" fontWeight="900" fill="#0a0a10" style={{ fontFamily: "inherit", letterSpacing: "0.12em" }}>{neutral === "SC" ? "SAFETY CAR" : "VIRTUAL SAFETY CAR"}</text>
          </g>
        )}
        {gridHold && (
          <g transform="translate(500,34)" pointerEvents="none">
            <rect x="-62" y="-17" width="124" height="34" rx="6" fill="#0a0a10" stroke="#2a2a38" strokeWidth="1.5" />
            {[0, 1, 2, 3, 4].map((k) => (
              <circle key={k} cx={-44 + k * 22} cy="0" r="8" fill={k < startLights ? "#ff1e12" : "#2a1513"} stroke="#000" strokeWidth="1.2" />
            ))}
          </g>
        )}
      </svg>
      </div>
    </div>
  );
}

function WeatherStrip({ condition, rainChance, caution }) {
  const labelMap = { dry: "Dry", damp: "Damp", wet: "Wet" };
  return (
    <div className="pw-weather">
      <span className={`pw-weather-pill ${condition}`}>{labelMap[condition]}</span>
      <div className="pw-rainbar"><div className="pw-rainbar-fill" style={{ width: `${rainChance}%` }} /></div>
      <span className="pw-rainlabel">Rain risk {Math.round(rainChance)}%</span>
      {caution.length > 0 && <span className="pw-weather-pill caution">⚠ Sector {caution.join(", ")}</span>}
    </div>
  );
}

const TYRE_LETTER = { SOFT: "S", MEDIUM: "M", HARD: "H", INTER: "I", WET: "W" };
function driverCode(name) {
  const parts = String(name || "").trim().split(/\s+/);
  const surname = (parts.length > 1 ? parts.slice(1).join("") : parts[0]) || "";
  return surname.replace(/[^A-Za-z]/g, "").slice(0, 3).toUpperCase() || "???";
}

function TimingTower({ standings, activeCarId, onSelect }) {
  const [gapRef, setGapRef] = useState("leader");
  const ref = gapRef === "car" ? standings.find((c) => c.id === activeCarId) : null;
  // Fastest lap of the race and each driver's personal best, for lap colours
  const bests = {};
  let fastest = Infinity, fastestId = null;
  // Overall best sector times (completed laps and the lap in progress)
  const bestS = [Infinity, Infinity, Infinity];
  standings.forEach((c) => {
    [0, 1, 2].forEach((k) => {
      const b = c.bestSectors ? c.bestSectors[k] : Infinity;
      const cu = c.curSectors && c.curSectors[k] != null && c.lapsCompleted > 0 ? c.curSectors[k] : Infinity;
      bestS[k] = Math.min(bestS[k], b, cu);
    });
  });
  const secColor = (c, k) => {
    const v = c.curSectors ? c.curSectors[k] : null;
    if (v == null) return "#2a2a38";
    if (c.lapsCompleted === 0) return "#e8c547";
    if (v <= bestS[k] + 1e-6) return "#c77dff";
    const pb = c.bestSectors ? c.bestSectors[k] : Infinity;
    return v <= pb + 1e-6 ? "#00d68f" : "#e8c547";
  };
  standings.forEach((c) => {
    const b = (c.lapHistory || []).reduce((m, l) => Math.min(m, l.time), Infinity);
    bests[c.id] = b;
    if (b < fastest) { fastest = b; fastestId = c.id; }
  });
  return (
    <div className="pw-tower-scroll">
      <table className="pw-tower">
        <thead>
          <tr><th>P</th><th>Driver</th><th><button className="pw-gapref" onClick={() => setGapRef(gapRef === "leader" ? "car" : "leader")} title="Switch gap reference: leader / your selected car">{gapRef === "leader" ? "Gap ⇄" : "To car ⇄"}</button></th><th>Int</th><th>Last</th><th>Tyre</th><th>Pit</th></tr>
        </thead>
        <tbody>
          {standings.map((c, idx) => {
            const cmp = COMPOUNDS[c.compound] || COMPOUNDS.MEDIUM;
            const prev = idx > 0 ? standings[idx - 1] : null;
            let interval = "—";
            if (c.status === "dnf") interval = "OUT";
            else if (!prev) interval = "—";
            else if (Math.floor(c.gapLaps) !== Math.floor(prev.gapLaps)) interval = `+${Math.max(1, Math.floor(c.gapLaps) - Math.floor(prev.gapLaps))}L`;
            else interval = `+${Math.max(0, c.gapSeconds - prev.gapSeconds).toFixed(1)}`;
            return (
              <tr
                key={c.id}
                className={`${c.id === activeCarId ? "active" : ""} ${c.team.isPlayer ? "player" : ""} ${c.inPit ? "inpit" : ""} ${c.status === "dnf" ? "dnf" : ""}`}
                style={{ "--team": c.team.color }}
                onClick={() => c.team.isPlayer && onSelect(c.id)}
                title={`${c.name} — ${c.team.name}`}
              >
                <td className="pw-tpos-cell"><span className="pw-tpos">{c.position}</span></td>
                <td className="pw-tdriver">
                  <span className="pw-tbar" style={{ background: c.team.color }} />
                  <span className="pw-tcode">{driverCode(c.name)}</span>
                  <Stars name={c.name} />
                  <span className="pw-carno">#{c.number}</span>
                  {c.id === fastestId && fastest < Infinity && <span className="pw-fl-tag" title={`Fastest lap ${fmtLap(fastest)}`}>FL</span>}
                  {c.inPit && c.status !== "dnf" && <span className="pw-pit-tag">PIT</span>}
                  {c.status === "dnf" && <span className="pw-pit-tag dnf">DNF</span>}
                  {c.penaltySec > 0 && c.status !== "dnf" && <span className="pw-pen-tag" title="Pending time penalty">+{c.penaltySec}s</span>}
                  {c.limitStrikes > 0 && c.status !== "dnf" && <span className="pw-tl-tag" title="Track-limit warnings">TL{c.limitStrikes}</span>}
                </td>
                <td className="pw-tgap">{c.status === "dnf" ? "OUT" : ref ? (c.id === ref.id ? "—" : Math.floor(c.gapLaps) !== Math.floor(ref.gapLaps) ? `${c.gapLaps > ref.gapLaps ? "+" : "-"}${Math.max(1, Math.abs(Math.floor(c.gapLaps) - Math.floor(ref.gapLaps)))}L` : `${c.gapSeconds - ref.gapSeconds >= 0 ? "+" : "-"}${Math.abs(c.gapSeconds - ref.gapSeconds).toFixed(1)}s`) : c.position === 1 ? "LEADER" : c.gapLaps <= 0.0005 ? `+${Math.max(0, c.gapSeconds).toFixed(1)}s` : fmtGap(c.gapLaps, c.gapSeconds)}</td>
                <td className="pw-tint">{interval}</td>
                <td className="pw-tlast" title={c.lastSectors ? `Last lap  S1 ${c.lastSectors[0].toFixed(3)} · S2 ${c.lastSectors[1].toFixed(3)} · S3 ${c.lastSectors[2].toFixed(3)}` : undefined}>
                  <span style={c.lastLapTime ? { color: c.lastLapTime <= fastest + 1e-6 ? "#c77dff" : c.lastLapTime <= bests[c.id] + 1e-6 ? "#00d68f" : undefined } : undefined}>{c.lastLapTime ? fmtLap(c.lastLapTime) : "—"}</span>
                  {c.status !== "dnf" && (
                    <span className="pw-msec">{[0, 1, 2].map((k) => <i key={k} style={{ background: secColor(c, k) }} />)}</span>
                  )}
                </td>
                <td className="pw-ttyre">
                  <span className="pw-tyrebadge" style={{ borderColor: cmp.color, color: cmp.color }}>{TYRE_LETTER[c.compound] || "?"}</span>
                  <span className="pw-tyreage">{c.tireAge}<small>L</small></span>
                </td>
                <td className="pw-tpits">{c.pitCount}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function CompoundDot(props) {
  const { cx, cy, payload } = props;
  const color = COMPOUNDS[payload.compound]?.color || "#F2B33D";
  return <circle cx={cx} cy={cy} r={3.2} fill={color} stroke="#0B0E14" strokeWidth={1} />;
}

function StrategyChart({ car }) {
  if (!car) return null;
  const data = car.lapHistory;
  const avg = data.length ? data.reduce((a, b) => a + b.time, 0) / data.length : 0;
  // A pit stop shows up as a compound change between two consecutive laps —
  // mark those with a vertical line so stints are easy to read at a glance.
  const stintChangeLaps = data.slice(1).filter((d, i) => d.compound !== data[i].compound).map((d) => d.lap);
  const compoundsUsed = [...new Set(data.map((d) => d.compound))];

  return (
    <div className="pw-chartwrap">
      {car.status === "dnf" ? (
        <p className="pw-empty">This car has retired from the race.</p>
      ) : data.length < 2 ? (
        <p className="pw-empty">Lap data will appear once the car completes its opening laps.</p>
      ) : (
        <>
          <ResponsiveContainer width="100%" height={180}>
            <LineChart data={data} margin={{ top: 8, right: 12, bottom: 0, left: 0 }}>
              <CartesianGrid stroke="#232B38" strokeDasharray="3 5" />
              <XAxis dataKey="lap" stroke="#6B7684" fontSize={11} />
              <YAxis stroke="#6B7684" fontSize={11} domain={["dataMin - 1", "dataMax + 1"]} width={44} tickFormatter={(v) => { const r = Math.round(v); return `${Math.floor(r / 60)}:${String(r % 60).padStart(2, "0")}`; }} />
              <Tooltip
                contentStyle={{ background: "#131822", border: "1px solid #232B38", fontSize: 12 }}
                labelFormatter={(l) => `Lap ${l}`}
                formatter={(v, name, props) => [`${fmtLap(v)} — ${COMPOUNDS[props.payload.compound]?.label || ""}`, "Lap time"]}
              />
              <ReferenceLine y={avg} stroke="#6B7684" strokeDasharray="2 4" />
              {stintChangeLaps.map((lap) => (
                <ReferenceLine key={lap} x={lap} stroke="#E23D3D" strokeDasharray="3 3" strokeOpacity={0.6} />
              ))}
              <Line type="monotone" dataKey="time" stroke="#F2B33D" strokeWidth={2} dot={<CompoundDot />} />
            </LineChart>
          </ResponsiveContainer>
          <div className="pw-chart-legend">
            {compoundsUsed.map((c) => (
              <span key={c} className="pw-chart-legend-item">
                <span className="pw-tyre" style={{ background: COMPOUNDS[c].color }} />
                {COMPOUNDS[c].label}
              </span>
            ))}
            {stintChangeLaps.length > 0 && <span className="pw-chart-legend-item pw-chart-legend-pit">┊ Pit stop</span>}
          </div>
        </>
      )}
      {car.status !== "dnf" && (
        <div className="pw-tirebadge-row">
          <span className="pw-tyre-lg" style={{ background: COMPOUNDS[car.compound].color }} />
          <span>{COMPOUNDS[car.compound].label} — {car.tireAge} laps old</span>
        </div>
      )}
    </div>
  );
}

// The lap-time chart only actually changes once per lap (when a new
// lapHistory entry lands) or when the active car/compound switches — not on
// every 250ms simulation tick. Skipping re-renders in between keeps the
// (fairly expensive) recharts SVG from being rebuilt 4x a second for nothing.
const MemoStrategyChart = React.memo(StrategyChart, (prev, next) => {
  const a = prev.car;
  const b = next.car;
  if (a === b) return true;
  if (!a || !b) return false;
  return (
    a.id === b.id &&
    a.status === b.status &&
    a.compound === b.compound &&
    a.tireAge === b.tireAge &&
    a.lapHistory === b.lapHistory
  );
});

function PitControls({ playerCars, activeCarId, setActiveCarId, onEngineMode, onQueuePit, onCancelPit }) {
  const car = playerCars.find((c) => c.id === activeCarId) || playerCars[0];
  if (!car) return null;
  if (car.status === "dnf") {
    return (
      <div className="pw-pitcontrols">
        <div className="pw-cartabs">
          {playerCars.map((c) => (
            <button key={c.id} className={`pw-cartab ${c.id === activeCarId ? "active" : ""}`} onClick={() => setActiveCarId(c.id)}>
              #{c.number} {c.name}<Stars name={c.name} />
            </button>
          ))}
        </div>
        <p className="pw-empty">This car has retired — controls unavailable.</p>
      </div>
    );
  }
  return (
    <div className="pw-pitcontrols">
      <div className="pw-cartabs">
        {playerCars.map((c) => (
          <button key={c.id} className={`pw-cartab ${c.id === activeCarId ? "active" : ""}`} onClick={() => setActiveCarId(c.id)}>
            #{c.number} {c.name}<Stars name={c.name} />
          </button>
        ))}
      </div>

      <div className="pw-control-block">
        <div className="pw-control-label">Engine mode</div>
        <div className="pw-mode-row">
          {Object.entries(ENGINE_MODES).map(([key, m]) => (
            <button key={key} className={`pw-mode-btn ${car.engineMode === key ? "active" : ""}`} onClick={() => onEngineMode(car.id, key)}>
              {m.label}
            </button>
          ))}
        </div>
      </div>

      <div className="pw-control-block">
        <div className="pw-control-label">Box at end of this lap</div>
        <div className="pw-tyre-row">
          {Object.values(COMPOUNDS).map((cmp) => (
            <button key={cmp.key} className="pw-tyre-btn" style={{ borderColor: cmp.color }} onClick={() => onQueuePit(car.id, cmp.key)} disabled={car.inPit}>
              <span className="pw-tyre-sm" style={{ background: cmp.color }} />{cmp.label}
            </button>
          ))}
        </div>
        {car.pitQueued && (
          <div className="pw-pit-pending">
            Pit queued — fitting {COMPOUNDS[car.pendingCompound].label} at the pit entrance
            <button className="pw-cancel" onClick={() => onCancelPit(car.id)}>Cancel</button>
          </div>
        )}
        {car.inPit && <div className="pw-pit-pending serving">Serving pit stop — losing time to rivals now.</div>}
      </div>
    </div>
  );
}

// playerCars is a freshly filtered/spread array every tick, but the fields
// this panel actually displays (mode, compound, pit status...) only change
// on user action or a pit event — not every 250ms.
function sameRelevantCarFields(a, b) {
  return (
    a.id === b.id &&
    a.status === b.status &&
    a.engineMode === b.engineMode &&
    a.compound === b.compound &&
    a.pitQueued === b.pitQueued &&
    a.pendingCompound === b.pendingCompound &&
    a.inPit === b.inPit
  );
}
const MemoPitControls = React.memo(PitControls, (prev, next) => {
  if (prev.activeCarId !== next.activeCarId) return false;
  if (prev.playerCars.length !== next.playerCars.length) return false;
  return prev.playerCars.every((c, i) => sameRelevantCarFields(c, next.playerCars[i]));
});

const EVENT_META = {
  pit: { icon: "🔧", label: "Pit", color: "var(--accent)" },
  overtake: { icon: "➤", label: "Overtake", color: "var(--ok)" },
  incident: { icon: "⚠", label: "Incident", color: "var(--danger)" },
  weather: { icon: "🌧", label: "Weather", color: "#3D8BF2" },
  flag: { icon: "🏁", label: "Flag", color: "var(--text)" },
  strategist: { icon: "🎙", label: "Strategist", color: "#3D8BF2" },
  steward: { icon: "⚖", label: "Stewards", color: "#E8913D" },
  info: { icon: "•", label: "Info", color: "var(--muted)" },
};
const EVENT_FILTERS = ["all", "pit", "overtake", "incident", "weather", "strategist", "steward", "flag"];

function EventLog({ events }) {
  const [filter, setFilter] = useState("all");
  const shown = filter === "all" ? events : events.filter((e) => (e.type || "info") === filter);

  return (
    <div>
      <div className="pw-eventlog-filters">
        {EVENT_FILTERS.map((f) => (
          <button key={f} className={`pw-filter-btn ${filter === f ? "active" : ""}`} onClick={() => setFilter(f)}>
            {f === "all" ? "All" : EVENT_META[f].label}
          </button>
        ))}
      </div>
      <div className="pw-eventlog">
        {shown.length === 0 && <p className="pw-empty">No events of this type yet.</p>}
        {shown.map((e) => {
          const meta = EVENT_META[e.type || "info"];
          return (
            <div key={e.id} className="pw-event-row" style={{ borderLeftColor: meta.color }}>
              <span className="pw-event-icon" aria-hidden="true">{meta.icon}</span>
              <span className="pw-event-lap">L{e.lap}</span>
              <span className="pw-event-text">{e.text}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// events only gets a new array reference when pushEvent actually fires —
// most ticks push nothing, so this skips a full list re-render 4x/second
// for no visual change.
const MemoEventLog = React.memo(EventLog);

function ResultsOverlay({ standings, onReplay, onContinue, isLastRound }) {
  return (
    <div className="pw-overlay">
      <div className="pw-results">
        <h2>Chequered Flag</h2>
        <ol className="pw-podium-list">
          {standings.slice(0, 10).map((c) => (
            <li key={c.id} className={c.team.isPlayer ? "player" : ""}>
              <span className="pw-pos">{c.position}</span>
              <span className="pw-teamchip" style={{ background: c.team.color }} />
              {c.name}<Stars name={c.name} /> <span className="pw-carno">#{c.number}</span>
              {c.penaltySec > 0 && <span className="pw-pen-tag">+{c.penaltySec}s pen</span>}
              <span className="pw-final-gap">{c.status === "dnf" ? "DNF" : fmtGap(c.gapLaps, c.gapSeconds)}</span>
            </li>
          ))}
        </ol>
        <div className="pw-results-actions">
          <button className="pw-secondary-btn" onClick={onReplay}>↻ Replay Race</button>
          <button className="pw-start-btn" onClick={onContinue}>{isLastRound ? "Finish Season →" : "Continue to Team HQ →"}</button>
        </div>
      </div>
    </div>
  );
}

/* ============================== STYLES ============================== */

const CSS = `
  @import url("https://fonts.googleapis.com/css2?family=Titillium+Web:wght@400;600;700;900&display=swap");
  .pw-root {
    --bg: #0B0E14; --panel: #131822; --line: #232B38; --text: #E8ECF1;
    --muted: #6B7684; --accent: #F2B33D; --danger: #E23D3D; --ok: #3DE281;
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, sans-serif;
    background: var(--bg); color: var(--text); min-height: 100%; padding: 16px; box-sizing: border-box;
  }
  .pw-root * { box-sizing: border-box; }
  .pw-root button { font-family: inherit; cursor: pointer; }
  .pw-root button:focus-visible, .pw-root tr:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  @media (prefers-reduced-motion: reduce) { .pw-root * { transition: none !important; animation: none !important; } }

  .pw-topbar, .pw-hq-header {
    display: flex; align-items: center; justify-content: space-between;
    background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
    padding: 12px 18px; margin-bottom: 14px; gap: 16px; flex-wrap: wrap;
  }
  .pw-brand { display: flex; align-items: center; gap: 10px; }
  .pw-brand-mark { background: var(--accent); color: #fff; font-weight: 800; font-size: 12px; padding: 4px 8px; border-radius: 6px; letter-spacing: 0.05em; }
  .pw-brand-name { font-weight: 700; letter-spacing: 0.06em; font-size: 13px; color: var(--muted); }
  .pw-caution-badge {
    background: rgba(225,6,0,0.18); color: var(--accent-text); font-size: 11px; font-weight: 800;
    padding: 3px 9px; border-radius: 100px; letter-spacing: 0.05em; animation: pw-pulse 1.1s ease-in-out infinite;
  }
  @keyframes pw-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
  .pw-sector-flag { animation: pw-pulse 1.3s ease-in-out infinite; }
  .pw-race-status { display: flex; align-items: center; gap: 18px; }
  .pw-lapcounter { font-variant-numeric: tabular-nums; font-size: 14px; color: var(--muted); }
  .pw-lapcounter strong { color: var(--text); font-size: 16px; }
  .pw-clock { font-family: ui-monospace, "SF Mono", "Cascadia Code", monospace; font-size: 15px; color: var(--accent-text); letter-spacing: 0.04em; }
  .pw-speed-controls { display: flex; gap: 6px; }
  .pw-speed-btn { background: transparent; border: 1px solid var(--line); color: var(--muted); padding: 6px 12px; border-radius: 6px; font-size: 12px; font-weight: 600; }
  .pw-speed-btn.active { background: var(--accent); border-color: var(--accent-text); color: #fff; }
  .pw-speed-btn:disabled { opacity: 0.4; cursor: not-allowed; }
  .pw-restart-btn { color: var(--danger); border-color: rgba(226,61,61,0.4); }

  .pw-grid { display: grid; grid-template-columns: 1.15fr 1fr 0.85fr; grid-template-rows: auto auto; gap: 14px; }
  .pw-panel { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; }
  .pw-panel h2 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); margin: 0 0 10px; font-weight: 700; }
  .pw-carno { color: var(--muted); font-size: 0.85em; }

  .pw-track { grid-column: 1; grid-row: 1 / span 2; }
  .pw-timing { grid-column: 2; grid-row: 1 / span 2; }
  .pw-strategy { grid-column: 3; grid-row: 1; }
  .pw-pits { grid-column: 3; grid-row: 2; }
  .pw-log { grid-column: 1 / span 2; grid-row: 3; }

  @media (max-width: 1100px) {
    .pw-grid { grid-template-columns: 1fr; }
    .pw-track, .pw-timing, .pw-strategy, .pw-pits, .pw-log { grid-column: 1; grid-row: auto; }
    .pw-hq-grid { grid-template-columns: 1fr !important; }
  }

  .pw-trackwrap { background: #0E1219; border-radius: 8px; padding: 6px; }
  .pw-tracksvg { width: 100%; height: 320px; display: block; }
  .pw-track-pos { fill: var(--accent); font-size: 16px; font-weight: 700; }
  .pw-track-pit { fill: var(--danger); font-size: 12px; font-weight: 800; letter-spacing: 0.05em; }
  .pw-track-dnf { fill: var(--muted); font-size: 11px; font-weight: 800; letter-spacing: 0.05em; }
  .pw-pit-sign { fill: #0b0e14; font-size: 4.6px; font-weight: 800; }
  .pw-pitlane-label { fill: var(--muted); font-size: 10px; font-weight: 700; letter-spacing: 0.08em; }
  .pw-cardot { transition: transform 0.23s linear, opacity 0.3s ease; }
  .pw-carrot { transition: transform 0.23s linear; }
  .pw-pit-ring { transform-box: fill-box; transform-origin: center; animation: pw-spin 1.6s linear infinite; }
  @media (prefers-reduced-motion: reduce) { .pw-pit-ring { animation: none; } }

  .pw-weather { display: flex; align-items: center; gap: 10px; margin-top: 10px; flex-wrap: wrap; }
  .pw-weather-pill { font-size: 11px; font-weight: 700; text-transform: uppercase; padding: 3px 9px; border-radius: 100px; letter-spacing: 0.05em; }
  .pw-weather-pill.dry { background: rgba(225,6,0,0.15); color: var(--accent-text); }
  .pw-weather-pill.damp { background: rgba(61,139,242,0.15); color: #3D8BF2; }
  .pw-weather-pill.wet { background: rgba(61,139,242,0.3); color: #7db4ff; }
  .pw-weather-pill.caution { background: rgba(226,61,61,0.15); color: var(--danger); }
  .pw-rainbar { flex: 1; height: 5px; background: var(--line); border-radius: 4px; overflow: hidden; min-width: 60px; }
  .pw-rainbar-fill { height: 100%; background: #3D8BF2; transition: width 0.4s ease; }
  .pw-rainlabel { font-size: 11px; color: var(--muted); white-space: nowrap; }

  .pw-tower-scroll { max-height: 460px; overflow-y: auto; }
  .pw-tower { width: 100%; border-collapse: collapse; font-size: 12.5px; }
  .pw-tower th { text-align: left; color: var(--muted); font-weight: 600; padding: 6px 8px; border-bottom: 1px solid var(--line); position: sticky; top: 0; background: var(--panel); }
  .pw-tower td { padding: 7px 8px; border-bottom: 1px solid rgba(35,43,56,0.5); font-variant-numeric: tabular-nums; }
  .pw-tower tr.player { background: rgba(225,6,0,0.06); cursor: pointer; }
  .pw-tower tr.active { outline: 1px solid var(--accent); }
  .pw-tower tr.inpit { opacity: 0.55; }
  .pw-tower tr.dnf { opacity: 0.4; }
  .pw-teamchip { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; }
  .pw-tyre { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 5px; }
  .pw-tyre-lg { display: inline-block; width: 14px; height: 14px; border-radius: 50%; }
  .pw-tyre-sm { display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 6px; }
  .pw-pit-tag { margin-left: 6px; background: rgba(226,61,61,0.15); color: var(--danger); font-size: 9.5px; font-weight: 800; padding: 1px 5px; border-radius: 4px; letter-spacing: 0.04em; }
  .pw-pen-tag { margin-left: 6px; background: rgba(232,145,61,0.18); color: #E8913D; font-size: 9.5px; font-weight: 800; padding: 1px 5px; border-radius: 4px; }
  .pw-tl-tag { margin-left: 6px; background: rgba(107,118,132,0.2); color: var(--muted); font-size: 9.5px; font-weight: 800; padding: 1px 5px; border-radius: 4px; }
  .pw-pit-tag.dnf { background: rgba(107,118,132,0.2); color: var(--muted); }

  .pw-empty { color: var(--muted); font-size: 13px; }
  .pw-tirebadge-row { display: flex; align-items: center; gap: 8px; margin-top: 8px; font-size: 12.5px; color: var(--muted); }
  .pw-chart-legend { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 4px; font-size: 11px; color: var(--muted); }
  .pw-chart-legend-item { display: flex; align-items: center; gap: 5px; }
  .pw-chart-legend-pit { color: var(--danger); }
  .pw-cliffwarn { margin-top: 10px; padding: 8px 10px; border-radius: 6px; font-size: 12.5px; font-weight: 600; background: rgba(226,61,61,0.12); color: var(--danger); }
  .pw-undercut { margin-top: 10px; padding: 8px 10px; border-radius: 6px; font-size: 12.5px; font-weight: 600; }
  .pw-undercut.ok { background: rgba(61,226,129,0.12); color: var(--ok); }
  .pw-undercut.hold { background: rgba(107,118,132,0.12); color: var(--muted); }

  .pw-cartabs { display: flex; gap: 6px; margin-bottom: 12px; }
  .pw-cartab { background: transparent; border: 1px solid var(--line); color: var(--muted); padding: 6px 10px; border-radius: 6px; font-size: 12px; flex: 1; }
  .pw-cartab.active { border-color: var(--accent-text); color: var(--accent-text); }
  .pw-control-block { margin-bottom: 14px; }
  .pw-control-label { font-size: 11px; color: var(--muted); margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.05em; }
  .pw-mode-row, .pw-tyre-row { display: flex; gap: 6px; flex-wrap: wrap; }
  .pw-mode-btn { background: transparent; border: 1px solid var(--line); color: var(--text); padding: 6px 10px; border-radius: 6px; font-size: 12px; }
  .pw-mode-btn.active { background: var(--accent); color: #fff; border-color: var(--accent-text); }
  .pw-tyre-btn { background: transparent; border: 1px solid var(--line); color: var(--text); padding: 6px 10px; border-radius: 6px; font-size: 12px; display: flex; align-items: center; }
  .pw-tyre-btn.active { background: rgba(225,6,0,0.12); border-width: 2px; }
  .pw-tyre-btn:disabled { opacity: 0.35; cursor: not-allowed; }
  .pw-pit-pending { margin-top: 10px; background: rgba(225,6,0,0.1); color: var(--accent-text); padding: 7px 10px; border-radius: 6px; font-size: 12px; display: flex; align-items: center; justify-content: space-between; }
  .pw-pit-pending.serving { background: rgba(226,61,61,0.1); color: var(--danger); }

  .pw-strategist-note {
    background: rgba(61,139,242,0.08); border: 1px solid rgba(61,139,242,0.25); border-radius: 8px;
    padding: 10px 12px; font-size: 12.5px; color: var(--text); margin-bottom: 16px; line-height: 1.5;
  }
  .pw-strategist-tag {
    background: #3D8BF2; color: #08101d; font-size: 10px; font-weight: 800; padding: 1px 7px;
    border-radius: 100px; letter-spacing: 0.04em; margin-right: 6px;
  }
  .pw-advice-tag {
    margin-left: 6px; background: rgba(61,139,242,0.18); color: #7db4ff; font-size: 9px; font-weight: 800;
    padding: 1px 5px; border-radius: 4px; letter-spacing: 0.03em;
  }
  .pw-cancel { background: transparent; border: 1px solid var(--accent); color: var(--accent-text); border-radius: 5px; padding: 2px 8px; font-size: 11px; }

  .pw-practice-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin: 14px 0 4px; }
  .pw-practice-card {
    background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 14px;
    text-align: center; display: flex; flex-direction: column; align-items: center; gap: 4px;
  }
  .pw-practice-label { font-size: 12px; color: var(--muted); margin-top: 4px; }
  .pw-practice-value { font-size: 20px; font-weight: 800; color: var(--accent-text); }
  .pw-practice-sub { font-size: 10.5px; color: var(--muted); }

  .pw-eventlog-filters { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 8px; }
  .pw-filter-btn { background: transparent; border: 1px solid var(--line); color: var(--muted); padding: 4px 10px; border-radius: 100px; font-size: 11px; font-weight: 600; }
  .pw-filter-btn.active { background: var(--accent); border-color: var(--accent-text); color: #fff; }
  .pw-eventlog { max-height: 190px; overflow-y: auto; font-size: 12.5px; }
  .pw-event-row { display: flex; align-items: baseline; gap: 8px; padding: 5px 8px; border-bottom: 1px solid rgba(35,43,56,0.5); border-left: 3px solid var(--line); }
  .pw-event-icon { flex-shrink: 0; font-size: 12px; }
  .pw-event-lap { color: var(--accent-text); font-weight: 700; width: 30px; flex-shrink: 0; }
  .pw-event-text { color: var(--text); }

  .pw-overlay { position: fixed; inset: 0; background: rgba(11,14,20,0.85); display: flex; align-items: center; justify-content: center; z-index: 50; padding: 20px; }
  .pw-results { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 24px 28px; min-width: 320px; max-width: 480px; width: 100%; }
  .pw-results h2 { color: var(--accent-text); font-size: 18px; margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.06em; }
  .pw-podium-list { list-style: none; margin: 0; padding: 0; }
  .pw-podium-list li { display: flex; align-items: center; gap: 8px; padding: 7px 0; border-bottom: 1px solid rgba(35,43,56,0.5); font-size: 13.5px; }
  .pw-podium-list li.player { color: var(--accent-text); }
  .pw-pos { width: 22px; font-weight: 700; color: var(--muted); }
  .pw-final-gap { margin-left: auto; color: var(--muted); font-variant-numeric: tabular-nums; }
  .pw-results-actions { display: flex; gap: 10px; margin-top: 16px; }
  .pw-secondary-btn { flex: 1; background: transparent; border: 1px solid var(--line); color: var(--text); padding: 10px; border-radius: 8px; font-size: 13px; font-weight: 600; }
  .pw-start-btn { flex: 1; background: var(--accent); border: none; color: #fff; padding: 10px; border-radius: 8px; font-size: 13px; font-weight: 700; }

  /* ---- Team HQ (calendar / development / qualifying) ---- */
  .pw-hq { max-width: 1100px; margin: 0 auto; }
  .pw-saves { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; width: min(720px, 100%); max-height: 90vh; overflow: auto; padding: 18px; color: var(--text); }
  .pw-saves-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; font-size: 16px; }
  .pw-saves-new { border: 1px solid var(--line); border-radius: 10px; padding: 12px; margin-bottom: 12px; }
  .pw-saves-label { font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); margin-bottom: 6px; }
  .pw-saves-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
  .pw-saves-input { flex: 1; min-width: 140px; background: var(--bg); border: 1px solid var(--line); color: var(--text); padding: 8px 10px; border-radius: 8px; font-size: 13px; font-family: inherit; }
  .pw-saves-input:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
  .pw-saves-hint { font-size: 11.5px; color: var(--muted); margin-top: 6px; }
  .pw-saves-notice { font-size: 12.5px; padding: 8px 10px; border-radius: 8px; margin-bottom: 10px; border: 1px solid var(--line); }
  .pw-saves-notice.ok { color: var(--ok); border-color: var(--ok); }
  .pw-saves-notice.bad { color: var(--danger); border-color: var(--danger); }
  .pw-saves-list { display: flex; flex-direction: column; gap: 8px; margin-bottom: 12px; }
  .pw-saves-empty { color: var(--muted); font-size: 13px; padding: 14px; text-align: center; border: 1px dashed var(--line); border-radius: 10px; }
  .pw-save-item { border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; display: flex; flex-direction: column; gap: 8px; background: var(--bg); }
  .pw-save-name { font-weight: 700; font-size: 14px; word-break: break-word; }
  .pw-save-meta { font-size: 11.5px; color: var(--muted); margin-top: 2px; }
  .pw-save-actions { display: flex; gap: 6px; flex-wrap: wrap; }
  .pw-save-actions .pw-hq-devbtn, .pw-saves-import .pw-hq-devbtn, .pw-saves-paste .pw-hq-devbtn { padding: 6px 10px; font-size: 12px; }
  .pw-saves-import { display: flex; gap: 8px; flex-wrap: wrap; }
  .pw-saves-paste { margin-top: 10px; display: flex; flex-direction: column; gap: 8px; align-items: flex-start; }
  .pw-saves-textarea { width: 100%; background: var(--bg); border: 1px solid var(--line); color: var(--text); border-radius: 8px; padding: 8px; font-family: ui-monospace, monospace; font-size: 11.5px; }

  .pw-stars { color: #F2B33D; margin-left: 4px; font-size: 0.85em; letter-spacing: 1px; text-shadow: 0 0 6px rgba(242,179,61,0.35); }
  .pw-fab { position: fixed; left: 12px; bottom: 12px; z-index: 40; display: flex; gap: 6px; }
  .pw-fab-btn { background: rgba(19,24,34,0.92); border: 1px solid var(--line); color: var(--text); padding: 7px 11px; border-radius: 999px; font-size: 12px; font-weight: 600; backdrop-filter: blur(4px); }
  .pw-fab-btn:hover { border-color: var(--accent-text); color: var(--accent-text); }
  .pw-overlay-top { z-index: 60; }
  .pw-settings { width: min(560px, 100%); }
  .pw-set-group { border: 1px solid var(--line); border-radius: 10px; padding: 12px; margin-bottom: 12px; }
  .pw-set-row { display: flex; align-items: center; gap: 10px; font-size: 13px; margin-top: 8px; flex-wrap: wrap; }
  .pw-set-row input[type=range] { flex: 1; min-width: 120px; }
  .pw-set-row .pw-saves-input { flex: 0 0 auto; min-width: 150px; margin-left: auto; }
  .pw-swatches { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
  .pw-swatch { width: 28px; height: 28px; border-radius: 50%; border: 2px solid transparent; padding: 0; }
  .pw-swatch.on { border-color: #fff; box-shadow: 0 0 0 2px var(--accent); }
  .pw-colorpick { width: 34px; height: 30px; padding: 0; border: 1px solid var(--line); background: var(--bg); border-radius: 6px; }
  .pw-set-preview { margin-top: 10px; font-weight: 700; font-size: 13px; display: flex; align-items: center; gap: 6px; }
  .pw-tabs { display: flex; gap: 6px; margin-bottom: 12px; flex-wrap: wrap; }
  .pw-tab { background: var(--panel); border: 1px solid var(--line); color: var(--muted); padding: 8px 14px; border-radius: 8px; font-size: 12.5px; font-weight: 700; }
  .pw-tab.on { border-color: var(--accent-text); color: var(--accent-text); }
  .pw-stat-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 10px; margin-top: 14px; }
  .pw-stat-card { background: var(--bg); border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; display: flex; flex-direction: column; gap: 4px; }
  .pw-stat-card span { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }
  .pw-stat-card strong { font-size: 20px; }
  .pw-table-wrap { overflow-x: auto; }
  .pw-table { width: 100%; border-collapse: collapse; font-size: 13px; }
  .pw-table th { text-align: left; color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; padding: 6px 8px; border-bottom: 1px solid var(--line); }
  .pw-table td { padding: 8px; border-bottom: 1px solid var(--line); }
  .pw-board-meter { height: 10px; background: var(--bg); border: 1px solid var(--line); border-radius: 999px; overflow: hidden; margin-bottom: 8px; }
  .pw-board-fill { height: 100%; transition: width .4s ease; }
  .pw-board-fill.great, .pw-board-fill.good { background: var(--ok); }
  .pw-board-fill.warn { background: var(--accent); }
  .pw-board-fill.bad, .pw-board-fill.crit { background: var(--danger); }
  .pw-board-line { font-size: 13px; margin-bottom: 8px; }
  .pw-board-obj { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; font-size: 13px; }
  .pw-board-obj em { color: var(--muted); font-style: normal; }
  .pw-obj-dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; border: 2px solid var(--muted); margin-right: 8px; }
  .pw-obj-dot.ok { background: var(--ok); border-color: var(--ok); }
  .pw-board-warn { margin-top: 10px; color: var(--danger); font-size: 12.5px; font-weight: 700; }
  .pw-press-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; font-size: 13px; }
  .pw-press-list li { display: flex; flex-direction: column; gap: 2px; }
  .pw-press-outlet { font-size: 10.5px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--accent-text); font-weight: 800; }
  .pw-press-body { color: var(--muted); font-size: 12.5px; }
  .pw-press-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; }
  .pw-press-card { background: var(--bg); border: 1px solid var(--line); border-radius: 10px; padding: 12px; }
  .pw-press-card h3 { margin: 6px 0; font-size: 15px; }
  .pw-press-card p { margin: 0; color: var(--muted); font-size: 12.5px; line-height: 1.45; }
  .pw-press-opts { display: flex; flex-direction: column; gap: 8px; }
  .pw-press-opt { text-align: left; background: var(--bg); border: 1px solid var(--line); color: var(--text); padding: 12px 14px; border-radius: 10px; font-size: 13.5px; display: flex; justify-content: space-between; gap: 10px; }
  .pw-press-opt:hover { border-color: var(--accent-text); }
  .pw-press-risk { color: var(--danger); font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.06em; }
  .pw-press-reply p { margin: 0 0 10px; }
  .pw-pos-txt { color: var(--ok); }
  .pw-neg-txt { color: var(--danger); }
  .pw-fired { border-color: var(--danger); }

  .pw-hq-devbtn { background: transparent; border: 1px solid var(--accent); color: var(--accent-text); padding: 8px 14px; border-radius: 8px; font-size: 12.5px; font-weight: 700; display: flex; align-items: center; gap: 8px; }
  .pw-devpoints-pill { background: rgba(225,6,0,0.15); padding: 2px 8px; border-radius: 100px; font-size: 11px; }
  .pw-hq-grid { display: grid; grid-template-columns: 1.2fr 1fr; gap: 14px; }

  .pw-calendar-list { list-style: none; margin: 0 0 16px; padding: 0; }
  .pw-calendar-list li { display: flex; align-items: center; gap: 10px; padding: 9px 4px; border-bottom: 1px solid rgba(35,43,56,0.5); font-size: 13px; }
  .pw-calendar-list li.next { color: var(--accent-text); font-weight: 700; }
  .pw-calendar-list li.done { color: var(--muted); }
  .pw-round-no { width: 30px; color: var(--muted); font-weight: 700; }
  .pw-round-name { flex: 1; }
  .pw-round-meta { color: var(--muted); font-size: 11.5px; }
  .pw-round-status { color: var(--muted); font-size: 11.5px; min-width: 80px; text-align: right; }

  .pw-standings-list { list-style: none; margin: 0; padding: 0; }
  .pw-standings-list li { display: flex; align-items: center; gap: 8px; padding: 6px 0; border-bottom: 1px solid rgba(35,43,56,0.5); font-size: 13px; }
  .pw-standings-list li.player { color: var(--accent-text); }

  .pw-devpool { font-size: 13px; color: var(--muted); margin-bottom: 8px; }
  .pw-devpool strong { color: var(--accent-text); font-size: 15px; }
  .pw-devnote { font-size: 12px; color: var(--muted); margin: 0 0 18px; }
  .pw-dev-row { margin-bottom: 22px; }
  .pw-dev-label-row { display: flex; justify-content: space-between; margin-bottom: 6px; }
  .pw-dev-label { font-weight: 700; font-size: 13.5px; }
  .pw-dev-pct { color: var(--accent-text); font-variant-numeric: tabular-nums; font-size: 13px; }
  .pw-dev-bar { height: 8px; background: var(--line); border-radius: 5px; overflow: hidden; margin-bottom: 8px; }
  .pw-dev-bar-fill { height: 100%; background: var(--accent); transition: width 0.4s ease; }
  .pw-dev-desc { color: var(--muted); font-size: 12px; margin: 0 0 10px; }
  .pw-invest-btn { background: transparent; border: 1px solid var(--accent); color: var(--accent-text); padding: 7px 14px; border-radius: 7px; font-size: 12.5px; font-weight: 700; }
  .pw-invest-btn:disabled { opacity: 0.35; cursor: not-allowed; border-color: var(--line); color: var(--muted); }

  .pw-hq-budget { font-size: 12.5px; color: var(--muted); margin: -6px 0 14px; }
  .pw-danger-btn { border-color: rgba(226,61,61,0.4) !important; color: var(--danger) !important; }
  .pw-loading {
    display: flex; align-items: center; justify-content: center; min-height: 60vh;
    color: var(--muted); font-size: 14px; letter-spacing: 0.04em;
  }
  .pw-loading-card { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 28px 36px; text-align: center; min-width: 280px; }
  .pw-loading-spinner { width: 34px; height: 34px; margin: 0 auto 14px; border: 3px solid var(--line); border-top-color: var(--accent-text); border-radius: 50%; animation: pw-spin 0.9s linear infinite; }
  .pw-loading-title { font-weight: 700; font-size: 15px; }
  .pw-loading-sub { font-size: 12px; color: var(--muted); margin-top: 4px; }
  @keyframes pw-spin { to { transform: rotate(360deg); } }
  @media (prefers-reduced-motion: reduce) { .pw-loading-spinner { animation-duration: 3s; } }
  .pw-sponsor-banner {
    background: rgba(61,226,129,0.08); border: 1px solid rgba(61,226,129,0.25); border-radius: 8px;
    padding: 9px 12px; font-size: 12.5px; color: var(--text); margin: -2px 0 14px;
  }
  .pw-sponsor-offers { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; margin-top: 12px; }
  .pw-sponsor-offer { background: var(--bg); border: 1px solid var(--line); border-radius: 10px; padding: 14px; display: flex; flex-direction: column; gap: 6px; }
  .pw-sponsor-offer.risk-low { border-top: 3px solid var(--ok); }
  .pw-sponsor-offer.risk-medium { border-top: 3px solid var(--accent); }
  .pw-sponsor-offer.risk-high { border-top: 3px solid var(--danger); }
  .pw-sponsor-name { font-weight: 700; font-size: 15px; }
  .pw-sponsor-risk { font-size: 11.5px; color: var(--muted); }
  .pw-sponsor-desc { font-size: 13px; margin: 4px 0; flex: 1; }
  .pw-sponsor-pay { display: flex; justify-content: space-between; font-size: 12.5px; color: var(--muted); margin-bottom: 8px; }
  .pw-sponsor-pay strong { color: var(--text); }
  .pw-sponsor-result { font-size: 12.5px; margin: 10px 0 0; padding: 8px 10px; border-radius: 6px; }
  .pw-sponsor-result.achieved { background: rgba(61,226,129,0.12); color: var(--ok); }
  .pw-sponsor-result.missed { background: rgba(226,61,61,0.1); color: var(--danger); }

  .pw-transfer-list { list-style: none; margin: 0; padding: 0; }
  .pw-transfer-list li { padding: 6px 0; border-bottom: 1px solid rgba(35,43,56,0.5); font-size: 12.5px; color: var(--muted); }
  .pw-hq-budget strong { color: var(--accent-text); font-size: 14px; }

  .pw-driver-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 10px; margin-bottom: 16px; }
  .pw-driver-card {
    background: transparent; border: 1px solid var(--line); border-radius: 8px; padding: 10px;
    text-align: left; color: var(--text); display: flex; flex-direction: column; gap: 6px;
  }
  .pw-driver-card.selected { border-color: var(--accent-text); background: rgba(225,6,0,0.08); }
  .pw-driver-card.signed { cursor: default; }
  .pw-driver-name { font-weight: 700; font-size: 13px; }
  .pw-driver-stat-row { display: flex; align-items: center; gap: 6px; font-size: 10.5px; color: var(--muted); }
  .pw-driver-stat-row span { width: 62px; flex-shrink: 0; }
  .pw-driver-bar { flex: 1; height: 5px; background: var(--line); border-radius: 4px; overflow: hidden; }
  .pw-driver-bar div { height: 100%; background: var(--accent); }
  .pw-driver-price { font-size: 11.5px; color: var(--accent-text); font-weight: 700; margin-top: 2px; }
  .pw-driver-footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; font-size: 12.5px; color: var(--muted); }
  .pw-driver-footer .pw-start-btn { flex: 0 0 auto; padding: 10px 18px; }
  .pw-driver-card.signed { cursor: default; }
  .pw-driver-actions { display: flex; gap: 6px; margin-top: 4px; }
  .pw-driver-actions .pw-invest-btn { flex: 1; padding: 6px 8px; font-size: 11.5px; }
  .pw-driver-actions .pw-cancel { flex: 1; padding: 6px 8px; }
  .pw-driver-card.vacant { border-style: dashed; }
  .pw-driver-market-list { display: flex; flex-direction: column; gap: 5px; }
  .pw-market-row {
    display: flex; align-items: center; gap: 6px; background: transparent; border: 1px solid var(--line);
    color: var(--text); padding: 6px 8px; border-radius: 6px; font-size: 11px; text-align: left;
  }
  .pw-market-row:disabled { opacity: 0.35; cursor: not-allowed; }
  .pw-market-row .pw-carno { flex: 1; }
  .pw-market-row .pw-final-gap { color: var(--accent-text); font-weight: 700; }

  .pw-tier-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; }
  .pw-tier-card {
    background: transparent; border: 1px solid var(--line); border-radius: 10px; padding: 16px;
    text-align: left; color: var(--text); display: flex; flex-direction: column; gap: 8px;
  }
  .pw-tier-card:hover { border-color: var(--accent-text); background: rgba(225,6,0,0.06); }
  .pw-tier-name { font-weight: 800; font-size: 15px; color: var(--accent-text); }
  .pw-tier-stat-row { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--muted); }
  .pw-tier-stat-row span { width: 60px; flex-shrink: 0; }
  .pw-tier-meta { font-size: 12px; color: var(--muted); }
  .pw-tier-meta strong { color: var(--text); }
  .pw-tier-desc { font-size: 12px; color: var(--muted); margin: 4px 0 0; line-height: 1.5; }

  .pw-fia-list { list-style: none; margin: 0 0 8px; padding: 0; }
  .pw-fia-list li { display: flex; align-items: center; gap: 8px; padding: 8px 4px; border-bottom: 1px solid rgba(35,43,56,0.5); font-size: 13px; }
  .pw-fia-list li.player { background: rgba(225,6,0,0.06); }
  .pw-fia-team { flex: 1; }
  .pw-fia-delta { font-size: 11.5px; font-weight: 700; padding: 2px 9px; border-radius: 100px; }
  .pw-fia-delta.up { background: rgba(61,226,129,0.15); color: var(--ok); }
  .pw-fia-delta.down { background: rgba(226,61,61,0.15); color: var(--danger); }
  .pw-fia-delta.flat { background: rgba(107,118,132,0.15); color: var(--muted); }

  .pw-quali-list { list-style: none; margin: 0 0 16px; padding: 0; }
  .pw-quali-row {
    display: flex; align-items: center; gap: 8px; padding: 7px 4px;
    border-bottom: 1px solid rgba(35,43,56,0.5); font-size: 13.5px;
    opacity: 0; animation: pw-quali-in 0.35s ease forwards;
  }
  .pw-quali-row.player { color: var(--accent-text); }
  .pw-form { display: inline-block; margin-left: 8px; padding: 1px 7px; border-radius: 10px; font-size: 11px; font-weight: 700; border: 1px solid var(--line); white-space: nowrap; }
  .pw-form-up { color: var(--ok); border-color: rgba(61,226,129,0.4); background: rgba(61,226,129,0.08); }
  .pw-form-down { color: var(--danger); border-color: rgba(226,61,61,0.4); background: rgba(226,61,61,0.08); }
  .pw-form-flat { color: var(--muted); }
  .pw-form-fx { font-weight: 500; opacity: 0.85; }
  .pw-pole-tag {
    margin-left: 6px; background: rgba(225,6,0,0.18); color: var(--accent-text);
    font-size: 9.5px; font-weight: 800; padding: 1px 6px; border-radius: 4px; letter-spacing: 0.05em;
  }
  @keyframes pw-quali-in { from { opacity: 0; transform: translateX(-6px); } to { opacity: 1; transform: translateX(0); } }
  @media (prefers-reduced-motion: reduce) { .pw-quali-row { animation: none; opacity: 1; } }
  .pw-gapref { background: none; border: 0; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; cursor: pointer; padding: 0; }
  .pw-gapref:hover { color: #fff; }
  .pw-fl-tag { margin-left: 4px; font-size: 9px; font-weight: 800; padding: 1px 4px; border-radius: 3px; background: #c77dff; color: #0a0a10; }
  .pw-trackwrap { position: relative; overflow: hidden; }
  .pw-trackstage { position: relative; width: 100%; aspect-ratio: 1000 / 600; max-height: 70vh; overflow: hidden; border-radius: 3px; }
  .pw-root .pw-trackstage .pw-layer { position: absolute; left: 0; top: 0; width: 100%; height: 100%; max-height: none; aspect-ratio: auto; transform-origin: 0 0; transition: transform 0.25s linear; will-change: transform; }
  .pw-root .pw-trackstage .pw-layer-ui, .pw-root .pw-trackstage .pw-layer-dyn { transition: none; will-change: auto; }
  .pw-root .pw-trackstage .pw-layer-ui { pointer-events: none; }
  .pw-cam { transform-origin: 0 0; transition: transform 0.25s linear; }
  .pw-msec { display: inline-flex; gap: 2px; margin-left: 6px; vertical-align: middle; }
  .pw-msec i { display: block; width: 7px; height: 4px; border-radius: 1px; }
  .pw-cambtn { position: absolute; top: 10px; right: 10px; z-index: 2; background: rgba(10,10,16,0.82); color: #e8ecf1; border: 1px solid var(--line); border-radius: 3px; font: inherit; font-size: 11px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; padding: 5px 9px; cursor: pointer; }
  .pw-cambtn:hover, .pw-cambtn.on { border-color: var(--accent); color: #fff; }
  .pw-led-off { fill: #10141b; }
  .pw-ledglow { opacity: 0.35; }
  .pw-led-yellow { fill: #ffc400; animation: pw-led-flash 0.6s steps(2) infinite; }
  .pw-led-sc { fill: #ffc400; }
  .pw-led-green { fill: #00e070; animation: pw-led-flash 0.5s steps(2) infinite; }
  @keyframes pw-led-flash { 50% { fill: #2b2210; } }
  .pw-sc-bar { animation: pw-sc-blink 0.5s steps(2) infinite; }
  @keyframes pw-sc-blink { 50% { fill: #3a2a00; } }
  .pw-sc-banner { animation: pw-sc-pulse 1.2s ease-in-out infinite; }
  @keyframes pw-sc-pulse { 50% { opacity: 0.75; } }
  .pw-rain { animation: pw-rain-fall 0.45s linear infinite; }
  @keyframes pw-rain-fall { to { transform: translate(-11.6px, 46.6px); } }
  .pw-loading-bar { height: 4px; background: #2a2a38; border-radius: 2px; margin: 14px 0 10px; overflow: hidden; }
  .pw-loading-fill { height: 100%; background: var(--accent); transition: width 0.25s ease; }
  .pw-loading-steps { list-style: none; margin: 0; padding: 0; font-size: 12px; color: var(--muted); text-align: left; }
  .pw-loading-steps li.done { color: var(--ok); }
  .pw-loading-steps li.now { color: #fff; }
  /* ================= GLOBAL — modern F1 broadcast theme ================= */
  .pw-root {
    --bg: #0a0a10; --panel: #15151e; --line: #2a2a38; --text: #ffffff; --muted: #8b8b9c;
    --accent: #e10600; --accent-text: #ff5a4d; --danger: #ff4b3e; --ok: #00d68f; --purple: #b565ff;
    font-family: "Titillium Web", Inter, ui-sans-serif, system-ui, sans-serif;
    min-height: 100vh;
    background:
      radial-gradient(1200px 500px at 50% -120px, rgba(225,6,0,0.14), transparent 70%),
      repeating-linear-gradient(45deg, rgba(255,255,255,0.018) 0 2px, transparent 2px 5px),
      var(--bg);
  }
  .pw-root .pw-panel {
    background: linear-gradient(180deg, #1a1a25 0%, #14141c 100%);
    border: 1px solid var(--line); border-radius: 6px; padding: 12px 14px;
    box-shadow: 0 8px 24px rgba(0,0,0,0.35);
  }
  .pw-root .pw-panel h2 {
    display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 700;
    letter-spacing: 0.14em; color: #fff; margin: 0 0 10px; text-transform: uppercase;
  }
  .pw-root .pw-panel h2::before {
    content: ""; width: 5px; height: 14px; background: var(--accent); transform: skewX(-18deg); flex-shrink: 0;
  }

  /* Top broadcast bar */
  .pw-f1bar {
    background: linear-gradient(90deg, #15151e 0%, #1c1c28 100%); border: 1px solid var(--line);
    border-bottom: 3px solid var(--accent); border-radius: 6px; padding: 8px 14px; margin-bottom: 12px;
    position: relative; overflow: hidden;
  }
  .pw-f1bar::after {
    content: ""; position: absolute; right: 0; top: 0; bottom: 0; width: 240px; pointer-events: none;
    background: repeating-linear-gradient(115deg, rgba(255,255,255,0.04) 0 8px, transparent 8px 16px);
  }
  .pw-f1id { display: flex; align-items: center; gap: 12px; min-width: 0; }
  .pw-f1badge {
    background: var(--accent); color: #fff; font-weight: 900; font-size: 15px; letter-spacing: 0.06em;
    padding: 6px 16px 6px 12px; clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 0 100%);
  }
  .pw-f1title { display: flex; flex-direction: column; line-height: 1.1; }
  .pw-f1round { font-size: 10.5px; letter-spacing: 0.2em; color: var(--muted); font-weight: 700; }
  .pw-f1circuit { font-size: 16px; font-weight: 900; letter-spacing: 0.04em; text-transform: uppercase; }
  .pw-root .pw-caution-badge { background: #ffd60a; color: #111; border-radius: 3px; padding: 4px 10px; font-weight: 900; }
  .pw-finished-badge { background: #fff; color: #111; font-weight: 900; font-size: 11px; padding: 4px 10px; border-radius: 3px; letter-spacing: 0.08em; }
  .pw-root .pw-race-status { gap: 14px; z-index: 1; }
  .pw-root .pw-lapcounter {
    display: flex; align-items: baseline; gap: 8px; background: #0a0a10; border: 1px solid var(--line);
    border-left: 4px solid var(--accent); padding: 4px 14px; border-radius: 3px; color: var(--muted);
  }
  .pw-lap-label { font-size: 11px; font-weight: 700; letter-spacing: 0.2em; color: var(--muted); }
  .pw-root .pw-lapcounter strong { font-size: 26px; font-weight: 900; color: #fff; line-height: 1; }
  .pw-lap-total { font-size: 14px; font-weight: 600; color: var(--muted); }
  .pw-root .pw-clock { color: #fff; background: #0a0a10; border: 1px solid var(--line); padding: 7px 12px; border-radius: 3px; font-size: 15px; font-weight: 700; }
  .pw-root .pw-speed-controls { z-index: 1; }
  .pw-root .pw-speed-btn { border-radius: 3px; border: 1px solid var(--line); background: #0a0a10; color: #cfcfdb; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; font-size: 11px; }
  .pw-root .pw-speed-btn:hover:not(:disabled) { border-color: #fff; color: #fff; }
  .pw-root .pw-speed-btn.active { background: var(--accent); border-color: var(--accent-text); color: #fff; }
  .pw-root .pw-restart-btn { color: #ff8a80; border-color: rgba(255,75,62,0.4); }

  /* Layout: tower | circuit | strategy+pit wall, feed underneath */
  @media (min-width: 1101px) {
    .pw-root .pw-grid { grid-template-columns: minmax(400px, 460px) minmax(0, 1fr) minmax(290px, 340px); gap: 12px; }
    .pw-root .pw-timing { grid-column: 1; grid-row: 1 / span 2; }
    .pw-root .pw-track { grid-column: 2; grid-row: 1 / span 2; }
    .pw-root .pw-strategy { grid-column: 3; grid-row: 1; }
    .pw-root .pw-pits { grid-column: 3; grid-row: 2; }
    .pw-root .pw-log { grid-column: 1 / span 3; grid-row: 3; }
  }

  /* Phones / narrow screens: nothing may push the page wider than the screen
     (that made mobile browsers zoom out and jump around during a race). */
  @media (max-width: 1100px) {
    .pw-root .pw-grid { grid-template-columns: minmax(0, 1fr); }
    .pw-root .pw-grid > *, .pw-root .pw-hq-grid > * { min-width: 0; }
    .pw-root .pw-tower-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
  }
  @media (max-width: 640px) {
    .pw-root { overflow-x: hidden; }
    .pw-root .pw-speed-controls { flex-wrap: wrap; }
    .pw-root .pw-fx-heavy { display: none; }
    .pw-root .pw-tower .pw-carno, .pw-root .pw-tower .pw-tl-tag, .pw-root .pw-tower .pw-msec { display: none; }
    .pw-root .pw-tower th, .pw-root .pw-tower td { padding-left: 4px; padding-right: 4px; }
    .pw-root .pw-tower { font-size: 12px; }
    .pw-root .pw-panel { padding: 12px 10px; }
  }

  /* Timing tower — F1 TV style */
  .pw-root .pw-tower-scroll { max-height: 640px; }
  .pw-root .pw-tower { font-size: 13px; border-collapse: separate; border-spacing: 0 2px; }
  .pw-root .pw-tower th {
    background: transparent; color: var(--muted); font-size: 10px; letter-spacing: 0.14em; text-transform: uppercase;
    font-weight: 700; padding: 4px 6px; border-bottom: none;
  }
  .pw-root .pw-tower td { padding: 0; border-bottom: none; background: #1d1d29; height: 29px; white-space: nowrap; }
  .pw-root .pw-tower tr { cursor: default; }
  .pw-root .pw-tower tr td:first-child { border-radius: 3px 0 0 3px; }
  .pw-root .pw-tower tr td:last-child { border-radius: 0 3px 3px 0; padding-right: 8px; }
  .pw-root .pw-tower tr.player td { background: linear-gradient(90deg, color-mix(in srgb, var(--team) 26%, #1d1d29), #232331); cursor: pointer; }
  .pw-root .pw-tower tr.player { background: none; cursor: pointer; }
  .pw-root .pw-tower tr.active { outline: none; }
  .pw-root .pw-tower tr.active td { box-shadow: inset 0 1px 0 #fff, inset 0 -1px 0 #fff; }
  .pw-root .pw-tower tr.active td:first-child { box-shadow: inset 0 1px 0 #fff, inset 0 -1px 0 #fff, inset 1px 0 0 #fff; }
  .pw-root .pw-tower tr.active td:last-child { box-shadow: inset 0 1px 0 #fff, inset 0 -1px 0 #fff, inset -1px 0 0 #fff; }
  .pw-root .pw-tower tr.inpit td { opacity: 0.6; }
  .pw-root .pw-tower tr.dnf td { opacity: 0.35; }
  .pw-tpos-cell { width: 34px; text-align: center; }
  .pw-tpos { display: inline-flex; align-items: center; justify-content: center; width: 100%; height: 29px; font-weight: 900; font-size: 14px; background: #0a0a10; border-radius: 3px 0 0 3px; }
  .pw-tower tr:nth-child(1) .pw-tpos { background: #fff; color: #111; }
  .pw-tdriver { padding-left: 0 !important; }
  .pw-tdriver .pw-tbar { display: inline-block; width: 4px; height: 17px; border-radius: 1px; vertical-align: middle; margin: 0 8px 0 8px; transform: skewX(-12deg); }
  .pw-tcode { font-weight: 900; font-size: 14px; letter-spacing: 0.06em; vertical-align: middle; }
  .pw-root .pw-tdriver .pw-carno { margin-left: 5px; font-size: 10.5px; vertical-align: middle; }
  .pw-tgap { text-align: right; font-weight: 600; color: #e9e9f2; padding: 0 8px !important; }
  .pw-tower tr:nth-child(1) .pw-tgap { color: var(--ok); font-size: 10.5px; letter-spacing: 0.1em; font-weight: 800; }
  .pw-tlast { text-align: right; color: var(--muted); padding: 0 6px !important; font-size: 12px; }
  .pw-ttyre { text-align: left; }
  .pw-tyrebadge {
    display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px; border-radius: 50%;
    border: 3px solid; font-size: 9.5px; font-weight: 900; vertical-align: middle; background: #0a0a10; margin-left: 4px;
  }
  .pw-tyreage { font-size: 11.5px; margin-left: 4px; vertical-align: middle; font-weight: 600; }
  .pw-tyreage small { color: var(--muted); font-size: 9px; margin-left: 1px; }
  .pw-tint { text-align: right; color: #9fe3c7; padding: 0 6px !important; font-size: 12px; font-weight: 600; }
  .pw-tpits { text-align: center; font-weight: 800; color: #fff; padding: 0 8px !important; }
  .pw-pitcount { margin-left: 4px; font-size: 10.5px; color: var(--muted); font-weight: 700; vertical-align: middle; }
  .pw-root .pw-pit-tag { background: var(--accent); color: #fff; border-radius: 2px; vertical-align: middle; }
  .pw-root .pw-pen-tag, .pw-root .pw-tl-tag { vertical-align: middle; }

  /* Circuit */
  .pw-root .pw-trackwrap { background: radial-gradient(ellipse at center, #0f0f17 0%, #08080d 100%); border: 1px solid var(--line); border-radius: 4px; padding: 4px; }
  .pw-root .pw-tracksvg { height: auto; aspect-ratio: 1000 / 600; max-height: 70vh; }
  .pw-root .pw-track-pos { fill: #fff; font-weight: 900; font-size: 15px; paint-order: stroke; stroke: #0a0a10; stroke-width: 4px; stroke-linejoin: round; }
  .pw-root .pw-track-pit { fill: #fff; paint-order: stroke; stroke: var(--accent); stroke-width: 4px; stroke-linejoin: round; }
  .pw-root .pw-weather { background: #0a0a10; border: 1px solid var(--line); border-radius: 4px; padding: 6px 10px; margin-top: 8px; }
  .pw-root .pw-weather-pill { border-radius: 3px; font-weight: 800; letter-spacing: 0.1em; }
  .pw-root .pw-weather-pill.dry { background: rgba(255,214,10,0.16); color: #ffd60a; }
  .pw-root .pw-weather-pill.caution { background: #ffd60a; color: #111; }
  .pw-root .pw-rainbar { height: 4px; border-radius: 0; }

  /* Strategy & pit wall */
  .pw-root .pw-cartab { border-radius: 3px; background: #0a0a10; font-weight: 700; }
  .pw-root .pw-cartab.active { border-color: #fff; color: #fff; box-shadow: inset 0 -3px 0 var(--accent); }
  .pw-root .pw-mode-btn, .pw-root .pw-tyre-btn { border-radius: 3px; background: #0a0a10; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; font-size: 11px; }
  .pw-root .pw-mode-btn.active { background: var(--accent); border-color: var(--accent-text); color: #fff; }
  .pw-root .pw-tyre-btn:hover:not(:disabled) { background: #22222f; }
  .pw-root .pw-control-label { color: var(--muted); letter-spacing: 0.14em; font-weight: 700; }
  .pw-root .pw-pit-pending { background: rgba(225,6,0,0.14); color: #ff8a80; border-radius: 3px; border-left: 3px solid var(--accent); }
  .pw-root .pw-cancel { color: #fff; border-color: #fff; border-radius: 3px; }
  .pw-root .pw-cliffwarn { border-radius: 3px; border-left: 3px solid var(--danger); }
  .pw-root .pw-undercut { border-radius: 3px; }
  .pw-root .pw-carno { color: var(--muted); }

  /* Race feed */
  .pw-root .pw-filter-btn { border-radius: 3px; background: #0a0a10; text-transform: uppercase; letter-spacing: 0.08em; font-size: 10.5px; font-weight: 700; }
  .pw-root .pw-filter-btn.active { background: #fff; border-color: #fff; color: #111; }
  .pw-root .pw-eventlog { max-height: 200px; }
  .pw-root .pw-event-row { background: #1a1a25; border-bottom: none; margin-bottom: 2px; border-left-width: 4px; border-radius: 0 3px 3px 0; align-items: center; }
  .pw-root .pw-event-lap { color: #fff; background: #0a0a10; border-radius: 2px; text-align: center; padding: 1px 0; font-size: 11px; width: 34px; }

  /* Chequered flag overlay */
  .pw-root .pw-overlay { background: rgba(6,6,10,0.88); backdrop-filter: blur(3px); }
  .pw-root .pw-results { background: #15151e; border: 1px solid var(--line); border-radius: 6px; padding: 0 0 20px; overflow: hidden; max-width: 520px; }
  .pw-root .pw-results::before {
    content: ""; display: block; height: 14px;
    background: repeating-conic-gradient(#fff 0 25%, #111 0 50%) 0 0 / 14px 14px;
  }
  .pw-root .pw-results h2 { color: #fff; font-size: 22px; font-weight: 900; letter-spacing: 0.12em; padding: 16px 24px 4px; margin: 0 0 8px; }
  .pw-root .pw-podium-list { padding: 0 20px; }
  .pw-root .pw-podium-list li { background: #1d1d29; border: none; border-radius: 3px; margin-bottom: 3px; padding: 0 12px 0 0; height: 32px; }
  .pw-root .pw-podium-list li.player { color: #fff; background: linear-gradient(90deg, rgba(225,6,0,0.35), #1d1d29); }
  .pw-root .pw-podium-list .pw-pos { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 32px; background: #0a0a10; color: #fff; font-weight: 900; border-radius: 3px 0 0 3px; }
  .pw-root .pw-podium-list li:nth-child(1) .pw-pos { background: #fff; color: #111; }
  .pw-root .pw-podium-list li:nth-child(2) .pw-pos { background: #c0c0cc; color: #111; }
  .pw-root .pw-podium-list li:nth-child(3) .pw-pos { background: #cd7f32; color: #111; }
  .pw-root .pw-results-actions { padding: 0 20px; }
  .pw-root .pw-start-btn { background: var(--accent); color: #fff; border-radius: 3px; text-transform: uppercase; letter-spacing: 0.08em; }
  .pw-root .pw-secondary-btn { border-radius: 3px; text-transform: uppercase; letter-spacing: 0.08em; font-size: 12px; }

`;
